fun s_of_n_creator(n: Int): (Int) -> List<Int> {
    var sample = mutableListOf<Int>()
    var i = 0
    return { item: Int ->
        i += 1
        if (i <= n) {
            sample.add(item)
        } else if (Math.random() * i < n) {
            sample[Math.random() * n.toDouble()].toInt() = item
        }
        sample
    }
}
 
val frequency = IntArray(10)
for (i in 1..100_000) {
    val s_of_n = s_of_n_creator(3)
    var sample: List<Int>? = null
    for (digit in 0..9) {
        sample = s_of_n(digit)
    }
    sample?.forEach { digit -> frequency[digit] += 1 }
}
 
