import java.math.BigInteger
import java.math.BigDecimal
import java.math.MathContext
 
fun bernoulli(n: Int): BigDecimal {
    val a = Array(n + 1) { BigDecimal.ZERO }
    var z = BigDecimal.ZERO
    for (m in a.indices) {
        a[m] = BigDecimal.ONE.divide(BigDecimal(m + 1), MathContext.DECIMAL128)
        for (j in m downTo 1) {
            val d = a[j - 1]
            a[j - 1] = d.multiply(BigDecimal(j)).subtract(a[j])
        }
    }
    // return the 'first' Bernoulli number
    return if (n!= 1) a[0] else a[0].negate()
}
 
fun binomial(n: Int, k: Int): BigInteger {
    if (n <= 0 || k <= 0 || n < k) {
        return BigInteger.ONE
    }
    var num = BigInteger.ONE
    var den = BigInteger.ONE
    for (i in k + 1..n) {
        num = num.multiply(BigInteger.valueOf(i.toLong()))
    }
    for (i in 2..n - k) {
        den = den.multiply(BigInteger.valueOf(i.toLong()))
    }
    return num.divide(den)
}
 
fun faulhaberTriangle(p: Int): Array<BigDecimal> {
    val coeffs = Array(p + 1) { BigDecimal.ZERO }
    val q = BigDecimal.ONE.divide(BigDecimal(p + 1), MathContext.DECIMAL128)
    var t = BigDecimal.ZERO
    var u = BigDecimal.ZERO
    var sign = -1
    for (j in coeffs.indices) {
        sign *= -1
        val d = coeffs[p - j]
        t = BigDecimal(sign)
        u = BigDecimal(binomial(p + 1, j))
        d.multiply(q)
        d.multiply(t)
        d.multiply(u)
        d.multiply(bernoulli(j))
    }
    return coeffs
}
 
fun main() {
    for (i in 0 until 10) {
        val coeffs = faulhaberTriangle(i)
        for (coeff in coeffs) {
            print(coeff.toPlainString() + "  ")
        }
        println()
    }
    println()
    // get coeffs for (k + 1)th row
    val k = 17
    val cc = faulhaberTriangle(k)
    val n = 1000
    val nn = BigDecimal(n)
    var np = BigDecimal.ONE
    var sum = BigDecimal.ZERO
    var tmp = BigDecimal.ZERO
    for (c in cc) {
        np = np.multiply(nn)
        tmp = np.multiply(c)
        sum = sum.add(tmp)
    }
    println(sum.toPlainString())
};1

