val a1 = intArrayOf(0, 1403580, -810728)
val a2 = intArrayOf(527612, 0, -1370589)
 
const val m1 = (1.0.pow(32.0) - 209).toInt()
const val m2 = (1.0.pow(32.0) - 22853).toInt()
const val d = m1 + 1
 
// Python style modulus
fun mod(x: Int, y: Int): Int {
    val m = x % y
    return if (m < 0) {
        if (y < 0) {
            m - y
        } else {
            m + y
        }
    } else {
        m
    }
}
 
class MRG32k3a {
    var x1 = intArrayOf(0, 0, 0)
    var x2 = intArrayOf(0, 0, 0)
 
    fun seed(seedState: Int) {
        if (seedState <= 0 || seedState >= d) {
            throw IllegalArgumentException("Argument must be in the range [0, $d].")
        }
        x1 = intArrayOf(seedState, 0, 0)
        x2 = intArrayOf(seedState, 0, 0)
    }
 
    fun nextInt(): Int {
        val x1i = mod(a1[0] * x1[0] + a1[1] * x1[1] + a1[2] * x1[2], m1)
        val x2i = mod(a2[0] * x2[0] + a2[1] * x2[1] + a2[2] * x2[2], m2)
        x1 = intArrayOf(x1i, x1[0], x1[1]) // keep last three
        x2 = intArrayOf(x2i, x2[0], x2[1]) // keep last three
        return mod(x1i - x2i, m1) + 1
    }
 
    fun nextFloat(): Double = nextInt().toDouble() / d
}
 
fun main() {
    val randomGen = MRG32k3a()
    randomGen.seed(1234567)
    for (i in 0 until 5) {
        println(randomGen.nextInt())
    }
 
    val counts = IntArray(5)
    randomGen.seed(987654321)
    for (i in 0 until 100_000) {
        val j = floor(randomGen.nextFloat() * 5).toInt()
        counts[j]++
    }
    println("\nThe counts for 100,000 repetitions are:")
    for (i in 0 until 5) {
        println("  $i : ${counts[i]}")
    }
};1

import java.util.HashSet
import java.util.LinkedList
import java.util.Queue
 
class Sokoban(level: String) {
    private val board: String
    private val goal: List<Int>
    private val nrows: Int
    private val px: Int
    private val py: Int
 
    init {
        val board = level.lines().map { it.trimEnd() }
        nrows = board.map { it.length }.max()!!
        board.map { it.padEnd(nrows) }
        board.forEachIndexed { r, row ->
            row.forEachIndexed { c, ch ->
                if (ch == '@' || ch == '+') {
                    px = c
                    py = r
                }
            }
        }
        goal = board.joinToString("").replace(Regex("[.@#\\$\\+\\*]"), " ").toCharArray().withIndex().filter { it.value == '.' }.map { it.index }
        board = board.joinToString("").replace(Regex("[.@#\\$\\+\\*]"), "  @#$ $")
    }
 
    fun pos(x: Int, y: Int): Int {
        return y * nrows + x
    }
 
    fun push(x: Int, y: Int, dx: Int, dy: Int, board: String): Boolean {
        if (board[pos(x + 2 * dx, y + 2 * dy)]!='') {
            return false
        }
        board[pos(x, y)] =''
        board[pos(x + dx, y + dy)] = '@'
        board[pos(x + 2 * dx, y + 2 * dy)] = '$'
        return true
    }
 
    fun solved(board: String): Boolean {
        return goal.all { board[it] == '$' }
    }
 
    private val DIRS = arrayOf(intArrayOf(0, -1, 'u', 'U'), intArrayOf(1, 0, 'r', 'R'), intArrayOf(0, 1, 'd', 'D'), intArrayOf(-1, 0, 'l', 'L'))
    fun solve(): String {
        val queue: Queue<Array<Any>> = LinkedList()
        queue.add(arrayOf(board, "", px, py))
        val visited = HashSet<String>()
        visited.add(board)
 
        while (!queue.isEmpty()) {
            val current = queue.poll()
            val csol = current[1] as String
            val x = current[2] as Int
            val y = current[3] as Int
 
            for (dir in DIRS) {
                val dx = dir[0]
                val dy = dir[1]
                val cmove = dir[2]
                val cpush = dir[3]
                val work = current[0].toString()
                when (work[pos(x + dx, y + dy)]) {
                    '$' -> {
                        if (!push(x, y, dx, dy, work)) {
                            continue
                        }
                        if (!visited.add(work)) {
                            continue
                        }
                        if (solved(work)) {
                            return csol + cpush
                        }
                        queue.add(arrayOf(work, csol + cpush, x + dx, y + dy));1

fun findSensitiveStrings(strings: List<String>, sensitiveWords: Set<String>): List<String> {
    val result = mutableListOf<String>()
    val loweredSensitive = sensitiveWords.map { it.lowercase() }.toSet()
    for (s in strings) {
        val lowerS = s.lowercase()
        for (word in loweredSensitive) {
            if (lowerS.contains(word)) {
                result.add(s)
                break
            }
        }
    }
    return result
};1

