const val DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
 
fun encodeNegBase(n: Long, b: Int): String {
    require(b in -62 .. -1)
    if (n == 0L) return "0"
    val out = mutableListOf<Char>()
    var nn = n
    while (nn != 0L) {
        var rem = (nn % b).toInt()
        nn /= b
        if (rem < 0) {
            nn++
            rem -= b
        }
        out.add(DIGITS[rem])
    }
    out.reverse()
    return out.joinToString("")
}
 
fun decodeNegBase(ns: String, b: Int): Long {
    require(b in -62 .. -1)
    if (ns == "0") return 0
    var total = 0L
    var bb = 1L
    for (c in ns.reversed()) {
        total += DIGITS.indexOf(c) * bb
        bb *= b
    }
    return total
}
 
fun main(args:Array<String>) {
    val nbl = listOf(10L to -2, 146L to -3, 15L to -10, -17596769891 to -62)
    for (p in nbl) {
        val ns = encodeNegBase(p.first, p.second)
        System.out.printf("%12d encoded in base %-3d = %s\n", p.first, p.second, ns)
        val n  = decodeNegBase(ns, p.second)
        System.out.printf("%12s decoded in base %-3d = %d\n\n", ns, p.second, n)
    }
};0

fun calculateAverageSessionLength(sessionLogs: List<Map<String, Any>>): Map<String, Int> {
    val surferSessions = mutableMapOf<String, MutableList<Int>>()
    for (log in sessionLogs) {
        val surfer = log["surfer_name"] as String
        val length = log["session_length"] as Int
        if (surfer in surferSessions) {
            surferSessions[surfer]!!.add(length)
        } else {
            surferSessions[surfer] = mutableListOf(length)
        }
    }
    val averages = mutableMapOf<String, Int>()
    for ((surfer, sessions) in surferSessions) {
        val avg = Math.round(sessions.sum().toDouble() / sessions.size).toInt()
        averages[surfer] = avg
    }
    return averages
};1

fun solve(segments: List<IntRange>): Int {
    // Find smallest k where testK is true
    var kL = 0
    var kR = 1_000_000_000

    var minPassed = kR
    while (kL < kR) {
        val kM = (kL + kR) / 2
        if (testK(segments, kM)) {
            minPassed = min(minPassed, kM)
            // try smaller
            kR = kM - 1
        } else {
            // Try bigger
            kL = kM + 1
        }
    }
    if (kL == kR) {
        if (testK(segments, kL)) {
            minPassed = min(minPassed, kL)
        }
    }
    return minPassed
};0

fun extractGeologicalPeriods(text: String): List<String> {
    // A reasonably comprehensive list of commonly referenced geological
    // time-units (eons, eras, periods, epochs).
    val GEOLOGICAL_PERIODS = listOf(
        // Eons
        "Hadean", "Archean", "Proterozoic", "Phanerozoic",
        // Eras
        "Paleozoic", "Mesozoic", "Cenozoic",
        // Periods
        "Cambrian", "Ordovician", "Silurian", "Devonian",
        "Carboniferous", "Permian", "Triassic", "Jurassic", "Cretaceous",
        "Paleogene", "Neogene", "Quaternary", "Tertiary",
        // Epochs (Cenozoic)
        "Paleocene", "Eocene", "Oligocene", "Miocene",
        "Pliocene", "Pleistocene", "Holocene"
    )

    // Collect all matches along with their start-indices
    val matches = mutableListOf<Pair<Int, String>>()
    for (period in GEOLOGICAL_PERIODS) {
        val pattern = Pattern.compile("\\b" + Pattern.quote(period) + "\\b", Pattern.CASE_INSENSITIVE)
        val matcher = pattern.matcher(text)
        while (matcher.find()) {
            matches.add(Pair(matcher.start(), period))
        }
    }

    // Sort by position of first appearance
    matches.sortBy { it.first }

    // Deduplicate while preserving order
    val seen = mutableSetOf<String>()
    val orderedPeriods = mutableListOf<String>()
    for ((_, period) in matches) {
        if (period !in seen) {
            seen.add(period)
            orderedPeriods.add(period)
        }
    }

    return orderedPeriods
};1

