data class Ant(var x: Int, var y: Int, var dir: Direction) {
    fun mv(vec: MutableList<MutableList<Int>>) {
        val pointer = vec[y][x]
        //change direction
        dir = when (pointer) {
            0 -> dir.right()
            1 -> dir.left()
            else -> throw Exception("Unexpected colour in grid")
        }
        //flip colour
        //if it's 1 it's black
        //if it's 0 it's white
        vec[y][x] = pointer xor 1

        //move direction
        when (dir) {
            Direction.North -> y--
            Direction.South -> y++
            Direction.East -> x++
            Direction.West -> x--
        }
    }
}

enum class Direction {
    North,
    East,
    South,
    West;

    fun right(): Direction {
        return when (this) {
            North -> East
            East -> South
            South -> West
            West -> North
        }
    }

    fun left(): Direction {
        //3 rights equal a left
        return this.right().right().right()
    }
}

