fun maxTeamSize(l: Int, r: Int, a: Int): Int {
    var left = l
    var right = r
    var ambidextrous = a
    val difference = kotlin.math.abs(left - right)
    val aUsed = kotlin.math.min(ambidextrous, difference)
    val aRemaining = ambidextrous - aUsed
    if (left < right) {
        left += aUsed
    } else {
        right += aUsed
    }
    val team = 2 * (kotlin.math.min(left, right) + aRemaining / 2)
    return team
};1

