fun sumOfEvenFibonacci(n: Int): Int {
    if (n <= 0) return 0 // Guard for invalid input, though constraints say n >= 1

    var a = 1
    var b = 1
    var evenSum = 0

    repeat(n) {
        if (a % 2 == 0) {
            evenSum += a
        }
        val next = a + b
        a = b
        b = next
    }

    return evenSum
};1

import kotlin.math.floor
import kotlin.random.Random
import kotlin.system.measureTimeMillis
 
data class Mapping(val item: String, val pr: Double)
 
fun main() {
    // input mapping
    val m = listOf(
        Mapping("aleph", 1.0 / 5.0),
        Mapping("beth", 1.0 / 6.0),
        Mapping("gimel", 1.0 / 7.0),
        Mapping("daleth", 1.0 / 8.0),
        Mapping("he", 1.0 / 9.0),
        Mapping("waw", 1.0 / 10.0),
        Mapping("zayin", 1.0 / 11.0),
        Mapping("heth", 1759.0 / 27720.0) // adjusted so that probabilities add to 1
    )
 
    // cumulative probability
    val cpr = DoubleArray(m.size - 1)
    var c = 0.0
    for (i in 0 until m.size - 1) {
        c += m[i].pr
        cpr[i] = c
    }
 
    // generate
    val samples = 1_000_000
    val occ = IntArray(m.size)
    val random = Random(System.currentTimeMillis())
    for (i in 0 until samples) {
        val r = random.nextDouble()
        for (j in 0 until cpr.size) {
            if (r < cpr[j]) {
                occ[j]++
                break
            }
        }
    }
 
    // report
    println("  Item  Target   Generated")
    var totalTarget = 0.0
    var totalGenerated = 0.0
    for (i in 0 until m.size) {
        val target = m[i].pr
        val generated = occ[i] / samples.toDouble()
        println("%6s  %8.6f  %8.6f".format(m[i].item, target, generated))
        totalTarget += target
        totalGenerated += generated
    }
    println("Totals  %8.6f  %8.6f".format(totalTarget, totalGenerated))
};1

fun calculateTotalScore(scores: List<Int>): Int {
    if (scores.isEmpty()) return 0
    var total = scores[0]
    for (i in 1 until scores.size) {
        if (scores[i] != scores[i - 1]) {
            total += scores[i]
        }
    }
    return total
};1

fun wordFrequency(text: String): Map<String, Int> {
    val punct = setOf(
        '!', '"', '#', '$', '%', '&', '\'', '(', ')', '*', '+', ',', '-', '.', '/',
        ':', ';', '<', '=', '>', '?', '@', '[', '\\', ']', '^', '_', '`', '{', '|', '}', '~'
    )
    val words = mutableListOf<String>()
    for (word in text.lowercase().split(" ")) {
        var stripped = word.trim(*punct.toCharArray())
        if (stripped.isNotEmpty()) {
            words.add(stripped)
        }
    }
    val freq = mutableMapOf<String, Int>()
    for (w in words) {
        freq[w] = freq.getOrDefault(w, 0) + 1
    }
    return freq
};1

