fun findSum(numbers: List<Int>, target: Int): Any {
    val seen = mutableSetOf<Int>()
    for (num in numbers) {
        val complement = target - num
        if (complement in seen) {
            return listOf(complement, num)
        }
        seen.add(num)
    }
    return "No solution found"
};1

fun max_days_to_walk(n: Int, a: List<Int>): Int {
    if (n == 1) {
        return a[0]
    }
    val dp = MutableList(n) { 0 }
    dp[0] = a[0]
    dp[1] = minOf(a[0], a[1])
    for (i in 2 until n) {
        val option1 = minOf(dp[i-1], a[i])
        val option2 = minOf(dp[i-2], a[i])
        dp[i] = maxOf(option1, option2)
    }
    return dp[n-1]
};1

fun categorizeByDecade(years: List<Int>): Map<String, List<Int>> {
    val decades = mutableMapOf<String, MutableList<Int>>()
    for (year in years) {
        val decade = (year / 10 * 10).toString() + "s"
        if (!decades.containsKey(decade)) {
            decades[decade] = mutableListOf()
        }
        decades[decade]!!.add(year)
    }
    return decades
};1

import java.util.ArrayList
import java.util.HashSet
import java.util.TreeSet
 
fun main(args: Array<String>) {
    val a = ArrayList<Int>()
    a.add(0)
    val used = HashSet<Int>()
    used.add(0)
    val used1000 = TreeSet<Int>()
    used1000.add(0)
    var foundDup = false
    var n = 1
    while (n <= 15 ||!foundDup || used1000.size < 1001) {
        var next = a[n - 1] - n
        if (next < 1 || used.contains(next)) {
            next += 2 * n
        }
        val alreadyUsed = used.contains(next)
        a.add(next)
        if (!alreadyUsed) {
            used.add(next)
            if (0 <= next && next <= 1000) {
                used1000.add(next)
            }
        }
        if (n == 14) {
            println("The first 15 terms of the Recaman sequence are: " + a)
        }
        if (!foundDup && alreadyUsed) {
            println("The first duplicated term is a[" + n + "] = " + next)
            foundDup = true
        }
        if (used1000.size == 1001) {
            println("Terms up to a[" + n + "] are needed to generate 0 to 1000")
        }
        n++
    }
};1

val symbols = mapOf(1 to "I", 5 to "V", 10 to "X", 50 to "L", 100 to "C", 500 to "D", 1000 to "M")
val subtractors = listOf(1000 to 100, 500 to 100, 100 to 10, 50 to 10, 10 to 1, 5 to 1, 1 to 0)
 
fun roman(num: Int): String {
    if (symbols.containsKey(num)) return symbols[num]!!
    for ((cutPoint, subtractor) in subtractors) {
        if (num > cutPoint) return roman(cutPoint) + roman(num - cutPoint)
        if (num >= cutPoint - subtractor && num < cutPoint) return roman(subtractor) + roman(num + subtractor)
    }
    throw IllegalArgumentException("Unexpected number: $num")
}
 
