fun maxProductThree(nums: List<Int>): Int {
    if (nums.size < 3) {
        throw IllegalArgumentException("Need at least three numbers to compute a 3-element product.")
    }
    val sortedNums = nums.sorted()
    val n = sortedNums.size

    val productLargestThree = sortedNums[n - 1] * sortedNums[n - 2] * sortedNums[n - 3]
    val productTwoSmallestOneLargest = sortedNums[0] * sortedNums[1] * sortedNums[n - 1]

    return maxOf(productLargestThree, productTwoSmallestOneLargest)
};1

