// The sieve of Eratosthenes optimized
fun primes(n: Long): List<Int> {
    val sieveBound = ((n - 1) / 2).toInt()
    val sieve = Array(sieveBound) { true }
    val crosslimit = (floor(sqrt(n.toDouble())).toInt() - 1) / 2

    for (i in 1..crosslimit) {
        if (!sieve[i-1]) continue
        for (j in (2 * i * (i + 1)) .. sieveBound step 2 * i + 1) {
            sieve[j-1] = false
        }
    }

    return listOf(2) + sieve.mapIndexedNotNull { i, isPrime -> if (isPrime) 2 * (i + 1) + 1 else null }
};0

fun createTicket(ticketDetails: Map<String, Any>): Map<String, Any> {
    val requiredKeys = setOf("title", "description", "priority")
    val missing = requiredKeys - ticketDetails.keys
    if (missing.isNotEmpty()) {
        throw NoSuchElementException("Missing required ticket field(s): ${missing.joinToString(", ")}")
    }

    val title = ticketDetails["title"]
    val description = ticketDetails["description"]
    val priority = ticketDetails["priority"]

    if (title !is String) {
        throw IllegalArgumentException("Field 'title' must be a string.")
    }
    if (description !is String) {
        throw IllegalArgumentException("Field 'description' must be a string.")
    }
    if (priority !is String || priority !in setOf("low", "medium", "high")) {
        throw IllegalArgumentException("Field 'priority' must be one of: 'low', 'medium', 'high'.")
    }

    return mapOf(
        "title" to title,
        "description" to description,
        "priority" to priority
    )
};1

