fun vc(n: Int, base: Int, num: IntArray, denom: IntArray) {
    var p = 0
    var q = 1
    while (n!= 0) {
        p = p * base + (n % base)
        q *= base
        n /= base
    }
    num[0] = p
    denom[0] = q
    var n = p
    while (p!= 0) {
        p = q % p
        q = n
    }
    num[0] /= q
    denom[0] /= q
}
 
