fun farey(n: Int, length: Boolean = false): Any {
    if (length) {
        return (n * (n + 3)) / 2 - (2..n).sum { farey(n / it, true) }
    } else {
        return (1..n).flatMap { k -> (0..k).map { m -> m.toLong() / k } }.distinct().sorted()
    }
}
 
