fun xor(a: Byte, b: Byte): Byte {
    return a and (b.inv()) or (b and a.inv())
}
 
fun ha(a: Byte, b: Byte): Pair<Byte, Byte> {
    return Pair(xor(a, b), a and b)
}
 
fun fa(a: Byte, b: Byte, c0: Byte): Pair<Byte, Byte> {
    val (sa, ca) = ha(a, c0)
    val (s, cb) = ha(sa, b)
    return Pair(s, ca or cb)
}
 
fun add4(a3: Byte, a2: Byte, a1: Byte, a0: Byte, b3: Byte, b2: Byte, b1: Byte, b0: Byte): Pair<Byte, Pair<Byte, Pair<Byte, Pair<Byte, Byte>>>> {
    val (s0, c0) = fa(a0, b0, 0)
    val (s1, c1) = fa(a1, b1, c0)
    val (s2, c2) = fa(a2, b2, c1)
    val (s3, v) = fa(a3, b3, c2)
    return Pair(v, Pair(s3, Pair(s2, Pair(s1, s0))))
}
 
