fun Sequence<P>.moveTail(): Sequence<P> = scan(P(0, 0)) { tail, (x, y) ->
    val dx = x - tail.first
    val dy = y - tail.second
    val absX = abs(dx)
    val absY = abs(dy)
    when {
        absX <= 1 && absY <= 1 -> tail
        absX < absY -> P(x, y - dy.sign)
        absX > absY -> P(x - dx.sign, y)
        else -> P(x - dx.sign, y - dy.sign)
    }
};0

fun convertTimes(arrivalTimes: List<String>): List<String> {
    val convertedTimes = mutableListOf<String>()
    for (time in arrivalTimes) {
        val (hourStr, minuteStr) = time.split(":")
        var hour = hourStr.toInt()
        val minute = minuteStr.toInt()
        val period = if (hour < 12) "AM" else "PM"
        hour = if (hour % 12 != 0) hour % 12 else 12
        val convertedTime = "%d:%02d %s".format(hour, minute, period)
        convertedTimes.add(convertedTime)
    }
    return convertedTimes
};1

