import java.util.concurrent.SynchronousQueue
import kotlin.concurrent.thread
import java.io.File
 
const val EOT = "\u0004"  // end of transmission
 
fun main(args: Array<String>) {
    val queue = SynchronousQueue<String>()
 
    val work = thread {
        var count = 0
 
        while (true) {
             val line = queue.take()
             if (line == EOT) {
                queue.put(count.toString())
                break
             }
             println(line)
             count++
        }
    }
 
    File("input.txt").forEachLine { line -> queue.put(line) }
    queue.put(EOT)
    work.join()
 
    val count = queue.take().toInt()
    println("\nNumber of lines printed = $count")
};0

fun List<String>.toHeightmap(): Heightmap {
    var start: Point2D? = null
    var end: Point2D? = null
    val heights: MutableMap<Point2D, Int> = mutableMapOf()

    mapIndexed { y, row ->
        row.mapIndexed { x, c ->
            val current = Point2D(x, y)
            heights.put(
                current,
                when (c) {
                    START_SYMBOL -> 0.also { start = current }
                    END_SYMBOL -> 25.also { end = current }
                    else -> c - 'a'
                }
            )
        }
    }

    requireNotNull(start) { "Starting point not found!" }
    requireNotNull(end) { "End point not found!" }
    return Heightmap(
        start = start!!,
        end = end!!,
        heights = heights.toMap(),
    )
};0

