class TreeNode(var `val`: Int = 0, var left: TreeNode? = null, var right: TreeNode? = null)

fun widthAndSum(root: TreeNode?): List<Int> {
    if (root == null) return listOf(0, 0)
    // Each element in the queue is a Pair(node, index)
    val q: Queue<Pair<TreeNode, Int>> = LinkedList()
    q.add(Pair(root, 0))
    var maxWidth = 0
    var maxSum = root.`val`

    while (q.isNotEmpty()) {
        val levelLen = q.size
        val firstIdx = q.peek().second
        var levelSum = 0
        var first = 0
        var last = 0

        for (i in 0 until levelLen) {
            val (node, idxRaw) = q.remove()
            val idx = idxRaw - firstIdx
            if (i == 0) first = idx
            if (i == levelLen - 1) last = idx

            levelSum += node.`val`
            if (node.left != null) {
                q.add(Pair(node.left!!, 2 * idx))
            }
            if (node.right != null) {
                q.add(Pair(node.right!!, 2 * idx + 1))
            }
        }
        val width = last - first + 1
        if (width > maxWidth || (width == maxWidth && levelSum > maxSum)) {
            maxWidth = width
            maxSum = levelSum
        }
    }
    return listOf(maxWidth, maxSum)
};1

fun makeNonDecreasing(n: Int, a: List<Int>): List<Pair<Int, Int>> {
    val arr = a.toMutableList()
    val operations = mutableListOf<Pair<Int, Int>>()
    val maxVal = arr.maxOrNull() ?: 0
    if (maxVal > 0) {
        val m = arr.indexOf(maxVal)
        for (i in (m + 1) until n) {
            operations.add(Pair(m + 1, i + 1))
            arr[i] += maxVal
        }
        for (i in 0 until n - 1) {
            if (arr[i] > arr[i + 1]) {
                operations.add(Pair(i + 1, i + 2))
                arr[i + 1] += arr[i]
            }
        }
    } else {
        val minVal = arr.minOrNull() ?: 0
        val m = arr.indexOf(minVal)
        for (i in 0 until m) {
            operations.add(Pair(m + 1, i + 1))
            arr[i] += minVal
        }
        for (i in (n - 1) downTo 1) {
            if (arr[i - 1] > arr[i]) {
                operations.add(Pair(i + 1, i))
                arr[i - 1] += arr[i]
            }
        }
    }
    return operations
};1

class TreeNode(var `val`: Int, var left: TreeNode? = null, var right: TreeNode? = null)

fun closestValue(root: TreeNode, target: Double): Int {
    var closest = root.`val`
    var current: TreeNode? = root
    while (current != null) {
        if (kotlin.math.abs(current.`val` - target) < kotlin.math.abs(closest - target)) {
            closest = current.`val`
        }
        if (current.`val`.toDouble() == target) {
            break
        }
        current = if (target < current.`val`.toDouble()) {
            current.left
        } else {
            current.right
        }
    }
    return closest
};1

fun getDeviceTemperature(deviceId: String, devices: List<Map<String, Any>>): Double? {
    val tempTraitKey = "sdm.devices.traits.Temperature"
    val tempValueKey = "ambientTemperatureCelsius"

    for (device in devices) {
        val name = device["name"] as? String ?: ""
        if (name == deviceId || name.endsWith("/$deviceId")) {
            val traits = device["traits"] as? Map<*, *> ?: emptyMap<String, Any>()
            val tempTrait = traits[tempTraitKey] as? Map<*, *> ?: emptyMap<String, Any>()
            val temperature = tempTrait[tempValueKey]
            return when (temperature) {
                is Int -> temperature.toDouble()
                is Double -> temperature
                else -> null
            }
        }
    }
    return null
};1

fun setDefaults(schema: Map<String, Any>, userProperties: MutableMap<String, Any>): MutableMap<String, Any> {
    fun applyDefaults(sch: Map<String, Any>, target: MutableMap<String, Any>) {
        for ((key, defaultVal) in sch) {
            if (key == "required") continue
            try {
                if (defaultVal is Map<*, *>) {
                    @Suppress("UNCHECKED_CAST")
                    val defaultMap = defaultVal as Map<String, Any>
                    if (target.containsKey(key) && target[key] is MutableMap<*, *>) {
                        val nestedTarget = target[key] as MutableMap<String, Any>
                        applyDefaults(defaultMap, nestedTarget)
                    } else if (!target.containsKey(key)) {
                        val newMap = mutableMapOf<String, Any>()
                        applyDefaults(defaultMap, newMap)
                        target[key] = newMap
                    }
                    // else: key exists but not a map; do nothing
                } else {
                    if (!target.containsKey(key)) {
                        target[key] = defaultVal
                    }
                }
            } catch (e: Exception) {
                // Silence all errors
            }
        }
    }
    applyDefaults(schema, userProperties)
    return userProperties
};1

