fun sumColumns(inputStr: String): List<Double> {
    // Regular expression to capture a (possibly signed) floating-point number,
    // with optional exponent part.
    val numberPattern = Pattern.compile("[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?")

    // Early return for completely empty or whitespace-only input
    if (inputStr.trim().isEmpty()) {
        return emptyList()
    }

    // Prepare list that will hold the cumulative sums for each column
    val columnSums = mutableListOf<Double>()

    // Iterate over each row in the input string
    for (row in inputStr.trim().split("\n")) {
        // Split the row into cells by comma; empty strings represent empty cells
        val cells = row.split(",")

        // Ensure columnSums is long enough for the current row
        if (cells.size > columnSums.size) {
            repeat(cells.size - columnSums.size) {
                columnSums.add(0.0)
            }
        }

        // Process each cell
        for ((idx, cell) in cells.withIndex()) {
            val matcher = numberPattern.matcher(cell)
            val value = if (matcher.find()) matcher.group().toDouble() else 0.0
            columnSums[idx] = columnSums[idx] + value
        }
    }
    return columnSums
};1

