fun day4Part1(callNums: List<Int>, boards: List<Board>): Int {
    var finalNum = 0
    var unmarkedSum = 0
    outer@ for (num in callNums) {
        finalNum = num
        for (board in boards) {
            board.markSquare(num)
            if (board.isWinner()) {
                unmarkedSum = board.getUnmarkedSum()
                break@outer
            }
        }
    }
    return finalNum * unmarkedSum
