fun bfsWeighted(n: Int, adj: List<List<Pair<Int, Int>>>, root: Int): List<Int> {
    val visited = BooleanArray(n + 1) { false }
    val queue = ArrayDeque<Int>()
    queue.add(root)
    visited[root] = true
    val result = mutableListOf<Int>()
    result.add(root)
    // Sort each adjacency list by weight, preserving original order for ties
    val sortedAdj = adj.map { edges ->
        edges.withIndex().sortedWith(compareBy({ it.value.second }, { it.index })).map { it.value }
    }
    while (queue.isNotEmpty()) {
        val current = queue.removeFirst()
        for ((neighbor, _) in sortedAdj[current - 1]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true
                result.add(neighbor)
                queue.add(neighbor)
            }
        }
    }
    return result
};1

// Java Operators in Order of Preference
//--------------------------------------------
//Syntax                . followed by ::
//Exponentiation            ^
//Fractions         //
//Multiplication            * / % & \
//Bitshifts         << >> >>>
//Addition          + - | ⊻
//Syntax                :.. followed by |>
//Comparisons           > < >= <= == === != !== <:
//Control flow          && followed by || followed by ?
//Assignments           = += -= *= /= //= \= ^= ÷= %= |= &= ⊻= <<= >>= >>>=

// Operator precedence can be checked within Julia with the Base.operator_precedence function:

//julia> Base.operator_precedence(:>=), Base.operator_precedence(:&&), Base.operator_precedence(:(=))
//(6, 4, 1)

// Julia Associativity of Operators
//---------------------------------------------
//Assignment (=, etc.), conditional (a ? b : c), -> arrows, lazy OR/AND (&& ||),
//power operators, and unary operators are right associative. All others are
//left associative.;1

fun predictTemperature(temperatures: List<Int>): Int {
    val n = temperatures.size
    if (n < 2) {
        throw IllegalArgumentException("There must be at least two temperatures.")
    }
    val d = temperatures[1] - temperatures[0]
    for (i in 2 until n) {
        if (temperatures[i] - temperatures[i - 1] != d) {
            return temperatures.last()
        }
    }
    return temperatures.last() + d
};1

