fun List<String>.parse(tiles: Int, width: Int, height: Int) = (0..24).flatMap { tile ->
    val tileX = tile % tiles * width
    val tileY = tile / tiles * height
    flatMapIndexed { y, row ->
        row.mapIndexed { x, s ->
            val risk = ((s.toString().toInt() + tile % tiles + tile / tiles)).let { if (it > 9) it % 9 else it }
            val shortestPath = if (tileX + x == 0 && tileY + y == 0) 0 else Int.MAX_VALUE
            Node(Point(tileX + x, tileY + y), risk, shortestPath)
        }
    }
}.associateBy { it.point };0

fun extractFileExtension(importStatement: String): String {
    // Regular expression explained:
    //   ^\s*from\s+   -> optionally leading spaces, then 'from' and at least one space
    //   \.             -> the required leading dot in the relative import
    //   ([\w.]+)       -> capture the module path (letters/underscore/digits/dots)
    //   \s+import\s+  -> at least one space, 'import', at least one space
    val pattern = Pattern.compile("^\\s*from\\s+\\.([\\w.]+)\\s+import\\s+")
    val matcher = pattern.matcher(importStatement)
    if (!matcher.find()) {
        throw IllegalArgumentException("Import statement not in expected format.")
    }
    val moduleName = matcher.group(1)
    // The 'file extension' is whatever comes after the last dot in the module name
    return moduleName.split('.').last()
};1

fun moveTail(
    tailX: Int,
    tailY: Int,
    headX: Int,
    headY: Int,
    direction: String,
    body: (x: Int, y: Int) -> Unit
) {
    if (abs(tailX - headX) <= 1 && abs(tailY - headY) <= 1) return

    when (direction) {
        "D" -> {
            body(headX, headY + 1)
        }

        "U" -> {
            body(headX, headY - 1)
        }

        "L" -> {
            body(headX + 1, headY)
        }

        "R" -> {
            body(headX - 1, headY)
        }
    }
};0

