import kotlin.random.Random
 
const val EMPTY: Byte = '.'.toByte()
 
class Board(val grid: Array<ByteArray>) {
    constructor() : this(Array(8) { ByteArray(8) { EMPTY } })
 
    fun fen(): String {
        val fen = StringBuilder()
        var countEmpty = 0
        for (row in grid) {
            for (ch in row) {
                print("${ch.toChar()} ")
                if (ch == EMPTY) {
                    countEmpty++
                } else {
                    if (countEmpty > 0) {
                        fen.append(countEmpty)
                        countEmpty = 0
                    }
                    fen.append(ch.toChar())
                }
            }
            if (countEmpty > 0) {
                fen.append(countEmpty)
                countEmpty = 0
            }
            fen.append('/')
            println()
        }
        fen.append(" w - - 0 1")
        return fen.toString()
    }
 
    fun placeKings(rng: Random) {
        while (true) {
            val r1: Int = rng.nextInt(0, 8)
            val c1: Int = rng.nextInt(0, 8)
            val r2: Int = rng.nextInt(0, 8)
            val c2: Int = rng.nextInt(0, 8)
            if (r1!= r2 && (r1 - r2).absoluteValue > 1 && (c1 - c2).absoluteValue > 1) {
                grid[r1][c1] = 'K'.toByte()
                grid[r2][c2] = 'k'.toByte()
                return
            }
        }
    }
 
    fun placePieces(rng: Random, pieces: ByteArray, isPawn: Boolean) {
        val numToPlace = rng.nextInt(0, pieces.size)
        for (piece in pieces.take(numToPlace)) {
            var r = rng.nextInt(0, 8)
            var c = rng.nextInt(0, 8)
            while (grid[r][c]!= EMPTY || (isPawn && (r == 7 || r == 0))) {
                r = rng.nextInt(0, 8)
                c = rng.nextInt(0, 8)
            }
            grid[r][c] = piece
        }
    }
}
 
fun main() {
    val b = Board()
    b.placeKings(Random)
    b.placePieces(Random, "PPPPPPPP".toByteArray(), true)
    b.placePieces(Random, "pppppppp".toByteArray(), true)
    b.placePieces(Random, "RNBQBNR".toByteArray(), false)
    b.placePieces(Random, "rnbqbnr".toByteArray(), false)
    println(b.fen())
};1

