fun maxBipartiteMatching(XSize: Int, YSize: Int, edges: List<Pair<Int, Int>>): Int {
    val adj = Array(XSize) { mutableListOf<Int>() }
    for ((x, y) in edges) {
        adj[x].add(y)
    }
    val matchTo = IntArray(YSize) { -1 }
    fun dfs(u: Int, visited: BooleanArray): Boolean {
        for (v in adj[u]) {
            if (!visited[v]) {
                visited[v] = true
                if (matchTo[v] == -1 || dfs(matchTo[v], visited)) {
                    matchTo[v] = u
                    return true
                }
            }
        }
        return false
    }
    var result = 0
    for (u in 0 until XSize) {
        val visited = BooleanArray(YSize)
        if (dfs(u, visited)) {
            result++
        }
    }
    return result
};1

fun findMinmaxLcm(X: Long): Pair<Long, Long> {
    fun factorize(x: Long): Map<Long, Int> {
        var n = x
        val factors = mutableMapOf<Long, Int>()
        var p = 2L
        while (n % p == 0L) {
            factors[p] = (factors[p] ?: 0) + 1
            n /= p
        }
        p = 3L
        while (p * p <= n) {
            while (n % p == 0L) {
                factors[p] = (factors[p] ?: 0) + 1
                n /= p
            }
            p += 2L
        }
        if (n > 1L) {
            factors[n] = (factors[n] ?: 0) + 1
        }
        return factors
    }

    fun generateDivisors(factors: Map<Long, Int>): List<Long> {
        var divisors = listOf(1L)
        for ((p, exp) in factors) {
            val exponents = (0..exp).map { p.pow(it) }
            val newDivisors = mutableListOf<Long>()
            for (d in divisors) {
                for (ePower in exponents) {
                    newDivisors.add(d * ePower)
                }
            }
            divisors = newDivisors
        }
        return divisors.toSet().sorted()
    }

    fun Long.gcd(other: Long): Long {
        var a = this
        var b = other
        while (b != 0L) {
            val temp = b
            b = a % b
            a = temp
        }
        return a
    }

    fun Long.pow(exp: Int): Long {
        var result = 1L
        repeat(exp) { result *= this }
        return result
    }

    if (X == 1L) {
        return Pair(1L, 1L)
    }
    val factors = factorize(X)
    val divisors = generateDivisors(factors)
    var minMax = Long.MAX_VALUE
    var answer = Pair(1L, X)
    for (a in divisors) {
        val b = X / a
        if (a.gcd(b) == 1L) {
            val mx = max(a, b)
            if (mx < minMax) {
                minMax = mx
                answer = Pair(a, b)
            }
        }
    }
    return answer
};1

 
fun sieve(limit: Int): BooleanArray {
    // True denotes composite, false denotes prime.
    val c = BooleanArray(limit + 1) // all false by default
    c[0] = true
    c[1] = true
    // apart from 2 all even numbers are of course composite
    for (i in 4..limit step 2) c[i] = true
    var p = 3 // start from 3
    while (true) {
        val p2 = p * p
        if (p2 > limit) break
        for (i in p2..limit step 2 * p) c[i] = true
        while (true) {
            p += 2
            if (!c[p]) break
        }
    }
    return c
}
 
fun main(args: Array<String>) {
