fun runBfs(
    start: Point,
    end: Point,
    blizCache: MutableMap<Int, Set<Point>>,
    basin: Basin,
    initialMinute: Int = 0
): Int {
    val queue = mutableListOf<Visit>().also { it.add(Visit(start, initialMinute)) }
    val visited = mutableSetOf<Visit>()

    while (queue.isNotEmpty()) {
        val next = queue.removeFirst()
        if (visited.contains(next)) continue
        visited.add(next)

        if (Point(next.p.x, next.p.y + 1) == end ||
            Point(next.p.x, next.p.y - 1) == end) { // reached the end
            return (next.minute + 1) - initialMinute
        }

        for (i in next.minute..next.minute + 1) {
            if (!blizCache.contains(i)) { // generate and cache the blizzard positions
                blizCache[i] = basin.getBlizzards(i)
            }
        }

        // We waited here but stuck in the blizzard, discard this option
        if (blizCache[next.minute]!!.contains(next.p)) continue

        val possible = next.p.neighbors().filterNot {
            blizCache[next.minute + 1]!!.contains(it)
        }.filterNot {
            it.x < 0 || it.x > basin.maxX || it.y < 0 || it.y > basin.maxY
        }
        queue.add(Visit(next.p, next.minute + 1)) // wait here
        queue.addAll(possible.map { Visit(it, next.minute + 1) })
    }
    return -1
};0

import java.util.*
 
class Modulo(n: Int = 0, m: Int = 13) : Comparable<Modulo> {
 
    private val n: Int
    private val m: Int
 
    init {
        this.n = n % m
        this.m = m
    }
 
    fun compareTo(other: Modulo): Int {
        return this.n.compareTo(other.n)
    }
 
    operator fun plus(other: Modulo): Modulo {
        return Modulo(this.n + other.n, this.m)
    }
 
    operator fun minus(other: Modulo): Modulo {
        return Modulo(this.n - other.n, this.m)
    }
 
    operator fun times(other: Modulo): Modulo {
        return Modulo(this.n * other.n, this.m)
    }
 
    operator fun rangeTo(other: Modulo): ClosedRange<Modulo> {
        return object : ClosedRange<Modulo> {
            override val start: Modulo
                get() = this@Modulo
            override val endInclusive: Modulo
                get() = other
        }
    }
 
    fun toString(): String {
        return "Modulo(n=$n, m=$m)"
    }
 
    fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass!= other?.javaClass) return false
 
        other as Modulo
 
        if (n!= other.n) return false
        if (m!= other.m) return false
 
        return true
    }
 
    fun hashCode(): Int {
        var result = n
        result = 31 * result + m
        return result
    }
 
}
 
fun main(args: Array<String>) {
 
    val x = Modulo(10)
    val y = Modulo(20)
 
    println(x > y)
    println(x == y)
    println(x + y)
    println(2 + y)
    println(y + 2)
    println(x.rangeTo(y))
    println(x.rangeTo(y).toList())
 
};1

import kotlin.random.Random
 
fun <T> s_of_n_creator(n: Int): (T) -> List<T> {
  var sample = mutableListOf<T>()
  var i = 0
  return { item ->
    i++
    if (i <= n) {
      sample.add(item)
    } else if (Random.nextInt(i) < n) {
      sample[Random.nextInt(n)] = item
    }
    sample
  }
}
 
fun main() {
  val bin = IntArray(10)
  for (trial in 0..99999) {
    val s_of_n = s_of_n_creator(3)
    var sample: List<Int>
    for (i in 0..9)
      sample = s_of_n(i)
    for (s in sample)
      bin[s]++
  }
  for (x in bin)
    println(x)
};1

fun elephantsInZoo(totalAnimals: Int, zebraMore: Int): Any {
    // Grunnleggende validering ---------------------------------------------
    if (totalAnimals < 1) {
        return "Invalid total number of animals. It must be a positive integer."
    }
    // Ingen behov for å sjekke type da Kotlin er typesikret, men behold test for zebraMore
    // Kjerneberegning ------------------------------------------------------
    val numerator = totalAnimals - zebraMore
    // Sjekk delbarhet med 4 (må være et helt antall elefanter)
    if (numerator % 4 != 0) {
        return ("Invalid data: the calculated number of elephants is fractional " +
                "((total_animals - zebra_more) is not divisible by 4).")
    }
    val elephants = numerator / 4
    // Ytterligere logiske valideringer ------------------------------------
    if (elephants < 0) {
        return "Invalid data: the computed number of elephants is negative."
    }
    val zebras = 3 * elephants + zebraMore
    if (zebras < 0) {
        return "Invalid data: the computed number of zebras is negative."
    }
    // Alle sjekker bestått -----------------------------------------------
    return elephants
};1

/** Return 0 for each index whose member in a belongs to the increasing sequence.
 * 1 otherwise. null if not possible. */
fun findIncrSeqMembers(a: List<Int>, n: Int): List<Int>? {
    val res = MutableList(n) { 0 }

    var incrMax = Int.MIN_VALUE
    var decrMin = Int.MAX_VALUE
    if (n > 1 && a[0] >= a[1]) {
        res[0] = 1
        decrMin = res[0]
        // TODO extend this using a while loop. Take all decreasing numbers into decr until we hit something that has to go into incr.
        // TODO that probably won't cover many cases...
    }

    for (k in a) {
        if (k < decrMin) {
            decrMin = k
        } else if (k > incrMax) {
            incrMax = k
        } else {
            return null
        }
    }

    return res
};0

