fun fibonacci(n: Int): List<Int> {
    val fib = mutableListOf<Int>()
    if (n >= 1) {
        fib.add(0)
    }
    if (n >= 2) {
        fib.add(1)
    }
    for (i in 2 until n) {
        val nextNum = fib[i - 1] + fib[i - 2]
        fib.add(nextNum)
    }
    return fib
