    }
};0

fun countUniqueLcmFactors(b: Long): Int {
    if (b == 1L) return 1
    var res = 1
    var p = 2L
    var n = b
    while (p * p <= n) {
        if (n % p == 0L) {
            var e = 0
            while (n % p == 0L) {
                e += 1
                n /= p
            }
            res *= (e + 1)
        }
        p += 1L
    }
    if (n > 1L) {
        res *= 2
    }
    return res
};1

