fun place_number(pos: Int, sudoku_ar: MutableList<Int>): Boolean {
    return (pos..80).find { sudoku_ar[it] == 0 }?.let { pos ->
        val (x, y) = (pos % 9 to pos / 9)
        for (n in 1..9) {
            if (is_valid(n, x, y, sudoku_ar)) {
                sudoku_ar[pos] = n
                if (place_number(pos + 1, sudoku_ar)) {
                    return true
                }
                sudoku_ar[pos] = 0
            }
        }
        false
    }?: true
}
 
