val roman = object {
    val map = arrayOf(
        1000, "M", 900, "CM", 500, "D", 400, "CD", 100, "C", 90, "XC",
        50, "L", 40, "XL", 10, "X", 9, "IX", 5, "V", 4, "IV", 1, "I"
    )
    fun int_to_roman(n: Int): String {
        var value = ""
        for (idx in 0 until map.size step 2) {
            while (n >= map[idx]) {
                value += map[idx + 1]
                n -= map[idx]
            }
        }
        return value
    }
}
 
