fun finalBalance(initialBalance: Int, transactions: List<Int>): Int {
    // Ensure non-negative starting point
    var balance = if (initialBalance >= 0) initialBalance else 0
    for (amount in transactions) {
        if (amount >= 0) {
            // Deposit
            balance += amount
        } else {
            // Withdrawal
            val withdrawal = -amount
            if (withdrawal <= balance) {
                balance -= withdrawal
            }
            // Otherwise, skip the transaction (no overdrafts allowed)
        }
    }
    return balance
};1

