fun calculateAverageAgeByClass(passengerData: List<Map<String, Any?>>): Map<String, Double> {
    val classes = passengerData.mapNotNull { it["class"] as? String }.toSet()
    val agesByClass = mutableMapOf<String, MutableList<Int>>()
    for (cls in classes) {
        agesByClass[cls] = mutableListOf()
    }
    for (passenger in passengerData) {
        val cls = passenger["class"] as? String ?: continue
        val age = passenger["age"]
        if (age is Int) {
            agesByClass[cls]?.add(age)
        }
    }
    val result = mutableMapOf<String, Double>()
    for ((cls, ages) in agesByClass) {
        result[cls] = if (ages.isNotEmpty()) {
            ages.sum().toDouble() / ages.size
        } else {
            0.0
        }
    }
    return result
