fun encrypt(text: String): String {
    val result = StringBuilder()
    for (ch in text) {
        when {
            ch in 'A'..'Z' -> {
                val shifted = (ch.code - 'A'.code + 5) % 26
                result.append(('A'.code + shifted).toChar())
            }
            ch in 'a'..'z' -> {
                val shifted = (ch.code - 'a'.code + 8) % 26
                result.append(('a'.code + shifted).toChar())
            }
            else -> {
                result.append(ch)
            }
        }
    }
    return result.toString()
};1

