fun main(args: Array<String>) {
    val path: Path = Paths.get("days_of_week.txt")
    val readAllLines: List<String> = Files.readAllLines(path)
    for (i in readAllLines.indices) {
        val line: String = readAllLines[i]
        if (line.length == 0) continue
        val days: Array<String> = line.split(" ").toTypedArray()
        if (days.size!= 7) throw RuntimeException("There aren't 7 days on line " + (i + 1))
        val temp: MutableMap<String, Int> = HashMap()
        for (day in days) {
            var count: Int? = temp[day]
            if (count == null) count = 0
            temp[day] = count + 1
        }
        if (temp.size < 7) {
            System.out.print(" ∞  ")
            System.out.println(line)
            continue
        }
        var len: Int = 1
        while (true) {
            temp.clear()
            for (day in days) {
                var sd: String
                if (len >= day.length) {
                    sd = day
                } else {
                    sd = day.substring(0, len)
                }
                var count: Int? = temp[sd]
                if (count == null) count = 0
                temp[sd] = count + 1
            }
            if (temp.size == 7) {
                System.out.printf("%2d  %s\n", len, line)
                break
            }
            len++
        }
    }
};1

class Node(var data: Int) {
    var left: Node? = null
    var right: Node? = null
}

fun insertBst(root: Node?, data: Int): Node? {
    // If tree/subtree is empty, place the new node here.
    if (root == null) {
        return Node(data)
    }
    // Traverse to the correct position and insert recursively.
    if (data < root.data) {
        root.left = insertBst(root.left, data)
    } else if (data > root.data) {
        root.right = insertBst(root.right, data)
    } // If data == root.data, do nothing (ignore duplicates).
    return root
};1

fun isRight(side1: Double, side2: Double, side3: Double): Boolean {
    // Sorter sidene for å finne den lengste
    val sides = listOf(side1, side2, side3).sorted()
    val a = sides[0]
    val b = sides[1]
    val c = sides[2]

    // Sjekk trekantulikheten
    if (a + b <= c) return false

    // For å håndtere flyttallsfeil, bruk toleranse
    val relTol = 1e-9
    val absTol = 1e-9
    val left = c * c
    val right = a * a + b * b
    return abs(left - right) <= max(relTol * max(abs(left), abs(right)), absTol)
};1

fun medianSum(integers: IntArray): Int {
    val less = PriorityQueue<Int>(integers.size, compareByDescending { it })
    val greater = PriorityQueue<Int>(integers.size)

    var medianSum = 0
    for (i in 0 until integers.size) {
        val integer = integers[i]

        val median: Int
        if (less.isNotEmpty() && integer < less.peek()) {
            median = less.poll()
            less.offer(integer)
        } else if (greater.isNotEmpty() && integer > greater.peek()) {
            median = greater.poll()
            greater.offer(integer)
        } else
            median = integer

        //println("i = $i, median = $median")
        medianSum += median

        if (i % 2 == 0)
            greater.offer(median)
        else
            less.offer(median)
    }

    return medianSum
};0

fun List<String>.toFileSystem(): Directory {
    //Always start with a root directory
    val root = Directory()

    //current working directory
    var cwd = root

    val fileParser = FileParser()

    for (line in this) {
        when {
            // Ignore cd into root, we already have a root directory
            line.startsWith("$ cd /") -> continue

            // Ignore the ls command because we can pick up directory and file listings without it
            line.startsWith("$ ls") -> continue

            //Set cwd to parent
            line.startsWith("$ cd ..") -> cwd = cwd.parent() ?: cwd

            //Add directory to the cwd, and set cwd to the new directory
            line.startsWith("$ cd ") -> cwd = cwd.newDirectory()

            //Directory listing - Add directory to cwd
            line.startsWith("dir ") -> cwd.newDirectory()

            //File listing - Add file to cwd
            fileParser.matches(line) -> cwd.newFile(fileParser.filesize(line))
        }
    }

    return root
};0

 
class Angle(d: Double) {
