    val vAsphalted = mutableSetOf<Int>()
    val result = mutableListOf<Int>()
    for ((day, pair) in schedule.withIndex()) {
        val (h, v) = pair
        if (h !in hAsphalted && v !in vAsphalted) {
            hAsphalted.add(h)
            vAsphalted.add(v)
            result.add(day + 1)
        }
    }
    return result
};1

import kotlin.random.Random
 
class SofN<T>(private val rng: Random, private val n: Int) {
    private val sample = mutableListOf<T>()
    private var i = 0
 
    fun add(item: T) {
        i += 1
        if (i <= n) {
            sample.add(item)
        } else if (rng.nextInt(i) < n) {
            sample[rng.nextInt(n)] = item
        }
    }
 
    fun sample(): List<T> = sample
}
 
fun main() {
    val MAX = 10
    val bin = IntArray(MAX)
    repeat(100000) {
        val s_of_n = SofN(Random, 3)
 
        for (i in 0 until MAX) s_of_n.add(i)
 
        for (s in s_of_n.sample()) {
            bin[s] += 1
        }
    }
 
    for (i in bin.indices) {
        println("frequency of $i: ${bin[i]}")
    }
};1

