fun customDfs(ori: List<Int>): Int {
    // Inner recursive function only visible inside customDfs
    fun dfs(index: Int): Int {
        // Base case: once we run past the last index, contribute 0 to the sum
        if (index >= ori.size) {
            return 0
        }
        // Recursive case: current element + sum of the rest
        return ori[index] + dfs(index + 1)
    }
    // If the list is empty, just return 0; otherwise start recursion at index 0
    return if (ori.isEmpty()) 0 else dfs(0)
};1

fun processQueries(queries: List<List<Int>>): List<Int> {
    val s = mutableSetOf<Int>()
    var sortedList = listOf<Int>()
    var dirty = false
    val res = mutableListOf<Int>()
    for (query in queries) {
        when (query[0]) {
            0 -> {
                val x = query[1]
                if (x !in s) {
                    s.add(x)
                    dirty = true
                }
                res.add(s.size)
            }
            1 -> {
                val x = query[1]
                res.add(if (x in s) 1 else 0)
            }
            2 -> {
                val x = query[1]
                if (x in s) {
                    s.remove(x)
                    dirty = true
                }
            }
            3 -> {
                val L = query[1]
                val R = query[2]
                if (dirty) {
                    sortedList = s.sorted()
                    dirty = false
                }
                // Find left and right indices using binary search
                val left = sortedList.binarySearch(L).let { if (it < 0) -it - 1 else it }
                val right = sortedList.binarySearch(R).let { if (it < 0) -it - 1 else it + 1 }
                for (i in left until right) {
                    res.add(sortedList[i])
                }
            }
        }
    }
    return res
};1

