fun bankAccountOperations(
    accountHolder: String,
    initialBalance: Double,
    operations: List<Pair<String, Double>>
): Double {
    /**
     * Simulates a series of banking operations on an account and returns the final balance.
     *
     * Parameters
     * ----------
     * accountHolder : String
     *     The name of the account holder (not used in calculations, kept for completeness).
     * initialBalance : Double
     *     The starting balance of the account.
     * operations : List<Pair<String, Double>>
     *     A list of pairs, each describing an operation:
     *         - The first element is either the string 'deposit' or 'withdraw'.
     *         - The second element is a non-negative Double representing the amount.
     *
     * Returns
     * -------
     * Double
     *     The balance after processing all operations.
     */
    var balance = initialBalance

    for ((opType, amount) in operations) {
        // Make sure the amount is non-negative
        if (amount < 0) {
            throw IllegalArgumentException("Amount must be non-negative")
        }

        when (opType) {
            "deposit" -> balance += amount
            "withdraw" -> {
                if (amount <= balance) {
                    balance -= amount
                }
                // else: If insufficient funds, ignore the withdrawal
            }
            else -> throw IllegalArgumentException("Unknown operation type: $opType")
        }
    }

    return balance
};1

/**
 * Traverse from left to right, find every peak followed by valley, and
 * book profit. Keep accumulating the profit and return it.
 */
fun maxProfit3(prices: IntArray): Int {
    var valley = 0
    var peak = 0
    var profit = 0
    var i = 0
    while (i < prices.size - 1) {
        // going down till we find a valley
        while (i < prices.size - 1 && prices[i + 1] <= prices[i]) i++
        valley = prices[i]

        // going up till we find a peak
        while (i < prices.size - 1 && prices[i + 1] >= prices[i]) i++
        peak = prices[i]

        // time to book profit
        profit += peak - valley
    }
    return profit
};0

fun binarySearch(l: List<Int>, value: Int): Int {
    var low = 0
    var high = l.size - 1
    while (low <= high) {
        val mid = (low + high) / 2
        if (l[mid] > value) high = mid - 1
        else if (l[mid] < value) low = mid + 1
        else return mid
    }
    return -1
};1

fun maxAverageOf(nTreeNode: NTreeNode): Int? {
    val sumByNode = HashMap<NTreeNode, Int>()
    val sizeByNode = HashMap<NTreeNode, Int>()
    var maxAverage = Double.MIN_VALUE
    var maxNode: NTreeNode? = null

    nTreeNode.traverseBottomUp { node ->
        sumByNode[node] = node.value + node.children.sumBy { sumByNode[it]!! }
        sizeByNode[node] = 1 + node.children.sumBy { sizeByNode[it]!! }
        val nodeAverage = sumByNode[node]!!.toDouble() / sizeByNode[node]!!
        if (node.children.isNotEmpty() && nodeAverage > maxAverage) {
            maxAverage = nodeAverage
            maxNode = node
        }
    }

    return maxNode?.value
};0

 
