fun secureInnerJoin(listA: List<Int>, listB: List<Int>): List<List<Double>> {
    val setB = listB.toSet()
    val rows = mutableListOf<List<Double>>()
    for (value in listA) {
        if (setB.contains(value)) {
            rows.add(
                listOf(
                    value.toDouble(),
                    value / 2.0,
                    (value + value).toDouble(),
                    (value * value).toDouble()
                )
            )
        }
    }
    return rows.sortedBy { it[0] }
};1

