     * X = -1
     * Y = 0
     * Z = +1
     */
    val choice = when(outcomeRequired) {
        "X" -> oppChoiceValue-1
        "Y" -> oppChoiceValue
        "Z" -> oppChoiceValue + 1
        else -> throw IllegalArgumentException("Invalid input")
    }

    if (choice == 0) {
        return 3
    }
    if (choice == 4) {
        return 1
    }
    return choice
};0

fun <ForwardIterator> combsort(first: ForwardIterator, last: ForwardIterator) {
    val shrink_factor = 1.247330950103979
    val gap = first.distance(last)
    var swaps = true
    while (gap > 1 || swaps == true) {
        if (gap > 1) {
            gap = (gap / shrink_factor).toInt()
        }
        swaps = false
        var itLeft = first
        var itRight = first
        itRight.advance(gap)
        while (itRight!= last) {
            if (itRight.get() < itLeft.get()) {
                itLeft.swap(itRight)
                swaps = true
            }
            itLeft++
            itRight++
        }
    }
};1

import java.lang.Math
import java.util.HashMap
import java.util.Map
 
object REntropy {
 
  @JvmStatic
  fun main(args: Array<String>) {
    val sstr = arrayOf(
      "1223334444",
      "1223334444555555555",
      "122333",
      "1227774444",
      "aaBBcccDDDD",
      "1234567890abcdefghijklmnopqrstuvwxyz",
      "Rosetta Code"
    )
 
    for (ss in sstr) {
      val entropy = getShannonEntropy(ss)
      println(String.format("Shannon entropy of %40s: %.12f", "\"" + ss + "\"", entropy))
    }
  }
 
  fun getShannonEntropy(s: String): Double {
    var n = 0
    val occ = HashMap<Char, Int>()
 
    for (c_ in 0 until s.length) {
      val cx = s[c_]
      if (occ.containsKey(cx)) {
        occ[cx] = occ[cx]!! + 1
      } else {
        occ[cx] = 1
      }
      ++n
    }
 
    var e = 0.0
    for ((cx, p) in occ) {
      e += p * log2(p.toDouble() / n)
    }
    return -e
  }
 
  fun log2(a: Double): Double {
    return Math.log(a) / Math.log(2.0)
  }
};1

 
import java.util.Random
import java.util.concurrent.locks.Lock
import java.util.concurrent.locks.ReentrantLock
 
val rand = Random()
 
class Fork(val name: String) {
    val lock = ReentrantLock()
 
    fun pickUp(philosopher: String) {
        lock.lock()
        println("  $philosopher picked up $name")
    }
 
    fun putDown(philosopher: String) {
        lock.unlock()
        println("  $philosopher put down $name")
    }
}
 
class Philosopher(val pname: String, val f1: Fork, val f2: Fork) : Thread() {
    fun run() {
        (1..20).forEach {
            println("$pname is hungry")
            f1.pickUp(pname)
            f2.pickUp(pname)
            println("$pname is eating bite $it")
            Thread.sleep(rand.nextInt(300) + 100L)
            f2.putDown(pname)
            f1.putDown(pname)
        }
    }
}
 
fun diningPhilosophers(names: List<String>) {
    val size = names.size
    val forks = List(size) { Fork("Fork ${it + 1}") }
    val philosophers = mutableListOf<Philosopher>()
    names.forEachIndexed { i, n ->
        var i1 = i
        var i2 = (i + 1) % size
        if (i2 < i1) {
            i1 = i2
            i2 = i
        }
        val p = Philosopher(n, forks[i1], forks[i2])
        p.start()
        philosophers.add(p)
    }
    philosophers.forEach { it.join() }
}
 
