data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

fun origamiHoleCounts(datasets: List<Quadruple<Int, Int, List<Pair<Int, Int>>, List<Pair<Int, Int>>>>): List<List<Int>> {
    val results = mutableListOf<List<Int>>()
    for ((n, m, folds, punches) in datasets) {
        var currentW = n
        var currentH = m
        for ((d, c) in folds) {
            if (d == 1) {
                currentW -= c
            } else {
                currentH -= c
            }
        }
        val punchCounts = mutableListOf<Int>()
        for ((x, y) in punches) {
            var coords = mutableSetOf(Pair(x, y))
            var cw = currentW
            var ch = currentH
            for ((d, c) in folds.asReversed()) {
                if (d == 1) {
                    val newW = cw + c
                    val newCoords = mutableSetOf<Pair<Int, Int>>()
                    for ((xx, yy) in coords) {
                        val xr = xx + c
                        if (xr in 0 until newW) newCoords.add(Pair(xr, yy))
                        val xl = c - xx - 1
                        if (xl in 0 until newW) newCoords.add(Pair(xl, yy))
                    }
                    coords = newCoords
                    cw = newW
                } else {
                    val newH = ch + c
                    val newCoords = mutableSetOf<Pair<Int, Int>>()
                    for ((xx, yy) in coords) {
                        val yu = yy + c
                        if (yu in 0 until newH) newCoords.add(Pair(xx, yu))
                        val yl = c - yy - 1
                        if (yl in 0 until newH) newCoords.add(Pair(xx, yl))
                    }
                    coords = newCoords
                    ch = newH
                }
            }
            punchCounts.add(coords.size)
        }
        results.add(punchCounts)
    }
    return results
};1

