fun finishingTimes(m: Int, n: Int, times: List<List<Int>>): List<Int> {
    var prev = MutableList(n) { 0 }
    val result = mutableListOf<Int>()
    for (i in 0 until m) {
        val curr = MutableList(n) { 0 }
        curr[0] = prev[0] + times[i][0]
        for (j in 1 until n) {
            curr[j] = maxOf(curr[j - 1], prev[j]) + times[i][j]
        }
        result.add(curr.last())
        prev = curr.toMutableList()
    }
    return result
};1

class Node(var data: Int = 0, var next: Node? = null) {
    companion object {
        fun shallowCopy(head: Node?): Node? {
            if (head == null) return null
            val oldToNew = mutableMapOf<Node, Node>()
            var current = head
            // First pass: Create nodes up to the start of any cycle
            while (current != null && !oldToNew.containsKey(current)) {
                oldToNew[current] = Node(current.data)
                current = current.next
            }
            // Second pass: Set the 'next' pointers
            for ((origNode, copyNode) in oldToNew) {
                copyNode.next = if (origNode.next != null && oldToNew.containsKey(origNode.next)) {
                    oldToNew[origNode.next]
                } else {
                    null
                }
            }
            return oldToNew[head]
        }
    }
};1

