fun main(args: Array<String>) {
    val numbers = Arrays.asList(BigInteger("12757923"), BigInteger("12878611"), BigInteger("12878893"), BigInteger("12757923"), BigInteger("15808973"), BigInteger("15780709"))
    val rs = lmf(numbers)
    println("largest minimal factor: " + rs[0].decomp[0])
    for (r in rs) {
        println(r.number + " -> " + r.decomp)
    }
