fun lmf(numbers: List<BigInteger>): List<Result> {
    val rCh = ArrayList<Result>()
    for (n in numbers) {
        rCh.add(decomp(n))
    }
    val rs = ArrayList<Result>()
    rs.add(rCh[0])
    for (i in 1..rCh.size - 1) {
        when {
            rCh[i].decomp[0].compareTo(rs[0].decomp[0]) == 1 -> {
                rs.clear()
                rs.add(rCh[i])
            }
            rCh[i].decomp[0].compareTo(rs[0].decomp[0]) == 0 -> rs.add(rCh[i])
        }
    }
    return rs
}
 
fun decomp(n: BigInteger): Result {
    return Result(n, Primes(n))
}
 
class Result(val number: BigInteger, val decomp: List<BigInteger>)
 
fun Primes(n: BigInteger): List<BigInteger> {
    val res = ArrayList<BigInteger>()
    var mod = BigInteger.ZERO
    var div = BigInteger.ZERO
    var i = BigInteger.valueOf(2)
    while (i.compareTo(n)!= 1) {
        div = n.divide(i)
        mod = n.mod(i)
        while (mod.compareTo(BigInteger.ZERO) == 0) {
            res.add(i)
            n = div
            div = n.divide(i)
            mod = n.mod(i)
        }
        i = i.add(BigInteger.ONE)
    }
    return res
};1

fun reverseWords(s: String): String {
    val words = s.split(" ")
    val processedWords = mutableListOf<String>()
    val pattern = Pattern.compile("^([a-zA-Z]*)(.*)$")
    for (word in words) {
        val matcher = pattern.matcher(word)
        if (matcher.find()) {
            val letters = matcher.group(1)
            val rest = matcher.group(2)
            val reversedLetters = letters.reversed()
            processedWords.add(reversedLetters + rest)
        } else {
            processedWords.add(word.reversed())
        }
    }
    return processedWords.joinToString(" ")
};1

fun inventoryManagement(items: List<String>, quantities: List<Int>): Map<String, Int> {
    val inventory = mutableMapOf<String, Int>()
    val length = minOf(items.size, quantities.size)
    for (i in 0 until length) {
        val item = items[i]
        val quantity = quantities[i]
        inventory[item] = inventory.getOrDefault(item, 0) + quantity
    }
    return inventory
