class Accumulator(sum0: Number) {
    var sum: Number = sum0
        private set
 
    fun apply(n: Number): Number {
        // Acts like sum += n, but chooses long or double.
        // Converts weird types (like BigInteger) to double.
        return if (longable(sum) && longable(n)) {
            sum = sum.toLong() + n.toLong()
        } else {
            sum = sum.toDouble() + n.toDouble()
        }
    }
 
    fun longable(n: Number): Boolean {
        return n is Byte || n is Short || n is Int || n is Long
    }
 
    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val x = Accumulator(1)
            x.apply(5)
            Accumulator(3)
            println(x.apply(2.3))
        }
    }
};1

fun countDistinctSubsequences(N: Int, S: String): Int {
    val MOD = 1000000007L
    val charCounts = mutableMapOf<Char, Int>()
    for (ch in S) {
        charCounts[ch] = (charCounts[ch] ?: 0) + 1
    }
    var result = 1L
    for (count in charCounts.values) {
        result = (result * (count + 1)) % MOD
    }
    result = (result - 1 + MOD) % MOD
    return result.toInt()
};1

import (
    "hash/fnv"
    "log"
    "math/rand"
    "os"
    "time"
)
 
// Number of philosophers is simply the length of this list.
// It is not otherwise fixed in the program.
var ph = []string{"Aristotle", "Kant", "Spinoza", "Marx", "Russell"}
 
const hunger = 3                // number of times each philosopher eats
const think = time.Second / 100 // mean think time
const eat = time.Second / 100   // mean eat time
 
var fmt = log.New(os.Stdout, "", 0) // for thread-safe output
 
var done = make(chan bool)
 
// This solution uses channels to implement synchronization.
// Sent over channels are "forks."
type fork byte
 
// A fork object in the program models a physical fork in the simulation.
// A separate channel represents each fork place.  Two philosophers
// have access to each fork.  The channels are buffered with capacity = 1,
// representing a place for a single fork.
 
// Goroutine for philosopher actions.  An instance is run for each
// philosopher.  Instances run concurrently.
fun philosopher(phName: String,
    dominantHand: Channel<fork>, otherHand: Channel<fork>, done: Channel<Boolean>) {
    fmt.println(phName, "seated")
    // each philosopher goroutine has a random number generator,
    // seeded with a hash of the philosopher's name.
    val h = fnv.New64a()
    h.Write([]byte(phName))
    val rg = rand.New(rand.NewSource(int64(h.Sum64())))
    // utility function to sleep for a randomized nominal time
    val rSleep = fun(t: time.Duration) {
        time.Sleep(t/2 + time.Duration(rg.Int63n(int64(t))))
    }
    for (h in hunger) {
        fmt.println(phName, "hungry")
        dominantHand.receive() // pick up forks
        otherHand.receive()
        fmt.println(phName, "eating")
        rSleep(eat)
        dominantHand.send('f') // put down forks
        otherHand.send('f')
        fmt.println(phName, "thinking")
        rSleep(think)
    }
    fmt.println(phName, "satisfied")
    done.send(true)
    fmt.println(phName, "left the table")
}
 
fun main() {
    fmt.println("table empty")
    // Create fork channels and start philosopher goroutines,
    // supplying each goroutine with the appropriate channels
    val place0 = make(Channel<fork>, 1)
    place0.send('f') // byte in channel represents a fork on the table.
