fun trycell(x: IntArray, pos: Int): Boolean {
    var row = pos / 9
    var col = pos % 9
    var i: Int
    var j: Int
    var used = 0
 
    if (pos == 81) {
        return true
    }
    if (x[pos]!= 0) {
        return trycell(x, pos + 1)
    }
 
    for (i in 0..8) {
        used = used or (1 shl (x[i * 9 + col] - 1))
    }
 
    for (j in 0..8) {
        used = used or (1 shl (x[row * 9 + j] - 1))
    }
 
    row = row / 3 * 3
    col = col / 3 * 3
    for (i in row..row + 2) {
        for (j in col..col + 2) {
            used = used or (1 shl (x[i * 9 + j] - 1))
        }
    }
 
    for (x[pos] in 1..9) {
        if ((used and 1) == 0 && trycell(x, pos + 1)) {
            return true
        }
        used = used shr 1
    }
 
    x[pos] = 0
    return false
}
 
