fun shiftingLetters(S: String, shifts: IntArray): String {
    val n = S.length
    val res = CharArray(n)
    var cumulative = 0

    for (i in n - 1 downTo 0) {
        cumulative = (cumulative + shifts[i]) % 26
        val originalPos = S[i] - 'a'
        val shiftedPos = (originalPos + cumulative) % 26
        res[i] = ('a' + shiftedPos)
    }

    return res.concatToString()
};1

