fun distinctPermutations(S: String): List<String> {
    fun <T> permute(list: List<T>): List<List<T>> {
        if (list.size <= 1) return listOf(list)
        val perms = mutableListOf<List<T>>()
        val seen = mutableSetOf<T>()
        for (i in list.indices) {
            val curr = list[i]
            if (curr in seen) continue
            seen.add(curr)
            val sub = list.toMutableList().apply { removeAt(i) }
            for (p in permute(sub)) {
                perms.add(listOf(curr) + p)
            }
        }
        return perms
    }
    val uniquePerms = mutableSetOf<String>()
    for (p in permute(S.toList())) {
        uniquePerms.add(p.joinToString(""))
    }
    return uniquePerms.sorted()
};1

