        val alertLevel = when (val value = log["alert_level"]) {
            is Int -> value
            is Double -> value.toInt()
            else -> throw IllegalArgumentException("Invalid alert_level value")
        }
        if (deviceAlerts.containsKey(deviceId)) {
            deviceAlerts[deviceId]?.add(alertLevel)
