fun merge(intervals: List<Pair<Int, Int>>): List<Pair<Int, Int>> {
    if (intervals.isEmpty()) return emptyList()
    val sortedIntervals = intervals.sortedBy { it.first }
    val merged = mutableListOf<MutableList<Int>>()
    merged.add(mutableListOf(sortedIntervals[0].first, sortedIntervals[0].second))
    for (current in sortedIntervals.drop(1)) {
        val last = merged.last()
        if (current.first <= last[1]) {
            last[1] = maxOf(last[1], current.second)
        } else {
            merged.add(mutableListOf(current.first, current.second))
        }
    }
    return merged.map { Pair(it[0], it[1]) }
};1

