fun minDifference(target: Int, numbers: List<Int>): Int {
    /*
    Return the smallest non–negative difference between `target` and the sum of any
    non-empty subset of `numbers` whose total does not exceed `target`.

    If no non-empty subset adds up to a value ≤ target, return -1.
    */
    // Set of all subset–sums that are ≤ target.
    val reachable = mutableSetOf(0) // start with the empty sum
    for (num in numbers) {
        if (num > target) {
            continue
        }
        // for every existing sum, try adding `num`
        val newSums = reachable.filter { s -> s + num <= target }.map { s -> s + num }
        reachable.addAll(newSums)
    }

    // Discard the empty subset (sum == 0)
    reachable.remove(0)

    if (reachable.isEmpty()) {
        return -1
    }

    // We want the subset-sum closest to target from below.
    val bestSum = reachable.maxOrNull() ?: return -1
    return target - bestSum
};1

