fun chooseAFlask(markings: List<List<Int>>, flaskTypes: Int, requirements: List<Int>): Int {
    val flaskMap = mutableMapOf<Int, MutableList<Int>>()
    for (mark in markings) {
        if (mark[0] in flaskMap) {
            flaskMap[mark[0]]!!.add(mark[1])
        } else {
            flaskMap[mark[0]] = mutableListOf(mark[1])
        }
    }

    var minSum =Int.MAX_VALUE
    var flaskId = -1

        for (flsk in 0 until flaskTypes) {
            for (req in requirements) {
                var currentSum = 0
                val flaskMarkings = flaskMap[flsk]!!
                for (mark in flaskMarkings) {
                    if (mark >= req) {
                        currentSum += mark - req
                    }
                }

                if (currentSum < minSum) {
                    minSum = currentSum
                    flaskId = flsk
                }
            }
        }

    return flaskId

};0

fun FileSystemNode.Directory.findDirToDeleteSize(neededSpace: Int): Int {
    val dirsToDeleteSizes = mutableListOf(Int.MAX_VALUE)
    if (this.size > neededSpace) dirsToDeleteSizes.add(this.size)

    children.forEach { node ->
        if (node.value is FileSystemNode.Directory) {
            dirsToDeleteSizes.add(
                (node.value as FileSystemNode.Directory).findDirToDeleteSize(neededSpace)
            )
        }
    }

    return dirsToDeleteSizes.min()
};0

