class point
{
    var x: Int = 0
    var y: Int = 0
    constructor() { x = 0; y = 0 }
    constructor( a: Int, b: Int ) { x = a; y = b }
    fun set( a: Int, b: Int ) { x = a; y = b }
}
//--------------------------------------------------------------------------------------------------
class rndCircle : JPanel()
{
    private val _ptList = ArrayList<point>()
 
    fun paintComponent( g: Graphics )
    {
        super.paintComponent( g )
        createPoints()
        drawPoints( g )
    }
 
    fun createPoints()
    {
        val pt = point()
        for( x in 0..199 )
        {
            var a: Int
            var b: Int
            var c: Int
            while( true )
            {
                a = Random().nextInt( 31 ) - 15
                b = Random().nextInt( 31 ) - 15
                c = a * a + b * b
                if( c >= 100 && c <= 225 ) break
            }
            pt.set( a, b )
            _ptList.add( pt )
        }
    }
 
    fun drawPoints( g: Graphics )
    {
        for( pt in _ptList )
            g.color = Color.YELLOW
        g.drawOval( 300 + 10 * pt.x, 300 + 10 * pt.y, 10, 10 )
    }
}
//--------------------------------------------------------------------------------------------------
fun main( args: Array<String> )
{
    val frame = JFrame()
    frame.defaultCloseOperation = JFrame.EXIT_ON_CLOSE
    frame.setSize( 600, 600 )
    frame.isVisible = true
    frame.add( rndCircle() )
}
