import kotlin.random.Random
 
fun makeMaze(w: Int = 16, h: Int = 8): String {
    val vis = Array(h + 1) { IntArray(w + 1) }
    val ver = Array(h + 1) { Array(w + 1) { "|" } }
    val hor = Array(h + 1) { Array(w + 1) { "+" } }
 
    fun walk(x: Int, y: Int) {
        vis[y][x] = 1
 
        val d = listOf(Pair(x - 1, y), Pair(x, y + 1), Pair(x + 1, y), Pair(x, y - 1))
        d.shuffled(Random).forEach { (xx, yy) ->
            if (vis[yy][xx] == 1) return@forEach
            if (xx == x) hor[maxOf(y, yy)][x] = "+"
            if (yy == y) ver[y][maxOf(x, xx)] = " "
            walk(xx, yy)
        }
    }
 
    walk(Random.nextInt(w), Random.nextInt(h))
 
    var s = ""
    for (i in 0 until h) {
        for (j in 0 until w) {
            s += hor[i][j] + " " + ver[i][j] + " "
        }
        s += hor[i][w] + "\n"
    }
    return s
}
 
