fun removePerson(peopleList: MutableList<Map<String, Any>>, id: Int): String {
    // Search for the person by ID
    for ((index, person) in peopleList.withIndex()) {
        // Assumption guarantees 'id' key exists and is Int
        val personId = person["id"]
        if (personId is Int && personId == id) {
            peopleList.removeAt(index)
            return "Removed the person with id: $id"
        }
    }
    return "No person found with id: $id"
};1

 
fun commaQuibble(s: String): String {
    val t = s.trim('[', ']').replace(" ", "").replace("\"", "")
    val words = t.split(',')
    val sb = StringBuilder("{")
    for (i in 0 until words.size) {
        sb.append(when (i) {
            0                -> ""
            words.lastIndex  -> " and "
            else             -> ", "
        })
        sb.append(words[i])
    }
    return sb.append("}").toString()
}
 
