fun splitArray(nums: List<Int>): Boolean {
    val n = nums.size
    if (n < 7) return false

    // Prefix sums: pref[x] = sum(nums[0 .. x])
    val pref = IntArray(n)
    pref[0] = nums[0]
    for (idx in 1 until n) {
        pref[idx] = pref[idx - 1] + nums[idx]
    }

    // Helper to get sum of nums[l .. r] inclusive
    fun rangeSum(l: Int, r: Int): Int {
        return if (l == 0) pref[r] else pref[r] - pref[l - 1]
    }

    for (j in 3 until n - 3) {
        val equalSumsLeft = mutableSetOf<Int>()

        for (i in 1 until j - 1) {
            if (rangeSum(0, i - 1) == rangeSum(i + 1, j - 1)) {
                equalSumsLeft.add(rangeSum(0, i - 1))
            }
        }
        if (equalSumsLeft.isEmpty()) {
            continue
        }
        for (k in j + 2 until n - 1) {
            if (rangeSum(j + 1, k - 1) == rangeSum(k + 1, n - 1)) {
                val target = rangeSum(j + 1, k - 1)
                if (target in equalSumsLeft) {
                    return true
                }
            }
        }
    }
    return false
};1

fun findLadders(beginWord: String, endWord: String, wordList: List<String>): Set<Solution> {
    val ladders = findAllLadders(beginWord, endWord, wordList)
    val minSize = ladders.minByOrNull { it: Solution -> it.size }?.size ?: return emptySet()
    return ladders.filterTo(HashSet()) { it.size == minSize }
