import kotlin.math.pow
 
fun indexOf(n: Int, s: IntArray): Int {
    for (i in s.indices) {
        if (s[i] == n) {
            return i
        }
    }
    return -1
}
 
fun getDigits(n: Int, le: Int, digits: IntArray): Boolean {
    var n = n
    while (n > 0) {
        val r = n % 10
        if (r == 0 || indexOf(r, digits) >= 0) {
            return false
        }
        le--
        digits[le] = r
        n /= 10
    }
    return true
}
 
fun removeDigit(digits: IntArray, le: Int, idx: Int): Int {
    val pows = intArrayOf(1, 10, 100, 1000, 10000)
    var sum = 0
    var pow = pows[le - 2].toDouble()
    for (i in 0 until le) {
        if (i == idx) {
            continue
        }
        sum += digits[i] * pow.toInt()
        pow /= 10.0
    }
    return sum
}
 
fun main() {
    val lims = arrayOf(intArrayOf(12, 97), intArrayOf(123, 986), intArrayOf(1234, 9875), intArrayOf(12345, 98764))
    val count = IntArray(5)
    val omitted = Array(5) { IntArray(10) }
    val upperBound = lims.size
    for (i in 0 until upperBound) {
        val nDigits = IntArray(i + 2)
        val dDigits = IntArray(i + 2)
        val blank = IntArray(i + 2)
        for (n in lims[i][0]..lims[i][1]) {
            blank.copyInto(nDigits)
            val nOk = getDigits(n, i + 2, nDigits)
            if (!nOk) {
                continue
            }
            for (d in n + 1..lims[i][1] + 1) {
                blank.copyInto(dDigits)
                val dOk = getDigits(d, i + 2, dDigits)
                if (!dOk) {
                    continue
                }
                for (nix in nDigits.indices) {
                    val digit = nDigits[nix]
                    val dix = indexOf(digit, dDigits)
                    if (dix >= 0) {
                        val rn = removeDigit(nDigits, i + 2, nix)
                        val rd = removeDigit(dDigits, i + 2, dix)
                        if (n.toDouble() / d == rn.toDouble() / rd) {
                            count[i]++
                            omitted[i][digit]++
                            if (count[i] <= 12) {
                                println("$n/$d = $rn/$rd by omitting $digit's")
                            }
                        }
                    }
                }
            }
        }
        println()
    }
 
    for (i in 2..5) {
        println("There are ${count[i - 2]} $i-digit fractions of which:")
        for (j in 1..9) {
            if (omitted[i - 2][j] == 0) {
                continue
            }
            println("%6d have $j's omitted".format(omitted[i - 2][j]));1

import kotlin.concurrent.thread
import java.util.concurrent.Semaphore
import kotlin.concurrent.thread
import java.util.concurrent.Semaphore
 
// Only 4 workers can run in the same time
val sem = Semaphore(4)
 
val workers = mutableListOf<Thread>()
var running = true
 
fun worker() {
    val me = Thread.currentThread()
    while (true) {
        sem.acquire()
        try {
            if (!running) {
                break
            }
            println("${me.name} acquired semaphore")
            Thread.sleep(2000)
        } finally {
            sem.release()
        }
        Thread.sleep(10) // Let others acquire
    }
}
 
// Start 10 workers
for (i in 0..9) {
    thread(name = i.toString()) {
        worker()
    }
}
 
// Main loop
try {
    while (true) {
        Thread.sleep(100)
    }
} catch (e: InterruptedException) {
    running = false
    for (t in workers) {
        t.join()
    }
};1

operator fun MyDate.rangeTo(other: MyDate): DateRange = DateRange(this, other)

class DateRange(val start: MyDate, val endInclusive: MyDate) {
    operator fun contains(d: MyDate) = start <= d && d <= endInclusive
    operator fun iterator(): Iterator<MyDate> {
        return object : Iterator<MyDate> {
            var currentDate = start.copy()
            fun hasNext(): Boolean {
                return currentDate <= endInclusive
            }

            fun next(): MyDate {
                val retDate = currentDate
                currentDate = currentDate.nextDay()
                return retDate
            }
        }
    }
};0

import java.util.*
 
fun main(args: Array<String>) {
    var w = 0
    var h = 0
    var pix: ByteArray? = null
    fun refresh(x: Int, y: Int) {
        var i: Int
        var j: Int
        var k: Int
        print("\u001B[H")
        for (i in 0..h - 1) {
            for (j in 0..w - 1) {
                k = i * w + j
                print(if (pix!![k]!= 0.toByte()) '#' else'')
            }
            println()
        }
    }
    fun walk() {
        var dx = 0
        var dy = 1
        var i: Int
        var k: Int
        var x = w / 2
        var y = h / 2
        pix = ByteArray(w * h)
        print("\u001B[H\u001B[J")
        while (true) {
            i = y * w + x
            if (pix!![i]!= 0.toByte()) {
                k = dx
                dx = -dy
                dy = k
            } else {
                k = dy
                dy = -dx
                dx = k
            }
            pix!![i] = (pix!![i] xor 1).toByte()
            print("\u001B[" + (y + 1) + ";" + (x + 1) + "H" + if (pix!![i]!= 0.toByte()) '#' else'')
            x += dx
            y += dy
            k = 0
            if (x < 0) {
                System.arraycopy(pix, 1, pix, 0, w * h - 1)
                for (i in 0..w * h - 1 step w) {
                    pix!![i] = 0
                }
                x++
                k = 1
            } else if (x >= w) {
                System.arraycopy(pix, 1, pix, 0, w * h - 1)
                for (i in w - 1..w * h - 1 step w) {
                    pix!![i] = 0
                }
                x--
                k = 1
            }
            if (y >= h) {
                System.arraycopy(pix, w, pix, 0, w * (h - 1))
                Arrays.fill(pix, w * (h - 1), w * h, 0.toByte())
                y--
                k = 1
            } else if (y < 0) {
                System.arraycopy(pix, w, pix, 0, w * (h - 1))
                Arrays.fill(pix, 0, w, 0.toByte())
                y++
                k = 1
            }
            if (k == 1) {
                refresh(x, y)
            }
            print("\u001B[" + (y + 1) + ";" + (x + 1) + "H\u001B[31m@\u001B[m")
            System.out.flush()
            Thread.sleep(10)
        }
    }
    if (args.size > 0) {
        w = Integer.parseInt(args[0])
    }
    if (args.size > 1) {
        h = Integer.parseInt(args[1])
    }
    if (w < 40) {
        w = 40
    }
    if (h < 25) {
        h = 25
    }
    walk()
};1

fun calculateAverageSpeed(segments: List<Pair<Double, Double>>): Double {
    var totalDistance = 0.0
    var totalTime = 0.0
    for ((distance, time) in segments) {
        totalDistance += distance
        totalTime += time
    }
    return totalDistance / totalTime
