fun main() {
    val capacity = 15.0
    val numberOfItems = 9
    val items = arrayOfNulls<Item>(numberOfItems + 1)
    var result = 0.0
    var number = 1
    items[1] = Item("beef", 3.8, 36.0)
    items[2] = Item("pork", 5.4, 43.0)
    items[3] = Item("ham", 3.6, 90.0)
    items[4] = Item("greaves", 2.4, 45.0)
    items[5] = Item("flitch", 4.0, 30.0)
    items[6] = Item("brawn", 2.5, 56.0)
    items[7] = Item("welt", 3.7, 67.0)
    items[8] = Item("salami", 3.0, 95.0)
    items[9] = Item("sausage", 5.9, 98.0)
    items.sortByDescending { it.price / it.weight }
    while (capacity > 0.0 && number <= numberOfItems) {
        if (items[number]!!.weight <= capacity) {
            result += items[number]!!.price
            capacity -= items[number]!!.weight
            items[number]!!.m = 1.0
        } else {
            result += items[number]!!.price * (capacity / items[number]!!.weight)
            items[number]!!.m = capacity / items[number]!!.weight
            capacity = 0.0
        }
        number++
    }
    println("Total Value = $result")
    println("Total Weight = ${15.0 - capacity}")
    println("Items Used:")
    for (i in 1..numberOfItems) {
        if (items[i]!!.m > 0) {
            println("We took ${items[i]!!.m * items[i]!!.weight}kg of \"${items[i]!!.name}\" and the value it brought is ${items[i]!!.price * items[i]!!.m}")
        }
    }
}
 
