fun mianChowla(n: Int): List<Int> {
    val mc = MutableList(n) { 0 }
    mc[0] = 1
    var is = mutableListOf(2)
    var sum: Int
    for (i in 1 until n) {
        val le = is.size
        jloop@ for (j in mc[i - 1] + 1..Int.MAX_VALUE) {
            mc[i] = j
            for (k in 0..i) {
                sum = mc[k] + j
                if (contains(is, sum)) {
                    is = is.subList(0, le)
                    continue@jloop
                }
                is.add(sum)
            }
            break
        }
    }
    return mc
}
 
fun main() {
    val mc = mianChowla(100)
    println("The first 30 terms of the Mian-Chowla sequence are:")
    println(mc.subList(0, 30))
    println("\nTerms 91 to 100 of the Mian-Chowla sequence are:")
    println(mc.subList(90, 100))
};1

fun <T> Collection<T>.allCombinations(): Sequence<Pair<T, T>> {
    return sequence {
        for (a in this@allCombinations) {
            for (b in this@allCombinations) {
                if (a != b) {
                    yield(Pair(a, b))
                }
            }
        }
    }
};0

fun countSupportedBricks(brick: Brick, falling: MutableSet<Brick> = mutableSetOf(brick)): Int {
  return brick.supports
    .filter { it !in falling && it.supportedBy.all { it in falling } }
    .let {
      falling.addAll(it)
      it.size + it.sumOf { countSupportedBricks(it, falling) }
    }
};0

