            for (i in 0..rope.size-2) {
                val dx = rope[i].first - rope[i+1].first
                val dy = rope[i].second - rope[i+1].second
                if (Math.abs(dx) >= 2 || Math.abs(dy) >= 2)
                    rope[i+1] = rope[i+1] + Pair(dx.coerceIn(-1..1), dy.coerceIn(-1..1))
            }
            visited2.add(rope[1])
            visited10.add(rope.last())
        }
    }
