fun randomSampling(predictions: List<List<Double>>, number: Int): List<Int> {
    val total = predictions.size
    if (number == 0) {
        return emptyList()
    }
    if (number >= total) {
        val shuffled = (0 until total).toMutableList()
        shuffled.shuffle(Random)
        return shuffled
    }
    val selected = (0 until total).toList().shuffled(Random).take(number).sorted()
    return selected
