import kotlin.math.pow
 
val mask64 = (1.0.pow(64.0) - 1).toLong()
val mask32 = (1.0.pow(32.0) - 1).toLong()
val const = 0x2545F4914F6CDD1D
 
class Xorshift_star(var seed: Long = 0) {
 
    init {
        seed = seed and mask64
    }
 
    fun seed(num: Long) {
        seed = num and mask64
    }
 
    fun next_int(): Long {
        var x = seed
        x = (x xor (x ushr 12)) and mask64
        x = (x xor (x shl 25)) and mask64
        x = (x xor (x ushr 27)) and mask64
        seed = x
        val answer = ((x * const) and mask64 ushr 32) and mask32
        return answer
    }
 
    fun next_float(): Double {
        return next_int() / (1.0.pow(32.0))
    }
}
 
