fun validateBets(bets: List<Map<String, Any?>>): Boolean {
    for (bet in bets) {
        // betId
        val betId = bet["betId"]
        if (betId !is String || betId.isEmpty()) {
            return false
        }
        // wagerNumber
        val wagerNumber = bet["wagerNumber"]
        if (wagerNumber !is Int || (wagerNumber is Boolean) || wagerNumber < 0) {
            return false
        }
        // placedAt
        val placedAt = bet["placedAt"]
        if (placedAt !is String) {
            return false
        }
        try {
            var isoCandidate = placedAt
            if (isoCandidate.endsWith("Z")) {
                isoCandidate = isoCandidate.removeSuffix("Z") + "+00:00"
            }
            OffsetDateTime.parse(isoCandidate)
        } catch (e: DateTimeParseException) {
            return false
        }
        // win
        val win = bet["win"]
        if (win !is Boolean) {
            return false
        }
    }
    return true
};1

 
import java.util.stream.Collectors
 
/* returns the number itself, its smallest prime factor and all its prime factors */
fun primeFactorInfo(n: Int): Triple<Int, Int, List<Int>> {
    if (n <= 1) throw IllegalArgumentException("Number must be more than one")
    if (isPrime(n)) return Triple(n, n, listOf(n))
    val factors = mutableListOf<Int>()
    var factor = 2
    var nn = n
    while (true) {
        if (nn % factor == 0) {
            factors.add(factor)
            nn /= factor
            if (nn == 1) return Triple(n, factors.min()!!, factors)
            if (isPrime(nn)) factor = nn
        }
        else if (factor >= 3) factor += 2
        else factor = 3
    }
}
 
fun isPrime(n: Int) : Boolean {
    if (n < 2) return false
    if (n % 2 == 0) return n == 2
    if (n % 3 == 0) return n == 3
    var d = 5
    while (d * d <= n) {
        if (n % d == 0) return false
        d += 2
        if (n % d == 0) return false
        d += 4
    }
    return true
}
 
