class Polynomial(val coefficients: List<Double>) {
    fun evaluate(x: Double): Double {
        var result = 0.0
        for ((i, coeff) in coefficients.withIndex()) {
            result += coeff * Math.pow(x, i.toDouble())
        }
        return result
    }

    operator fun plus(other: Polynomial): Polynomial {
        val maxLen = maxOf(this.coefficients.size, other.coefficients.size)
        val paddedSelf = this.coefficients + List(maxLen - this.coefficients.size) { 0.0 }
        val paddedOther = other.coefficients + List(maxLen - other.coefficients.size) { 0.0 }
        val sumCoeff = paddedSelf.zip(paddedOther) { a, b -> a + b }
        return Polynomial(sumCoeff)
    }

    operator fun times(other: Polynomial): Polynomial {
        val resultLength = this.coefficients.size + other.coefficients.size - 1
        val resultCoeff = MutableList(resultLength) { 0.0 }
        for (i in this.coefficients.indices) {
            for (j in other.coefficients.indices) {
                resultCoeff[i + j] += this.coefficients[i] * other.coefficients[j]
            }
        }
        return Polynomial(resultCoeff)
    }
};1

