fun tankProduct(a: List<String>): String {
    fun isBeautiful(s: String): Boolean {
        if (s == "0") return true
        if (s.count { it == '1' } != 1) return false
        return s.all { it == '0' || it == '1' }
    }
    if (a.any { it == "0" }) {
        return "0"
    }
    var nonBeautiful: String? = null
    var sumExp = 0
    for (s in a) {
        if (isBeautiful(s)) {
            sumExp += s.length - 1
        } else {
            nonBeautiful = s
        }
    }
    if (nonBeautiful == null) {
        // All numbers are beautiful
        return "1" + "0".repeat(sumExp)
    }
    return nonBeautiful + "0".repeat(sumExp)
};1

fun getDiskAt(board: Map<Pair<Int, Int>, Any?>, position: Any?): Any? {
    // 1. Basic type validation: must be Pair or List
    val posKey: Pair<Int, Int>? = when (position) {
        is Pair<*, *> -> {
            val first = position.first
            val second = position.second
            if (first is Int && second is Int) {
                Pair(first, second)
            } else {
                return null
            }
        }
        is List<*> -> {
            if (position.size == 2 && position[0] is Int && position[1] is Int) {
                @Suppress("UNCHECKED_CAST")
                Pair(position[0] as Int, position[1] as Int)
            } else {
                return null
            }
        }
        else -> return null
    }
    // 2. Return the disk if present; otherwise, null
    return board[posKey]
};1

