fun eApprox(n: Int): Double {
    fun mul(a: Double): (Double) -> Double = { b: Double -> a * b }
    fun sum(xs: List<Double>): Double = xs.reduce { a, x -> a + x }
    fun enumFromTo(m: Int): (Int) -> List<Int> = { n: Int ->
        (m..n).toList()
    }
    fun scanl(f: (Double) -> (Double) -> Double): (Double) -> (List<Double>) -> List<Double> = { startValue: Double ->
        { xs: List<Double> ->
            xs.fold(listOf(startValue)) { a, x ->
                val v = f(a[0])(x)
                a + v
            }
        }
    }
    return sum(
        scanl(mul)(1.0)(
            enumFromTo(1)(n).map { x: Int -> 1.0 / x }
        )
    )
};1

fun Bitmap.cubicbezier(x0: Int, y0: Int, x1: Int, y1: Int, x2: Int, y2: Int, x3: Int, y3: Int, n: Int = 20) {
    val pts = mutableListOf<Pair<Int, Int>>()
    for (i in 0..n) {
        val t = i / n.toFloat()
        val a = (1.0 - t).pow(3)
        val b = 3.0 * t * (1.0 - t).pow(2)
        val c = 3.0 * t.pow(2) * (1.0 - t)
        val d = t.pow(3)
        val x = (a * x0 + b * x1 + c * x2 + d * x3).toInt()
        val y = (a * y0 + b * y1 + c * y2 + d * y3).toInt()
        pts.add(Pair(x, y))
    }
    for (i in 0 until n) {
        line(pts[i].first, pts[i].second, pts[i + 1].first, pts[i + 1].second)
    }
