fun countReturnableRooms(testCases: List<Pair<Int, String>>): List<Int> {
    val res = mutableListOf<Int>()
    for ((n, s) in testCases) {
        val onlyRight = s.all { it == '>' || it == '-' }
        val onlyLeft = s.all { it == '<' || it == '-' }
        if (onlyRight || onlyLeft) {
            res.add(n)
            continue
        }
        var answer = 0
        for (i in 0 until n) {
            if (s[i] == '-' || s[(i - 1 + n) % n] == '-') {
                answer += 1
            }
        }
        res.add(answer)
    }
    return res
};1

