fun findBestCombination(depths: List<Int>, minWeights: List<Int>): Pair<Int, Int> {
    var bestProduct = Int.MIN_VALUE
    var bestDepth: Int? = null
    var bestWeight: Int? = null

    for (d in depths) {
        for (w in minWeights) {
            val prod = d * w
            if (prod > bestProduct || (prod == bestProduct && (bestDepth == null || d < bestDepth))) {
                bestProduct = prod
                bestDepth = d
                bestWeight = w
            }
        }
    }
    if (bestDepth == null || bestWeight == null) {
        throw IllegalArgumentException("Both input lists must contain at least one element.")
    }
    return Pair(bestDepth, bestWeight)
};1

class TreeNode(var `val`: Int = 0, var left: TreeNode? = null, var right: TreeNode? = null)

fun maxPathSum(root: TreeNode?): Int {
    val maxSum = intArrayOf(Int.MIN_VALUE)
    fun helper(node: TreeNode?): Int {
        if (node == null) return 0
        val left = kotlin.math.max(helper(node.left), 0)
        val right = kotlin.math.max(helper(node.right), 0)
        val currentSum = node.`val` + left + right
        if (currentSum > maxSum[0]) {
            maxSum[0] = currentSum
        }
        return node.`val` + kotlin.math.max(left, right)
    }
    helper(root)
    return maxSum[0]
};1

fun validateConfigData(globalConfig: Map<String, Any?>, cameraConfigs: List<Map<String, Any?>>): Boolean {
    val expectedGlobal = mapOf(
        "app_name" to String::class,
        "version" to String::class,
        "max_users" to Int::class
    )
    val expectedCamera = mapOf(
        "camera_id" to Int::class,
        "camera_name" to String::class,
        "resolution" to String::class
    )

    fun validDict(candidate: Map<String, Any?>, spec: Map<String, kotlin.reflect.KClass<*>>): Boolean {
        // Must have exactly the same set of keys
        if (candidate.keys != spec.keys) return false

        for ((key, type) in spec) {
            val value = candidate[key]
            if (value == null) return false
            if (type == Int::class && value is Boolean) return false
            if (!type.isInstance(value)) return false
        }
        return true
    }

    // Validate globalConfig
    if (!validDict(globalConfig, expectedGlobal)) return false
    // Validate cameraConfigs is a list of maps
    for (camConfig in cameraConfigs) {
        if (!validDict(camConfig, expectedCamera)) return false
    }
    return true
};1

 
