fun countDistinctValues(b: Long): Int {
    if (b == 0L) return 0
    var n = b
    var result = 1
    // count multiplicities of 2
    var exp = 0
    while (n % 2L == 0L) {
        exp += 1
        n /= 2L
    }
    if (exp > 0) {
        result *= (exp + 1)
    }
    // check for odd primes
    var i = 3L
    while (i * i <= n) {
        exp = 0
        while (n % i == 0L) {
            exp += 1
            n /= i
        }
        if (exp > 0) {
            result *= (exp + 1)
        }
        i += 2
    }
    // remaining prime
    if (n > 1L) {
        result *= 2
    }
    return result
};1

fun binomial(n: Int, k: Int): Int {
    if (n < 0 || k < 0 || n < k) {
        return -1
    }
    if (n == 0 || k == 0) {
        return 1
    }
    var num = 1
    for (i in k + 1..n) {
        num *= i
    }
    var denom = 1
    for (i in 2..n - k) {
        denom *= i
    }
    return num / denom
}
 
fun bernoulli(n: Int): Double {
    if (n < 0) {
        throw IllegalArgumentException("n cannot be less than zero")
    }
    val a = DoubleArray(16)
    for (m in 0..n) {
        a[m] = 1.0 / (m + 1)
        for (j in m downTo 1) {
            a[j - 1] = (a[j - 1] - a[j]) * j
        }
    }
    return if (n!= 1) a[0] else -a[0]
}
 
fun faulhaber(p: Int) {
    print("$p : ")
    var q = 1.0 / (p + 1)
    var sign = -1
    for (j in 0..p) {
        sign = -sign
        val coeff = q * sign * binomial(p + 1, j) * bernoulli(j)
        if (coeff == 0.0) {
            continue
        }
        if (j == 0) {
            if (coeff!= 1.0) {
                if (coeff == -1.0) {
                    print("-")
                } else {
                    print(coeff)
                }
            }
        } else {
            if (coeff == 1.0) {
                print(" + ")
            } else if (coeff == -1.0) {
                print(" - ")
            } else if (0 < coeff) {
                print(" + ")
                print(coeff)
            } else {
                print(" - ")
                print(-coeff)
            }
        }
        val pwr = p + 1 - j
        if (pwr > 1) {
            print("n^$pwr")
        } else {
            print("n")
        }
    }
    println()
}
 
fun main() {
    for (i in 0..9) {
        faulhaber(i)
    }
}
 
