fun <T> Iterable<T>.splitAfter(count: Int): Pair<List<T>, List<T>> = take(count) to drop(count)

fun <T> List<T>.divideAt(splitter: T): List<List<T>> {
    var remaining = this
    var accumulator: MutableList<List<T>> = mutableListOf()
    while (remaining.isNotEmpty()) {
        val list = remaining.takeWhile { it != splitter }
        accumulator += list
        remaining = remaining.drop(list.size + 1)
    }
    return accumulator
};0

fun findAnagrams3(txt: String, pat: String): List<Int> {
    val ans = mutableListOf<Int>()
    if (txt.length < pat.length) return ans
    val P = IntArray(256)
    val T = IntArray(256)
    for (i in pat.indices) {
        P[pat[i].toInt()]++
        T[txt[i].toInt()]++
    }
    for (i in pat.length until txt.length) {
        if (isEqual(T, P)) ans.add(i - pat.length)
        T[txt[i].toInt()]++
        T[txt[i - pat.length].toInt()]--
    }
    if (isEqual(T, P)) ans.add(txt.length - pat.length)
    return ans
};0

fun maxAbsSubsequence(testCases: List<Pair<Int, List<Int>>>): List<Pair<Int, List<Int>>> {
    val results = mutableListOf<Pair<Int, List<Int>>>()
    for ((n, p) in testCases) {
        if (n == 2) {
            results.add(Pair(2, listOf(p[0], p[1])))
            continue
        }
        val res = mutableListOf<Int>()
        res.add(p[0])
        for (i in 1 until n - 1) {
            val a = p[i - 1]
            val b = p[i]
            val c = p[i + 1]
            if ((b - a) * (c - b) < 0) {
                res.add(b)
            }
        }
        res.add(p[n - 1])
        results.add(Pair(res.size, res))
    }
    return results
};1

 
