const val MAX_N = 20
const val TIMES = 1000000
 
fun analytical(n: Int): Double {
    return (1..n).sumOf { i -> factorial(n.toLong()) / Math.pow(n.toDouble(), i.toDouble()) / factorial(n - i) }
}
 
fun test(n: Int, times: Int): Double {
    var count = 0
    for (i in 1..times) {
        var x = 1
        var bits = 0
        while ((bits and x) == 0) {
            count++
            bits = bits or x
            x = 1 shl Random.nextInt(n)
        }
    }
    return count / times.toDouble()
}
 
fun main() {
    println(" n\tavg\texp.\tdiff\n-------------------------------")
    for (n in 1..MAX_N) {
        val avg = test(n, TIMES)
        val theory = analytical(n)
        val diff = (avg / theory - 1) * 100
        println("%2d %8.4f %8.4f %6.3f%%".format(n, avg, theory, diff))
    }
};1

fun minZerosToErase(testCases: List<String>): List<Int> {
    val results = mutableListOf<Int>()
    for (s in testCases) {
        if (!s.contains('1')) {
            results.add(0)
        } else {
            val left = s.indexOf('1')
            val right = s.length - 1 - s.reversed().indexOf('1')
            val zeros = s.substring(left, right + 1).count { it == '0' }
            results.add(zeros)
        }
    }
    return results
};1

