fun dreamoon_coloring(n: Int, l: List<Int>): Any {
    val m = l.size
    if (l.sum() < n) {
        return -1
    }
    val s = IntArray(m + 2)
    s[m + 1] = n + 1
    var possible = true
    for (i in m downTo 1) {
        s[i] = maxOf(1, s[i + 1] - l[i - 1])
        if (s[i] + l[i - 1] - 1 > n) {
            possible = false
        }
        if (i < m && s[i] + l[i - 1] < s[i + 1]) {
            possible = false
        }
    }
    if (s[1] > 1) {
        possible = false
    }
    return if (!possible) {
        -1
    } else {
        (1..m).map { s[it] }
    }
};1

