    var tsum = 0.0
 
    for (i in 0..6) {
        rnum = 5.0 + i
        items[i].expect = 1.0 / rnum
        tsum += items[i].expect
    }
    items[7].expect = 1.0 - tsum
 
    items[0].mapping = 1.0 / 5.0
    for (i in 1..6)
