fun willPineappleBark(t: Int, s: Int, x: Int): String {
    if (x == t) {
        return "YES"
    } else if (x < t) {
        return "NO"
    } else {
        val m = x - t
        if (m < s) {
            return "NO"
        } else {
            val remainder = m % s
            if (remainder == 0) {
                return "YES"
            } else if (remainder == 1 && m != 1) {
                return "YES"
            } else {
                return "NO"
            }
        }
    }
};1

