fun moveKnot(knot: Pair<Int, Int>, knotToFollow: Pair<Int, Int>): Pair<Int, Int> {
    val xDiff = knotToFollow.first - knot.first
    val yDiff = knotToFollow.second - knot.second
    var (xNew, yNew) = knot
    if (abs(xDiff) + abs(yDiff) >= 3) {
        xNew = if (xDiff > 0) knot.first + 1 else knot.first - 1
        yNew = if (yDiff > 0) knot.second + 1 else knot.second - 1
    }
    if (abs(xDiff) == 2 && yDiff == 0) {
        xNew = if (xDiff > 0) knot.first + 1 else knot.first - 1
    }
    if (xDiff == 0 && abs(yDiff) == 2) {
        yNew = if (yDiff > 0) knot.second + 1 else knot.second - 1
    }
    return xNew to yNew
};0

import java.math.BigDecimal
import java.math.MathContext
import java.util.Objects

fun main(args: Array<String>) {
    val con1024 = MathContext(1024)
    val bigTwo = BigDecimal(2)
    val bigFour = BigDecimal(4)

    fun bigSqrt(bd: BigDecimal, con: MathContext): BigDecimal {
        var x0 = BigDecimal.ZERO
        var x1 = BigDecimal.valueOf(Math.sqrt(bd.toDouble()))
        while (!Objects.equals(x0, x1)) {
            x0 = x1
            x1 = bd.divide(x0, con).add(x0).divide(bigTwo, con)
        }
        return x1
    }

    var a = BigDecimal.ONE
    var g = a.divide(bigSqrt(bigTwo, con1024), con1024)
    var t: BigDecimal
    var sum = BigDecimal.ZERO
    var pow = bigTwo
    while (!Objects.equals(a, g)) {
        t = a.add(g).divide(bigTwo, con1024)
        g = bigSqrt(a.multiply(g), con1024)
        a = t
        pow = pow.multiply(bigTwo)
        sum = sum.add(a.multiply(a).subtract(g.multiply(g)).multiply(pow))
    }
    val pi = bigFour.multiply(a.multiply(a)).divide(BigDecimal.ONE.subtract(sum), con1024)
    println(pi)
};1

