fun select(list: List<String>, prompt: String): String {
    if (list.size == 0) return ""
    val sc = Scanner(System.`in`)
    var ret: String? = null
    do {
        for (i in list.indices) {
            println(i + ": " + list[i])
        }
        print(prompt)
        val index = sc.nextInt()
        if (index >= 0 && index < list.size) {
            ret = list[index]
        }
    } while (ret == null)
    return ret
};1

fun sortFruits(fruits: List<String>): List<String> {
    // Sort a list of fruit names alphabetically.
    // The comparison is done in a case-insensitive way so that names such as
    // 'apple', 'Apple', and 'APPLE' are treated as equal for ordering purposes.
    // Any non-alphabetic characters (punctuation marks, digits, etc.) are kept
    // exactly as they appear in the original strings; they take part in the
    // comparison exactly where they occur in the string.
    return fruits.sortedBy { it.lowercase() }
