fun Int.isEvenBitwise(): Boolean {
    return (this and 1) == 0
}

fun Int.isOddBitwise(): Boolean {
    return (this and 1)!= 0
}

fun Int.isEvenRemainder(): Boolean {
    val remainder = this % 2
    return remainder == 0
}

fun Int.isOddRemainder(): Boolean {
    val remainder = this % 2
    return remainder!= 0
}

fun Int.isEvenModulo(): Boolean {
    return (this % 2) == 0
}

fun Int.isOddModulo(): Boolean {
    return (this % 2)!= 0
}

