import kotlin.concurrent.timer
 
fun sleepsort(values: List<Int>): List<Int> {
    var result = mutableListOf<Int>()
    var mx = values[0]
    for (v in values) {
        if (mx < v) mx = v
        timer(v) { result.add(v) }
    }
    Thread.sleep(mx + 1)
    return result
}
 
fun main(args: Array<String>) {
