fun processQueries(s: String, queries: List<List<Any>>): List<Int> {
    val sArray = s.toCharArray()
    val results = mutableListOf<Int>()
    for (query in queries) {
        if (query[0] == "update") {
            val i = query[1] as Int
            val c = query[2] as Char
            sArray[i-1] = c
        } else if (query[0] == "count") {
            val l = query[1] as Int
            val r = query[2] as Int
            val y = query[3] as String
            val m = y.length
            val substring = sArray.sliceArray((l-1)..(r-1))
            var count = 0
            val upper = r-l+2-m
            for (start in 0 until upper) {
                var match = true
                for (j in 0 until m) {
                    if (substring[start+j] != y[j]) {
                        match = false
                        break
                    }
                }
                if (match) count += 1
            }
            results.add(count)
        }
    }
    return results
};1

