fun sumGcdSequences(N: Int, K: Int): Int {
    val MOD = 1_000_000_007
    val maxD = K
    val f = LongArray(maxD + 1)
    for (d in 1..maxD) {
        val x = K / d
        f[d] = modPow(x.toLong(), N.toLong(), MOD.toLong())
    }
    for (d in maxD downTo 1) {
        var m = 2 * d
        while (m <= maxD) {
            f[d] = (f[d] - f[m] + MOD) % MOD
            m += d
        }
    }
    var ans = 0L
    for (d in 1..maxD) {
        ans = (ans + d * f[d]) % MOD
    }
    return ans.toInt()
}

// Helper function for modular exponentiation
fun modPow(base: Long, exp: Long, mod: Long): Long {
    var result = 1L
    var b = base % mod
    var e = exp
    while (e > 0) {
        if ((e and 1L) == 1L) {
            result = (result * b) % mod
        }
        b = (b * b) % mod
        e = e shr 1
    }
    return result
};1

private val HEX_24_PATTERN = Regex("^[0-9a-fA-F]{24}$")

fun isValidObjectId(value: String?): Boolean {
    /*
    Determine whether `value` is a valid MongoDB-style ObjectId.

    A valid ObjectId:
        * is a non-empty string,
        * is exactly 24 characters long,
        * contains only hexadecimal digits (0–9, a–f, A–F).

    Parameters
    ----------
    value : String?
        The string to validate.

    Returns
    -------
    Boolean
        true if `value` is a valid ObjectId, false otherwise.
    */
    if (value == null || value.isEmpty()) {
        return false
    }
    return HEX_24_PATTERN.matches(value)
};1

