fun reduce(numDigits: Int) {
    println("Fractions with digits of length $numDigits where cancellation is valid.  Examples:")
 
    //  Generate allowed numerator's and denominator's
    val min = Math.pow(10.0, numDigits - 1).toInt()
    val max = Math.pow(10.0, numDigits.toDouble()).toInt() - 1
    val values = ArrayList<Int>()
    for (number in min..max) {
        if (isValid(number)) {
            values.add(number)
        }
    }
 
    val cancelCount = HashMap<Int, Int>()
    val size = values.size
    var solutions = 0
    for (nIndex in 0 until size - 1) {
        val numerator = values[nIndex]
        //  Must be proper fraction
        for (dIndex in nIndex + 1 until size) {
            val denominator = values[dIndex]
            for (commonDigit in digitsInCommon(numerator, denominator)) {
                val numRemoved = removeDigit(numerator, commonDigit)
                val denRemoved = removeDigit(denominator, commonDigit)
                if (numerator * denRemoved == denominator * numRemoved) {
                    solutions++
                    cancelCount.merge(commonDigit, 1) { v1, v2 -> v1 + v2 }
                    if (solutions <= 12) {
                        println("    When $commonDigit is removed, $numerator/$denominator = $numRemoved/$denRemoved")
                    }
                }
            }
        }
    }
    println("Number of fractions where cancellation is valid = $solutions.")
    val sorted = ArrayList(cancelCount.keys)
    Collections.sort(sorted)
    for (removed in sorted) {
        println("    The digit $removed was removed ${cancelCount[removed]} times.")
    }
    println()
}
 
private val powers = intArrayOf(1, 10, 100, 1000, 10000, 100000)
 
//  Remove the specified digit.
fun removeDigit(n: Int, removed: Int): Int {
    var m = 0
    var pow = 0
    var n = n
    while (n > 0) {
        val r = n % 10
        if (r!= removed) {
            m = m + r * powers[pow]
            pow++
        }
        n /= 10
    }
    return m
}
 
