// RECAMAN --------------------------------------------
 
// recamanUpto :: (Int -> Set Int > [Int] -> Bool) -> [Int]
fun recamanUpto(p: (Int, Set<Int>, List<Int>) -> Boolean): List<Int> {
    var i = 1
    var r = 0 // First term of series
    var rs = listOf(r)
    val seen = mutableSetOf(r)
    while (!p(i, seen, rs)) {
        r = nextR(seen, i, r)
        seen.add(r)
        rs += r
        i++
    }
    return rs
}
 
// Next Recaman number.
 
// nextR :: Set Int -> Int -> Int
fun nextR(seen: Set<Int>, i: Int, n: Int): Int {
    val back = n - i
    return if (0 > back || seen.contains(back)) {
        n + i
    } else back
}
 
// GENERIC --------------------------------------------
 
// enumFromTo :: Int -> Int -> [Int]
fun enumFromTo(m: Int, n: Int): List<Int> =
    if (m <= n) iterateUntil(
        { x -> n <= x },
        { x -> 1 + x },
        m
    ) else emptyList()
 
// isSubsetOf :: Ord a => Set a -> Set a -> Bool
fun <T> Set<T>.isSubSetOf(b: Set<T>): Boolean =
    this.all { b.contains(it) }
 
// iterateUntil :: (a -> Bool) -> (a -> a) -> a -> [a]
fun <T> iterateUntil(p: (T) -> Boolean, f: (T) -> T, x: T): List<T> {
    val vs = mutableListOf(x)
    var h = x
    while (!p(h)) {
        h = f(h)
        vs += h
    }
    return vs
}
 
// last :: [a] -> a
fun <T> List<T>.last(): T =
    if (0 < this.size) this[this.size - 1] else throw NoSuchElementException()
 
