fun labelTreeEdges(n: Int, edges: List<Pair<Int, Int>>): List<Int> {
    val adj = MutableList(n + 1) { mutableListOf<Int>() }
    for ((u, v) in edges) {
        adj[u].add(v)
        adj[v].add(u)
    }

    var maxDeg = -1
    var maxDegNode = -1
    for (i in 1..n) {
        val currentDeg = adj[i].size
        if (currentDeg > maxDeg) {
            maxDeg = currentDeg
            maxDegNode = i
        }
    }
    val result = MutableList(n - 1) { 0 }
    var currentLabel = 0
    val otherEdgesIndices = mutableListOf<Int>()
    for ((idx, edge) in edges.withIndex()) {
        val (u, v) = edge
        if (u == maxDegNode || v == maxDegNode) {
            result[idx] = currentLabel
            currentLabel++
        } else {
            otherEdgesIndices.add(idx)
        }
    }
    val remainingLabels = (currentLabel until (n - 1)).toList()
    for ((i, idx) in otherEdgesIndices.withIndex()) {
        result[idx] = remainingLabels[i]
    }
    return result
};1

