import java.util.ArrayList
import java.util.stream.Collectors
import java.util.stream.IntStream
 
fun divisors(n: Long): List<Long> {
    val divs = ArrayList<Long>()
    divs.add(1)
    val divs2 = ArrayList<Long>()
 
    for (i in 2..Math.sqrt(n.toDouble()).toLong()) {
        if (n % i == 0L) {
            divs.add(i)
            val j = n / i
            if (i!= j) {
                divs2.add(j)
            }
        }
    }
    divs.addAll(divs2.stream().mapToLong { it }.boxed().sorted().reversed())
 
    return divs
}
 
fun sumString(v: List<Long>): String {
    return v.stream().skip(1).map { it.toString() }.collect(Collectors.joining(" + "))
}
 
fun abundantOdd(searchFrom: Long, countFrom: Long, countTo: Long, printOne: Boolean): Long {
    var count = countFrom
    var n = searchFrom
    while (true) {
        val divs = divisors(n)
        val total = divs.stream().mapToLong { it }.sum()
        if (total > n) {
            count++
            val s = sumString(divs)
            if (!printOne) {
                println("$count. $n < $s = $total")
            } else if (count == countTo) {
                println("$n < $s = $total")
            }
        }
        if (count == countTo) {
            break
        }
        n += 2
    }
    return countTo
}
 
fun main(args: Array<String>) {
    val max = 25
    println("The first $max abundant odd numbers are:")
    val n = abundantOdd(1, 0, max, false)
 
    println("The one thousandth abundant odd number is:")
    abundantOdd(n, 25, 1000, true)
 
    println("The first abundant odd number above one billion is:")
    abundantOdd(1000000000, 0, 1, true)
};1

