fun humble(n: Int): Array<BigInteger> {
    val two = BigInteger.valueOf(2)
    var twoTest = two
    val three = BigInteger.valueOf(3)
    var threeTest = three
    val five = BigInteger.valueOf(5)
    var fiveTest = five
    val seven = BigInteger.valueOf(7)
    var sevenTest = seven
    val results = Array(n, { BigInteger.ONE })
    var twoIndex = 0
    var threeIndex = 0
    var fiveIndex = 0
    var sevenIndex = 0
    for (index in 1 until n) {
        results[index] = twoTest.min(threeTest).min(fiveTest).min(sevenTest)
        if (results[index].compareTo(twoTest) == 0) {
            twoIndex++
            twoTest = two.multiply(results[twoIndex])
        }
        if (results[index].compareTo(threeTest) == 0) {
            threeIndex++
            threeTest = three.multiply(results[threeIndex])
        }
        if (results[index].compareTo(fiveTest) == 0) {
            fiveIndex++
            fiveTest = five.multiply(results[fiveIndex])
        }
        if (results[index].compareTo(sevenTest) == 0) {
            sevenIndex++
            sevenTest = seven.multiply(results[sevenIndex])
        }
    }
    return results
};1

fun firstAndLastUnique(s: String): List<Int> {
    // Returns the indices (0-based) of the first and last non-repeating characters
    // in the string `s`. If no such characters exist, returns listOf(-1, -1).
    val counts = IntArray(26) { 0 }
    for (ch in s) {
        counts[ch.code - 97] += 1
    }
    var first = -1
    var last = -1
    // Find first unique character
    for ((i, ch) in s.withIndex()) {
        if (counts[ch.code - 97] == 1) {
            first = i
            break
        }
    }
    // Find last unique character
    for (i in s.length - 1 downTo 0) {
        if (counts[s[i].code - 97] == 1) {
            last = i
            break
        }
    }
    return listOf(first, last)
};1

fun analyzeTitles(titles: List<String>): Pair<Char, Int> {
    val letterCounts = mutableMapOf<Char, Int>()
    for (title in titles) {
        if (title.isEmpty()) continue
        val firstLetter = title[0].uppercaseChar()
        letterCounts[firstLetter] = letterCounts.getOrDefault(firstLetter, 0) + 1
    }
    if (letterCounts.isEmpty()) {
        return Pair('\u0000', 0) // Using '\u0000' (null char) to represent ''
    }
    val mostFrequentCount = letterCounts.values.maxOrNull() ?: 0
    val tiedLetters = letterCounts
        .filter { it.value == mostFrequentCount }
        .keys
    val mostFrequentLetter = tiedLetters.minOrNull() ?: '\u0000'
    return Pair(mostFrequentLetter, mostFrequentCount)
};1

fun normalizeList(nums: List<Int>): List<Double> {
    val total = nums.sum()
    if (total == 0) {
        // Sum is zero (either the list is empty or contains only zeros)
        // Return a copy of the original list (converted to Double for consistency)
        return nums.map { it.toDouble() }
    }
    return nums.map { it.toDouble() / total }
};1

