fun getDatabases(dbNames: List<String>, dbDict: Map<String, Any>): List<Any> {
    if (dbNames !is List<*>) {
        throw IllegalArgumentException("dbNames must be a list of strings.")
    }
    if (dbDict !is Map<*, *>) {
        throw IllegalArgumentException("dbDict must be a map.")
    }
    val missing = dbNames.filter { !dbDict.containsKey(it) }
    if (missing.isNotEmpty()) {
        throw IllegalArgumentException("Database(s) not found: ${missing.joinToString(", ")}")
    }
    return dbNames.map { dbDict[it]!! }
};1

fun largestProduct(matrix: Array<Array<Int>>, n: Int): Long {
    var maxP = 0L
    for (i in matrix.indices) {
        for (j in matrix[i].indices) {
            if (matrix[i][j] == 0) continue
            if (matrix.size - i >= n) {
                val pv = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i + offset][j] }
                if (pv > maxP) {
                    maxP = pv
                }
            }
            if (matrix[i].size - j >= n) {
                val ph = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i][j + offset] }
                if (ph > maxP) {
                    maxP = ph
                }
            }
            if (matrix.size - i >= n && matrix[i].size - j >= n) {
                val pdr = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i + offset][j + offset] }
                if (pdr > maxP) {
                    maxP = pdr
                }
            }
            if (matrix.size - i >= n && j >= n - 1) {
                val pdl = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i + offset][j - offset] }
                if (pdl > maxP) {
                    maxP = pdl
                }
            }
        }
    }
    return maxP
};0

fun maxDiff(lst: List<Int>): Int {
    if (lst.size < 2) {
        return 0
    }
    return lst.maxOrNull()!! - lst.minOrNull()!!
}

fun maxDiffFirstHalf(lst: List<Int>): Int {
    val n = lst.size
    if (n < 2) {
        return 0
    }
    val firstHalfLength = (n + 1) / 2
    val firstHalf = lst.take(firstHalfLength)
    if (firstHalf.size < 2) {
        return 0
    }
    return firstHalf.maxOrNull()!! - firstHalf.minOrNull()!!
};1

fun maxDifference(arr: List<Int>): Int {
    val n = arr.size
    if (n < 2) return 0

    var minSoFar = arr[0]
    var maxDiff = arr[1] - arr[0]

    for (j in 1 until n) {
        val currentVal = arr[j]
        maxDiff = maxOf(maxDiff, currentVal - minSoFar)
        minSoFar = minOf(minSoFar, currentVal)
    }

    return maxDiff
};1

fun egyptian_division(dividend: Long, divisor: Long, remainder: Long?): Long {
    val SIZE = 64
    val powers = LongArray(SIZE)
    val doublings = LongArray(SIZE)
    var i = 0
    for (i in 0 until SIZE) {
        powers[i] = 1L shl i
        doublings[i] = divisor shl i
        if (doublings[i] > dividend) {
            break
        }
    }
    var answer = 0L
    var accumulator = 0L
    for (i in i - 1 downTo 0) {
        /*
         * If the current value of the accumulator added to the
         * doublings cell would be less than or equal to the
         * dividend then add it to the accumulator
         */
        if (accumulator + doublings[i] <= dividend) {
            accumulator += doublings[i]
            answer += powers[i]
        }
    }
    if (remainder!= null) {
        remainder = dividend - accumulator
    }
    return answer
}
 
