fun wordFreqList(text: String): List<Pair<Any, Int>> {
    // LinkedHashMap keeps insertion order.
    val counts = linkedMapOf<Any, Int>()

    fun addToken(token: Any) {
        counts[token] = counts.getOrDefault(token, 0) + 1
    }

    val currentWord = StringBuilder()

    for (ch in text) {
        if (ch.isLetter()) {
            currentWord.append(ch.lowercaseChar())
        } else {
            if (currentWord.isNotEmpty()) {
                addToken(currentWord.toString())
                currentWord.clear()
            }
            if (!ch.isWhitespace()) {
                addToken(ch.code)
            }
        }
    }

    if (currentWord.isNotEmpty()) {
        addToken(currentWord.toString())
    }

    return counts.entries.map { Pair(it.key, it.value) }
};1

