fun minCoinsNeeded(coins: List<Int>, amount: Int): Int {
    if (amount == 0) return 0
    if (coins.isEmpty()) return -1

    val INF = amount + 1
    val dp = IntArray(amount + 1) { INF }
    dp[0] = 0

    for (coin in coins) {
        for (curr in coin..amount) {
            dp[curr] = minOf(dp[curr], dp[curr - coin] + 1)
        }
    }
    return if (dp[amount] != INF) dp[amount] else -1
};1

