data class Rule(val key: Category?, val predicateOp: Operator, val predicateValue: Int, val next: String) {
    fun matches(ratings: Categories<Int>): Boolean {
        if (key == null) return true
        return when (predicateOp) {
            Operator.LT -> ratings[key] < predicateValue
            Operator.GT -> ratings[key] > predicateValue
        }
    }

    fun toString(): String {
        if (key == null) return next
        return "$key${"<>"[predicateOp.ordinal]}$predicateValue:$next"
    }
};0

 
fun main(args: Array<String>) {
    val a = mutableListOf(0)
    val used = mutableSetOf(0)
    val used1000 = mutableSetOf(0)
    var foundDup = false
    var n = 1
    while (n <= 15 || !foundDup || used1000.size < 1001) {
        var next = a[n - 1] - n
        if (next < 1 || used.contains(next)) next += 2 * n
        val alreadyUsed = used.contains(next)
        a.add(next)
        if (!alreadyUsed) {
            used.add(next)
            if (next in 0..1000) used1000.add(next)
        }
        if (n == 14) {
            println("The first 15 terms of the Recaman's sequence are: $a")
        }
        if (!foundDup && alreadyUsed) {
            println("The first duplicated term is a[$n] = $next")
            foundDup = true
        }
        if (used1000.size == 1001) {
            println("Terms up to a[$n] are needed to generate 0 to 1000")
        }
        n++
    }
};0

fun uniquePaths(m: Int, n: Int): Int {
    val dp = Array(m) { IntArray(n) { 1 } }
    for (i in 1 until m) {
        for (j in 1 until n) {
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
        }
    }
    return dp[m - 1][n - 1]
};1

fun calculatePredictionAccuracy(predictedValues: List<Int>, actualValues: List<Int>): Double {
    if (predictedValues.size != actualValues.size) {
        throw IllegalArgumentException("predictedValues and actualValues must be of the same length.")
    }
    if (predictedValues.isEmpty()) {
        return 0.0
    }
    val correctPredictions = predictedValues.zip(actualValues).count { it.first == it.second }
    val accuracyPercent = (correctPredictions.toDouble() / actualValues.size) * 100
    return String.format("%.2f", accuracyPercent).toDouble()
};1

fun ArrayList<ArrayList<Int>>.neighbours(y: Int, x: Int): ArrayList<Pair<Int, Pair<Int, Int>>> {
    val row = get(y)
    val nList = ArrayList<Pair<Int, Pair<Int, Int>>>()
    if (y == 0) {
        if (x == 0) {
            nList.addFor(y, x+1, this)
        } else if (x == row.size -1) {
            nList.addFor(y, x-1, this)
        } else {
            nList.addFor(y, x-1, this)
            nList.addFor(y, x+1, this)
        }
        nList.addFor(y+1, x, this)
    } else if (y == size-1) {
        if (x == row.size-1) {
            nList.addFor(y, x-1, this)
        } else if (x == 0) {
            nList.addFor(y, x+1, this)
        } else {
            nList.addFor(y, x-1, this)
            nList.addFor(y, x+1, this)
        }
        nList.addFor(y-1, x, this)
    } else {
        if (x > 0 && x < row.size-1) {
            nList.addFor(y, x-1, this)
            nList.addFor(y, x+1, this)
        } else if (x == 0) {
            nList.addFor(y, x+1, this)
        } else if (x == row.size-1) {
            nList.addFor(y, x-1, this)
        }
        nList.addFor(y+1, x, this)
        nList.addFor(y-1, x, this)
    }
    return nList
};0

fun shortestPathAllKeys(grid: List<String>): Int {
    if (grid.isEmpty()) return -1
    val nRows = grid.size
    val nCols = grid[0].length
    var totalKeysMask = 0
    var startR = -1
    var startC = -1
    for (r in grid.indices) {
        for (c in grid[r].indices) {
            val ch = grid[r][c]
            when {
                ch == '@' -> {
                    startR = r
                    startC = c
                }
                ch in 'a'..'f' -> {
                    totalKeysMask = totalKeysMask or (1 shl (ch - 'a'))
                }
            }
        }
    }

    data class State(val r: Int, val c: Int, val keys: Int)
    val queue: ArrayDeque<Array<Int>> = ArrayDeque()
    // queue要素: (row, col, keyMask, distance)
    queue.add(arrayOf(startR, startC, 0, 0))
    val visited = mutableSetOf<Triple<Int, Int, Int>>()
    visited.add(Triple(startR, startC, 0))
    val dirs = arrayOf(
        intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)
    )
    while (queue.isNotEmpty()) {
        val (r, c, keys, dist) = queue.removeFirst()
        if (keys == totalKeysMask) return dist
        for (d in dirs) {
            val nr = r + d[0]
            val nc = c + d[1]
            if (nr !in 0 until nRows || nc !in 0 until nCols) continue
            val cell = grid[nr][nc]
            if (cell == '#') continue
            var newKeys = keys
            if (cell in 'a'..'f') {
                newKeys = newKeys or (1 shl (cell - 'a'))
            }
            if (cell in 'A'..'F' && (keys and (1 shl (cell - 'A'))) == 0) {
                continue
            }
            val state = Triple(nr, nc, newKeys)
            if (state !in visited) {
                visited.add(state)
                queue.add(arrayOf(nr, nc, newKeys, dist + 1))
            }
        }
    }
    return -1
};1

fun isMatch(fileName: String, pattern: String): Boolean {
    val sLen = fileName.length
    val pLen = pattern.length

    // base cases
    if (pattern == fileName || pattern == "*") return true
    if (pattern.isEmpty() || fileName.isEmpty()) return false

    // init all matrix except [0][0] element as False
    val d = Array(pLen + 1) { BooleanArray(sLen + 1) }
    d[0][0] = true

    // DP compute
    for (pIdx in 1 until pLen + 1) {
        // the current character in the pattern is '*'
        if (pattern[pIdx - 1] == '*') {
            var sIdx = 1
            // d[p_idx - 1][s_idx - 1] is a string-pattern match
            // on the previous step, i.e. one character before.
            // Find the first idx in string with the previous math.
            while (!d[pIdx - 1][sIdx - 1] && sIdx < sLen + 1) sIdx++
            // If (string) matches (pattern),
            // when (string) matches (pattern)* as well
            d[pIdx][sIdx - 1] = d[pIdx - 1][sIdx - 1]
            // If (string) matches (pattern),
            // when (string)(whatever_characters) matches (pattern)* as well
            while (sIdx < sLen + 1) d[pIdx][sIdx++] = true
        } else if (pattern[pIdx - 1] == '?') {
            for (sIdx in 1 until sLen + 1) d[pIdx][sIdx] = d[pIdx - 1][sIdx - 1]
        } else {
            for (sIdx in 1 until sLen + 1) {
                // Match is possible if there is a previous match
                // and current characters are the same
                d[pIdx][sIdx] = d[pIdx - 1][sIdx - 1] &&
                        pattern[pIdx - 1] == fileName[sIdx - 1]
            }
        }
    }
    return d[pLen][sLen]
};0

