fun largestPalindrome(): Int {
    var largestPalindrome = 0
    for (a in 999 downTo 100) {
        var b = 999
        while (b >= a) {
            val p = a * b
            if (p <= largestPalindrome) {
                break // since p is always going to be small
            }
            if (p.isPalindrome) {
                largestPalindrome = p
            }
            b--
        }
    }
    return largestPalindrome
};0

