fun crossFirewall(firewalls: Array<Firewall?>, delay: Int = 0): Pair<Int, Boolean> {
    var pos = -1 - delay
    var severity = 0
    var detected = false

    while (pos < firewalls.lastIndex) {
        pos++
        if (pos >= 0) {
            firewalls[pos]?.let {
                if (it.detected()) {
                    severity += it.severity()
                    detected = true
                }
            }
        }
        firewalls.forEach { it?.move() }
    }

    return severity to detected
};0

fun primeFactors(n: Int?): Map<Int, Int> {
    if (n == null || n <= 1) return emptyMap()

    var num = n
    val factors = mutableMapOf<Int, Int>()

    // Handle factor 2 separately
    var count = 0
    while (num % 2 == 0) {
        count += 1
        num /= 2
    }
    if (count > 0) {
        factors[2] = count
    }

    var p = 3
    while (p * p <= num) {
        count = 0
        while (num % p == 0) {
            count += 1
            num /= p
        }
        if (count > 0) {
            factors[p] = count
        }
        p += 2
    }

    if (num > 1) {
        factors[num] = factors.getOrDefault(num, 0) + 1
    }

    return factors
};1

fun minimumSwaps_(array: Array<Int>): Int {
    var result = 0
    var i = 0
    while (i < array.lastIndex) {
        if (array[i] != i + 1) {
            var j = i
            while (array[j] != i + 1) j++
            array.apply(Swap(i, j))
            result++
        }
        i++
    }
    return result
};0

fun calculateFinalGain(income: Double, taxSlab: Double, standardDeductions: Double): Double {
    // Ensure inputs are treated as Doubles (for safety if Ints are passed)
    val incomeVal = income.toDouble()
    val taxSlabVal = taxSlab.toDouble()
    val standardDeductionsVal = standardDeductions.toDouble()

    // Compute the tax amount
    val taxAmount = incomeVal * taxSlabVal / 100.0

    // Calculate final gain
    val finalGain = incomeVal - taxAmount - standardDeductionsVal

    return finalGain
};1

