fun floydsTriangle(n: Int) {
    val triangle = mutableListOf<MutableList<String>>()
    var current = 0
    for (i in 1..n) {
        val v = mutableListOf<String>()
        for (j in 0 until i) {
            current++
            v.add(current.toString())
        }
        triangle.add(v)
    }
 
    for (row in triangle) {
        val arrangedRow = row.mapIndexed { i, number ->
            val spaceLen = triangle.last()!![i].length - number.length + 1
            val spaces = " ".repeat(spaceLen)
            val paddedNumber = spaces + number
            paddedNumber
        }
        println(arrangedRow.joinToString(""))
    }
};1

