fun determineWinner(candidates: List<String>, votes: List<Int>): String? {
    if (candidates.isEmpty() || votes.isEmpty() || candidates.size != votes.size) {
        return null
    }
    val maxVotes = votes.maxOrNull() ?: return null
    for ((i, v) in votes.withIndex()) {
        if (v == maxVotes) {
            return candidates[i]
        }
    }
    return null
};1

fun difference_in_days(year1: Int, month1: Int, day1: Int, year2: Int, month2: Int, day2: Int): Int {
    // 1. Helpers
    fun is_leap(y: Int): Boolean {
        return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
    }

    val DAYS_IN_MONTH = intArrayOf(0, 31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31)

    fun valid_date(y: Int, m: Int, d: Int): Boolean {
        if (y < 1 || m < 1 || m > 12) return false
        var dim = DAYS_IN_MONTH[m]
        if (m == 2 && is_leap(y)) {
            dim = 29
        }
        return (d in 1..dim)
    }

    fun to_ordinal(yin: Int, m: Int, d: Int): Int {
        var y = yin
        y -= 1
        var days = 365 * y + y / 4 - y / 100 + y / 400
        val month_days = intArrayOf(
            31, 28 + if (is_leap(y + 1)) 1 else 0, 31, 30, 31, 30,
            31, 31, 30, 31, 30, 31
        )
        for (i in 0 until m - 1) {
            days += month_days[i]
        }
        days += d
        return days
    }

    if (!(valid_date(year1, month1, day1) && valid_date(year2, month2, day2))) {
        return -1
    }

    val ord1 = to_ordinal(year1, month1, day1)
    val ord2 = to_ordinal(year2, month2, day2)
    return kotlin.math.abs(ord2 - ord1)
};1

 
enum class Direction { UP, RIGHT, DOWN, LEFT }
 
const val WHITE = 0
const val BLACK = 1
 
fun main(args: Array<String>) {
    val width = 75
    val height = 52
    val maxSteps = 12_000
    var x = width / 2
    var y = height / 2
    val m = Array(height) { IntArray(width) }
    var dir = Direction.UP
    var i = 0
    while (i < maxSteps && x in 0 until width && y in 0 until height) {
        val turn = m[y][x] == BLACK
        val index = (dir.ordinal + if (turn) 1 else -1) and 3
        dir = Direction.values()[index]
        m[y][x] = if (m[y][x] == BLACK) WHITE else BLACK
        when (dir) {
             Direction.UP    -> y--
             Direction.RIGHT -> x--
             Direction.DOWN  -> y++
             Direction.LEFT  -> x++
        }
        i++
    }
    for (j in 0 until height) {
        for (k in 0 until width) print(if(m[j][k] == WHITE) '.' else '#')
        println()
    }
};0

import java.math.BigInteger
 
fun dList(n: Int): List<List<Int>> {
    val a = IntArray(n)
    for (i in 0 until n) {
        a[i] = i
    }
    val r = mutableListOf<List<Int>>()
    fun recurse(last: Int) {
        if (last == 0) {
            for (j in 0 until n) {
                if (a[j] == j) {
                    return
                }
            }
            r.add(a.toList())
            return
        }
        for (i in last downTo 0) {
            val tmp = a[i]
            a[i] = a[last]
            a[last] = tmp
            recurse(last - 1)
            a[last] = a[i]
            a[i] = tmp
        }
    }
    recurse(n - 1)
    return r
}
 
fun subFact(n: Int): BigInteger {
    if (n == 0) {
        return BigInteger.ONE
    } else if (n == 1) {
        return BigInteger.ZERO
    }
    var d0 = BigInteger.ONE
    var d1 = BigInteger.ZERO
    var f = BigInteger.ZERO
    for (i in 1 until n) {
        d0 = d1
        d1 = f.multiply(i.toBigInteger()).add(d0).multiply(d1)
    }
    return d1
}
 
fun main(args: Array<String>) {
