fun farey(n: Int) {
    data class frac(val d: Int, val n: Int)
    var f1 = frac(0, 1)
    var f2 = frac(1, n)
    var t: frac
    var k: Int
    println("${f1.d}/${f1.n} ${f2.d}/${f2.n}")
    while (f2.n > 1) {
        k = (n + f1.n) / f2.n
        t = f1
        f1 = f2
        f2 = frac(f2.d * k - t.d, f2.n * k - t.n)
        print("${f2.d}/${f2.n} ")
    }
    println()
}
 
fun farey_len(n: Int): Long {
    var len = n.toLong() * (n + 3) / 2
    var p = 2
    var q = 0
    while (p <= n) {
        q = n / (n / p) + 1
        len -= farey_len(n / p) * (q - p)
        p = q
    }
    return len
}
 
fun main() {
    for (n in 1..11) {
        print("$n: ")
        farey(n)
    }
    for (n in 100..1000 step 100)
        println("$n: ${farey_len(n)} items")
    val n = 10000000
    println("\n$n: ${farey_len(n)} items")
};1

fun executeLambda(includePaths: List<String>, lambdaFunctionName: String): String {
    // Sanity-check: both parameters must be provided with correct types.
    if (includePaths !is List<*> || lambdaFunctionName !is String) {
        throw IllegalArgumentException("Invalid arguments: 'include_paths' must be list/tuple and 'lambda_function_name' must be a string.")
    }

    // Determine accessibility: the function is executable if ANY allowed path is
    // a substring of the provided lambda function name.
    for (path in includePaths) {
        if (path.isNotEmpty() && lambdaFunctionName.contains(path)) {
            return "Executing lambda function: $lambdaFunctionName"
        }
    }

    // If none of the include paths match, return the error message.
    return "Error: Lambda function '$lambdaFunctionName' is not accessible from the configured include paths."
};1

import java.util.*
class Automata {
    var cells: BitSet = BitSet(MAX_CELLS)
    var ncells: BitSet = BitSet(MAX_CELLS)
    val MAX_CELLS = 19
    fun run() {
        cells = BitSet(MAX_CELLS)
        ncells = BitSet(MAX_CELLS)
        while (true) {
            println("What Rule do you want to visualize")
            doRule(readLine()!!.toInt())
            println("Press any key to continue...")
            readLine()
        }
    }
    fun getCells(index: Int): Byte {
        var b: Byte
        var i1 = index - 1
        var i2 = index
        var i3 = index + 1
        if (i1 < 0) i1 = MAX_CELLS - 1
        if (i3 >= MAX_CELLS) i3 -= MAX_CELLS
        b = (4 * cells[i1].toInt() + 2 * cells[i2].toInt() + cells[i3].toInt()).toByte()
        return b
    }
    fun getBase2(i: Int): String {
        var s = Integer.toString(i, 2)
        while (s.length < 8) {
            s = "0" + s
        }
        return s
    }
    fun doRule(rule: Int) {
        println("Rule: " + rule + "\n----------\n")
        cells.set(MAX_CELLS / 2, true)
        for (gen in 0..50) {
            print(String.format("%4d", gen) + ": ")
            for (b in cells) {
                print(if (b) "#" else ".")
            }
            println("")
            var i = 0
            while (true) {
                val b = getCells(i)
                ncells[i] = '1' == getBase2(rule)[7 - b]
                if (++i == MAX_CELLS) break
            }
            i = 0
            for (b in ncells) {
                cells[i++] = b
            }
        }
        println("")
    }
}
fun main(args: Array<String>) {
    val t = Automata()
    t.run()
};1

