class ContinousKnapsackForRobber {
    private val tolerance = 0.0005
 
    init {
        val cok = ContinuousKnapsack(15.0) // 15 kg
 
        // making the list of items that you want to bring
        cok.add("beef", 3.8, 36) // marhahús
        cok.add("pork", 5.4, 43) // disznóhús
        cok.add("ham", 3.6, 90) // sonka
        cok.add("greaves", 2.4, 45) // tepertő
        cok.add("flitch", 4.0, 30) // oldalas
        cok.add("brawn", 2.5, 56) // disznósajt
        cok.add("welt", 3.7, 67) // hurka
        cok.add("salami", 3.0, 95) // szalámi
        cok.add("sausage", 5.9, 98) // kolbász
 
        // calculate the solution:
        val itemList = cok.calcSolution()
 
        // write out the solution in the standard output
        if (cok.isCalculated) {
            val nf = NumberFormat.getInstance()
 
            println("Maximal weight           = " + nf.format(cok.maxWeight) + " kg")
            println("Total weight of solution = " + nf.format(cok.solutionWeight) + " kg")
            println("Total value (profit)     = " + nf.format(cok.profit))
            println()
            println("You can carry the following materials " + "in the knapsack:")
            for (item in itemList) {
                if (item.inKnapsack > tolerance) {
                    println(
                        String.format(
                            "%1$-10s %2$-15s %3$-15s \n",
                            nf.format(item.inKnapsack) + " kg ",
                            item.name,
                            "(value = " + nf.format(item.inKnapsack * (item.value / item.weight)) + ")"
                        )
                    )
                }
            }
        } else {
            println(
                "The problem is not solved. " +
                        "Maybe you gave wrong data."
            )
        }
 
    }
 
    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            ContinousKnapsackForRobber()
        }
    }
};1

