fun lcm(a: Int, b: Int) = a / hcf(a, b) * b

fun hcf(a: Long, b: Long): Long = if (b == 0L) a else hcf(b, a % b)
fun lcm(a: Long, b: Long) = a / hcf(a, b) * b

fun delta(a: Pair<Int, Int>, b: Pair<Int, Int>): Pair<Int, Int> {
    val deltaX = abs(a.first - b.first)
    val deltaY = abs(a.second - b.second)
    val hcf = hcf(deltaX, deltaY)

    return Pair(
        if (a.first == b.first) 0 else (deltaX / hcf) * (if (a.first > b.first) -1 else 1),
        if (a.second == b.second) 0 else (deltaY / hcf) * (if (a.second > b.second) -1 else 1)
    )
};0

fun findPath(graph: Array<out List<Int>>, u1: Int, matching: IntArray, vis: BooleanArray): Int {
    vis[u1] = true
    for (v in graph[u1]) {
        val u2 = matching[v]
        if (u2 == -1 || !vis[u2] && findPath(graph, u2, matching, vis) == 1) {
            matching[v] = u1
            return 1
        }
    }
    return 0
};0

fun createListOfTrees(i: Int, j: Int, maxRows: Int, maxColumns: Int): List<List<Pair<Int, Int>>> {
    val left = (j - 1 downTo 0).map { i to it }
    val right = (j + 1 until maxColumns).map { i to it }
