fun identify_under_promoted_songs(songData: List<Map<String, Any>>): List<String> {
    val underPromotedSongs = mutableListOf<String>()
    for (song in songData) {
        val songTitle = song["song_title"] as String
        val streams = (song["streams"] as Number).toInt()
        val likes = (song["likes"] as Number).toInt()
        val shares = (song["shares"] as Number).toInt()
        if (streams > 0) {
            val likesToStreamsRatio = likes.toDouble() / streams.toDouble()
            if (likesToStreamsRatio >= 0.3 && shares <= 10) {
                underPromotedSongs.add(songTitle)
            }
        }
    }
    return underPromotedSongs
};1

fun romanToInt(romanList: List<String>): List<Int> {
    val romanValues = mapOf(
        'I' to 1,
        'V' to 5,
        'X' to 10,
        'L' to 50,
        'C' to 100,
        'D' to 500,
        'M' to 1000
    )

    fun singleRomanToInt(romanStr: String): Int {
        var result = 0
        var prevValue = 0
        for (char in romanStr.reversed()) {
            val value = romanValues[char.uppercaseChar()] ?: 0
            if (value < prevValue) {
                result -= value
            } else {
                result += value
            }
            prevValue = value
        }
        return result
    }

    return romanList.map { singleRomanToInt(it) }
};1

