// Recursive
fun factorialRecursive(n: Int): Int {
    return if (n == 0) 1 else n * factorialRecursive(n - 1)
}
 
// Tail-recursive
fun factorialTailRecursive(n: Int, prod: Int = 1): Int {
    return if (n == 0) prod else factorialTailRecursive(n - 1, prod * n)
}
 
// Iterative with Range#each
fun factorialIterative(n: Int): Int {
    var n = n
    for (i in 2 until n) {
        n *= i
    }
    return if (n == 0) 1 else n
}
 
// Iterative with Range#inject
fun factorialInject(n: Int): Int {
    return (1..n).inject(1) { prod, i -> prod * i }
}
 
// Iterative with Range#reduce, requires Ruby 1.8.7
fun factorialReduce(n: Int): Int {
    return (2..n).reduce(1, { prod, i -> prod * i })
}
 
fun main(args: Array<String>) {
    val n = 400
    val m = 10000
    val recursive = { factorialRecursive(n) }
    val tailRecursive = { factorialTailRecursive(n) }
    val iterative = { factorialIterative(n) }
    val inject = { factorialInject(n) }
    val reduce = { factorialReduce(n) }
    val recursiveTime = measureTimeMillis(recursive)
    val tailRecursiveTime = measureTimeMillis(tailRecursive)
    val iterativeTime = measureTimeMillis(iterative)
    val injectTime = measureTimeMillis(inject)
    val reduceTime = measureTimeMillis(reduce)
    println("recursive: $recursiveTime")
    println("tail recursive: $tailRecursiveTime")
    println("iterative: $iterativeTime")
    println("inject: $injectTime")
    println("reduce: $reduceTime")
}
 
