fun binarySearch(a: Array<Double>, value: Double, low: Int, high: Int): Int {
    if (high < low) {
        return -1
    }
    val mid = (low + high) / 2
    return if (a[mid] > value) {
        binarySearch(a, value, low, mid - 1)
    } else if (a[mid] < value) {
        binarySearch(a, value, mid + 1, high)
    } else {
        mid
    }
};1

fun convert_temperature(value: Any?, unit: String?): Double? {
    // Validate unit
    if (unit == null || (unit.uppercase() != "C" && unit.uppercase() != "F")) {
        return null
    }

    // Validate and coerce numeric value
    val numericValue = when (value) {
        is Number -> value.toDouble()
        is String -> value.toDoubleOrNull()
        else -> null
    } ?: return null

    // Absolute zero limits
    val ABS_ZERO_C = -273.15
    val ABS_ZERO_F = -459.67

    // Range check based on unit
    return when (unit.uppercase()) {
        "C" -> if (numericValue < ABS_ZERO_C) null else numericValue * 9 / 5 + 32
        "F" -> if (numericValue < ABS_ZERO_F) null else (numericValue - 32) * 5 / 9
        else -> null
    }
};1

fun getitem(s: String, depth: Int = 0): Pair<List<String>, String> {
    var out = listOf("")
    var s = s
    while (s.isNotEmpty()) {
        val c = s[0]
        if (depth > 0 && (c == ',' || c == '}')) {
            break
        }
        if (c == '{' && getgroup(s.substring(1), depth + 1)!= null) {
            val x = getgroup(s.substring(1), depth + 1)
            out = out.flatMap { a -> x!!.first.map { b -> a + b } }
            s = x.second
        } else {
            if (c == '\\' && s.length > 1) {
                s = s.substring(1)
                c = s[0] + c
            }
            out = out.map { a -> a + c }
            s = s.substring(1)
        }
    }
    return Pair(out, s)
}
 
fun getgroup(s: String, depth: Int): Pair<List<String>, String>? {
    var out = listOf("")
    var comma = false
    var s = s
    while (s.isNotEmpty()) {
        val g = getitem(s, depth)
        if (s.isEmpty()) {
            break
        }
        out += g.first
        when (s[0]) {
            '}' -> return if (comma) Pair(out, s.substring(1)) else Pair(out.map { a -> "{${a}}" }, s.substring(1))
            ',' -> {
                comma = true
                s = s.substring(1)
            }
        }
    }
    return null
}
 
