import java.util.*
 
class last_letter_first_letter {
    var max_path_length: Long = 0
    var max_path_length_count: Long = 0
    var max_path_example: MutableList<String> = mutableListOf()
 
    fun search(names: MutableList<String>, offset: Long) {
        if (offset > max_path_length) {
            max_path_length = offset
            max_path_length_count = 1
            max_path_example = names.subList(0, offset.toInt())
        } else if (offset == max_path_length) {
            ++max_path_length_count
        }
        var last_letter = names[offset.toInt() - 1].last()
        for (i in offset until names.size.toLong()) {
            if (names[i.toInt()][0] == last_letter) {
                Collections.swap(names, i.toInt(), offset.toInt())
                search(names, offset + 1)
                Collections.swap(names, i.toInt(), offset.toInt())
            }
        }
    }
 
    fun find_longest_chain(names: MutableList<String>) {
        max_path_length = 0
        max_path_length_count = 0
        max_path_example.clear()
        for (i in 0 until names.size) {
            Collections.swap(names, i, 0)
            search(names, 1)
            Collections.swap(names, i, 0)
        }
    }
}
 
