class TruthTable(vararg val symbols: String) {
    private val variables: List<String>
    private val symbols: Array<String>
 
    /**
     * Constructs a truth table for the symbols in an expression.
     */
    init {
        val variables = LinkedHashSet<String>()
 
        for (symbol in symbols) {
            if (!operators.containsKey(symbol)) {
                variables.add(symbol)
            }
        }
        this.variables = ArrayList(variables)
        this.symbols = symbols
    }
 
    fun toString(): String {
        val result = StringBuilder()
 
        for (variable in variables) {
            result.append(variable).append(' ')
        }
        result.append(' ')
        for (symbol in symbols) {
            result.append(symbol).append(' ')
        }
        result.append('\n')
        for (values in enumerate(variables.size)) {
            val i = variables.iterator()
 
            for (value in values) {
                result.append(String.format("%-" + i.next().length + "c ", if (value) 'T' else 'F'))
            }
            result.append(' ')
               .append(if (evaluate(values)) 'T' else 'F')
               .append('\n')
        }
 
        return result.toString()
    }
 
    /**
     * Recursively generates T/F values
     */
    fun enumerate(size: Int): List<List<Boolean>> {
        if (1 == size) {
            return listOf(listOf(false), listOf(true))
        }
 
        return ArrayList<List<Boolean>>().apply {
            for (head in enumerate(size - 1)) {
                add(ArrayList(head).apply { add(false) })
                add(ArrayList(head).apply { add(true) })
            }
        }
    }
 
    /**
     * Evaluates the expression for a set of values.
     */
    fun evaluate(enumeration: List<Boolean>): Boolean {
        val i = enumeration.iterator()
        val values = HashMap<String, Boolean>()
        val stack = Stack<Boolean>()
 
        variables.forEach { v -> values[v] = i.next() }
        for (symbol in symbols) {
            val op = operators[symbol]
 
            // Reverse Polish notation makes this bit easy
            stack.push(if (op == null) values[symbol] else op.evaluate(stack))
        }
        return stack.pop()
    }
 
    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            println(TruthTable(*args))
        };1

