fun partitions(args: List<Int>) {
  val sum = args.stream().mapToInt { i -> i }.sum()
  val nums = IntStream.range(1, sum + 1).toArray()
  val permutations = permutations(nums)
  for (permutation in permutations) {
    var totalIndex = 0
    val parts = ArrayList<List<Int>>()
    for (a in args) {
      val part = ArrayList<Int>()
      var cont = true
      for (j in 0 until a) {
        for (p in part) {
          if (permutation[totalIndex] < p) {
            cont = false
            break
          }
        }
        if (cont) {
          part.add(permutation[totalIndex])
          totalIndex++
        }
      }
      if (part.size!= a) {
        break
      }
      parts.add(part)
    }
    if (parts.size == args.size) {
      print("(")
      for (p in parts) {
        print("{ ")
        for (e in p) {
          print(e)
          print(" ")
        }
        print("},")
      }
      println("),")
    }
  }
}
 
fun <T> permutations(elements: Array<T>): List<Array<T>> {
  val result = ArrayList<Array<T>>()
  val c = elements.clone()
  do {
    result.add(c.clone())
  } while (nextPermutation(c))
  return result
}
 
fun <T> nextPermutation(elements: Array<T>): Boolean {
  var i = elements.size - 2
  while (i >= 0 && elements[i] >= elements[i + 1]) {
    i--
  }
  if (i < 0) {
    return false
  }
  var j = elements.size - 1
  while (elements[j] <= elements[i]) {
    j--
  }
  val temp = elements[i]
  elements[i] = elements[j]
  elements[j] = temp
  j = elements.size - 1
  while (i < j) {
    val temp2 = elements[i + 1]
    elements[i + 1] = elements[j]
    elements[j] = temp2
    i++
    j--
  }
  return true
}
 
fun main(args: Array<String>) {
  val args = Arrays.asList(2, 0, 2)
  partitions(args)
};1

