fun multiplicativeDigitalRoot(n: Long): LongArray {
    var mp = 0
    var mdr = n
    while (mdr > 9) {
        var m = mdr
        var total = 1L
        while (m > 0) {
            total *= m % 10
            m /= 10
        }
        mdr = total
        mp++
    }
    return longArrayOf(n, mdr, mp)
};1

