fun gcd(a: Long, b: Long): Long {
    var aa = a
    var bb = b
    while (bb != 0L) {
        val temp = bb
        bb = aa % bb
        aa = temp
    }
    return aa
}

fun minimumKForLcm(a: Int, b: Int): Int {
    val d = abs(a - b).toLong()
    if (d == 0L) {
        return 0
    }
    val divisors = mutableSetOf<Long>()
    val sqrtD = sqrt(d.toDouble()).toLong()
    for (i in 1..sqrtD) {
        if (d % i == 0L) {
            divisors.add(i)
            divisors.add(d / i)
        }
    }
    var minLcm = Long.MAX_VALUE
    var bestK = Long.MAX_VALUE
    for (g in divisors) {
        val remainder = a.toLong() % g
        val k = (g - remainder) % g
        val x = a.toLong() + k
        val y = b.toLong() + k
        val currentLcm = (x * y) / gcd(x, y)
        if (currentLcm < minLcm) {
            minLcm = currentLcm
            bestK = k
        } else if (currentLcm == minLcm) {
            if (k < bestK) {
                bestK = k
            }
        }
    }
    return bestK.toInt()
};1

 
