fun check_consecutive(nums: List<Int>): Boolean {
    // Condition 1: empty list
    if (nums.isEmpty()) {
        return false
    }
    // Condition 2: single element
    if (nums.size == 1) {
        return true
    }
    // Check consecutive ascending order
    for (i in 0 until nums.size - 1) {
        if (nums[i + 1] - nums[i] != 1) {
            return false
        }
    }
    return true
};1

 
