fun decimalToBinary(n: Int): String {
    /**
     * Recursively converts a decimal integer to its binary representation as a string.
     *
     * @param n The decimal integer to convert.
     * @return Binary representation of `n` without leading zeros. If `n` is 0,
     * the function returns the string "0". Negative numbers are handled
     * by prefixing the result with a minus sign.
     */
    // Handle the special case where n is 0.
    if (n == 0) {
        return "0"
    }

    // Handle negative numbers by converting the absolute value
    // and adding a minus sign in front.
    if (n < 0) {
        return "-" + decimalToBinary(-n)
    }

    // Base case: for 1 or 0 (handled above), simply return "1".
    if (n < 2) {
        return n.toString()
    }

    // Recursive step: convert the quotient and append the remainder.
    return decimalToBinary(n / 2) + (n % 2).toString()
};1

