fun Long.toSNAFU(): String {
    val base = listOf('0', '1', '2', '=', '-')
    val digits = listOf(0, 1, 2, -2, -1)
    val sb = StringBuilder()
    var nb = this

    while (nb != 0L) {
        val rest = (nb % 5).toInt()
        sb.append(base[rest])
        nb = (nb - digits[rest]) / 5L
    }
    return sb.toString().reversed()
};0

