class ListNode(var `val`: Int = 0, var next: ListNode? = null)

fun groupNodes(head: ListNode?, threshold: Int): ListNode? {
    val greaterDummy = ListNode(0)
    val equalDummy = ListNode(0)
    val lessDummy = ListNode(0)
    var greaterTail = greaterDummy
    var equalTail = equalDummy
    var lessTail = lessDummy

    var current = head
    while (current != null) {
        val nxt = current.next
        if (current.`val` > threshold) {
            greaterTail.next = current
            greaterTail = greaterTail.next!!
        } else if (current.`val` == threshold) {
            equalTail.next = current
            equalTail = equalTail.next!!
        } else {
            lessTail.next = current
            lessTail = lessTail.next!!
        }
        current.next = null
        current = nxt
    }
    greaterTail.next = equalDummy.next
    equalTail.next = lessDummy.next
    return greaterDummy.next ?: (equalDummy.next ?: lessDummy.next)
};1

