fun IntGrid.getOutgoing2(node: Node): Collection<Edge<Node, Unit?>> {
    val edges = ArrayList<Edge<Node, Unit?>>(3)
    for (i in 0..3) {
        val dir = Direction(i)
        if (dir == -node.dir) continue
        if (node.dirCount in 1..3 && dir != node.dir) continue
        if (node.dirCount >= 10 && dir == node.dir) continue
        var step = 1
        if (node.dir == dir && node.dirCount in 1..3)
            step = 4 - node.dirCount
        else if (dir != node.dir)
            step = 4
        while (!contains(node.posX + dir.x * step, node.posY + dir.y * step)) step--
        if (step <= 0) continue
        var posX = node.posX
        var posY = node.posY
        var loss = 0
        repeat(step) {
            posX += dir.x
            posY += dir.y
            loss += this[posX, posY]
        }
        edges.add(Edge(node, Node(posX, posY, dir, if (dir == node.dir) node.dirCount + step else step), loss, Unit))
    }
    return edges
};0

 
import java.math.BigDecimal
import java.math.MathContext
 
val mc = MathContext(256)
 
fun gcd(a: Long, b: Long): Long = if (b == 0L) a else gcd(b, a % b)
 
class Frac : Comparable<Frac> {
    val num: Long
    val denom: Long
 
    companion object {
        val ZERO = Frac(0, 1)
        val ONE  = Frac(1, 1)
    }
 
    constructor(n: Long, d: Long) {
        require(d != 0L)
        var nn = n
        var dd = d
        if (nn == 0L) {
            dd = 1
        }
        else if (dd < 0) {
            nn = -nn
            dd = -dd
        }
        val g = Math.abs(gcd(nn, dd))
        if (g > 1) {
            nn /= g
            dd /= g
        }
        num = nn
        denom = dd
    }
 
    constructor(n: Int, d: Int) : this(n.toLong(), d.toLong())
 
    operator fun plus(other: Frac) =
        Frac(num * other.denom + denom * other.num, other.denom * denom)
 
    operator fun unaryMinus() = Frac(-num, denom)
 
    operator fun minus(other: Frac) = this + (-other)
 
    operator fun times(other: Frac) = Frac(this.num * other.num, this.denom * other.denom)
 
    fun abs() = if (num >= 0) this else -this
 
    fun compareTo(other: Frac): Int {
        val diff = this.toDouble() - other.toDouble()
        return when {
            diff < 0.0  -> -1
            diff > 0.0  -> +1
            else        ->  0
        }
    }
 
    fun equals(other: Any?): Boolean {
       if (other == null || other !is Frac) return false
       return this.compareTo(other) == 0
    }
 
    fun toString() = if (denom == 1L) "$num" else "$num/$denom"
 
    fun toDouble() = num.toDouble() / denom
 
    fun toBigDecimal() = BigDecimal(num).divide(BigDecimal(denom), mc)
}
 
fun bernoulli(n: Int): Frac {
    require(n >= 0)
    val a = Array(n + 1) { Frac.ZERO }
    for (m in 0..n) {
        a[m] = Frac(1, m + 1)
        for (j in m downTo 1) a[j - 1] = (a[j - 1] - a[j]) * Frac(j, 1)
    }
    return if (n != 1) a[0] else -a[0] // returns 'first' Bernoulli number
}
 
fun binomial(n: Int, k: Int): Long {
    require(n >= 0 && k >= 0 && n >= k)
    if (n == 0 || k == 0) return 1
    val num = (k + 1..n).fold(1L) { acc, i -> acc * i }
    val den = (2..n - k).fold(1L) { acc, i -> acc * i }
    return num / den
}
 
fun faulhaberTriangle(p: Int): Array<Frac> {
    val coeffs = Array(p + 1) { Frac.ZERO }
    val q = Frac(1, p + 1)
    var sign = -1
    for (j in 0..p) {
        sign *= -1
        coeffs[p - j] = q * Frac(sign, 1) * Frac(binomial(p + 1, j), 1) * bernoulli(j)
    }
    return coeffs
}
 
