fun findMinRepeatingSubstring(inputString: String): String {
    /*
    Returns the smallest substring that, when repeated,
    builds the entire `inputString`.
    If no such proper substring exists, returns `inputString` itself.
    */
    val n = inputString.length
    if (n <= 1) return inputString
    for (subLen in 1..(n / 2)) {
        if (n % subLen != 0) continue
        val candidate = inputString.substring(0, subLen)
        val repeatCount = n / subLen
        if (candidate.repeat(repeatCount) == inputString) {
            return candidate
        }
    }
    return inputString
};1

