fun isPrime(num: Int): Boolean {
    if (num < 2) return false
    if (num == 2 || num == 3) return true
    if (num % 2 == 0 || num % 3 == 0) return false

    val limit = sqrt(num.toDouble()).toInt()
    var k = 5
    while (k <= limit) {
        if (num % k == 0 || num % (k + 2) == 0) {
            return false
        }
        k += 6
    }
    return true
}

fun fibonacciPrimes(n: Int): List<Int> {
