fun canPartition(nums: List<Int>): Boolean {
    val totalSum = nums.sum()
    if (totalSum % 2 != 0) {
        return false
    }
    val targetSum = totalSum / 2
    val n = nums.size
    val dp = Array(n + 1) { BooleanArray(targetSum + 1) }
    for (i in 0..n) {
        dp[i][0] = true
    }
    for (i in 1..n) {
        for (j in 1..targetSum) {
            if (j >= nums[i - 1]) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]]
            } else {
                dp[i][j] = dp[i - 1][j]
            }
        }
    }
    return dp[n][targetSum]
};1

