fun countChangedBits(n: Int, s: String): Int {
    val originalValue = s.reversed().toInt(2)
    val newValue = (originalValue + 1) % (1 shl n)
    val newBits = newValue.toString(2).padStart(n, '0').reversed()
    var count = 0
    for (i in 0 until n) {
        if (s[i] != newBits[i]) {
            count++
        }
    }
    return count
};1

 
