class Maze(width: Int, height: Int) {
    private val DIRECTIONS = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    private val width: Int
    private val height: Int
    private val startX: Int
    private val startY: Int
    private val endX: Int
    private val endY: Int
    private val verticalWalls: Array<BooleanArray>
    private val horizontalWalls: Array<BooleanArray>
    private val path: Array<IntArray?>
    private var visited: Array<BooleanArray?>
    fun print() {
        // Special handling: print the top line.
        var line = width.times.inject("+") { str, x -> str + if (x == startX) "   +" else "---+" }
        println(line)
        // For each cell, print the right and bottom wall, if it exists.
        for (y in 0 until height) {
            line = width.times.inject("|") { str, x -> str + if (path[x][y]!= 0) " * " else "   " + if (verticalWalls[x][y]) "|" else " " }
            println(line)
            line = width.times.inject("+") { str, x -> str + if (horizontalWalls[x][y]) "---+" else "   +" }
            println(line)
        }
    }

    fun resetVisitingState() {
        visited = Array(width) { BooleanArray(height) }
    }

    fun moveValid(x: Int, y: Int): Boolean {
        return x in 0 until width && y in 0 until height &&!visited!![x][y]
    }

    fun generate() {
        resetVisitingState()
        generateVisitCell(startX, startY)
    }

    fun generateVisitCell(x: Int, y: Int) {
        // Mark cell as visited.
        visited!![x][y] = true
        // Randomly get coordinates of surrounding cells (may be outside
        // of the maze range, will be sorted out later).
        val coordinates = DIRECTIONS.shuffle().map { dx, dy -> intArrayOf(x + dx, y + dy) }
        for (newX in coordinates) {
            val newY = newX[1]
            if (!moveValid(newX, newY)) continue
            // Recurse if it was possible to connect the current and
            // the cell (this recursion is the "depth-first" part).
            connectCells(x, y, newX, newY)
            generateVisitCell(newX, newY)
        }
    }

    fun connectCells(x1: Int, y1: Int, x2: Int, y2: Int) {
        if (x1 == x2) {
            // Cells must be above each other, remove a horizontal wall.
            horizontalWalls[x1][Math.min(y1, y2)] = false
        } else {
            // Cells must be next to each other, remove a vertical wall.
            verticalWalls[Math.min(x1, x2)][y1] = false
        }
    }

    init {
        this.width = width
        this.height = height;1

 
val Boolean.I get() = if (this) 1 else 0
 
val Int.B get() = this != 0
 
class Nybble(val n3: Boolean, val n2: Boolean, val n1: Boolean, val n0: Boolean) {
    fun toInt() = n0.I + n1.I * 2 + n2.I * 4 + n3.I * 8
 
    fun toString() = "${n3.I}${n2.I}${n1.I}${n0.I}"
}
 
fun Int.toNybble(): Nybble {
    val n = BooleanArray(4)
    for (k in 0..3) n[k] = ((this shr k) and 1).B
    return Nybble(n[3], n[2], n[1], n[0])
}
 
fun xorGate(a: Boolean, b: Boolean) = (a && !b) || (!a && b)
 
fun halfAdder(a: Boolean, b: Boolean) = Pair(xorGate(a, b), a && b)
 
fun fullAdder(a: Boolean, b: Boolean, c: Boolean): Pair<Boolean, Boolean> {
    val (s1, c1) = halfAdder(c, a)
    val (s2, c2) = halfAdder(s1, b)
    return s2 to (c1 || c2)
}
 
fun fourBitAdder(a: Nybble, b: Nybble): Pair<Nybble, Int> {
    val (s0, c0) = fullAdder(a.n0, b.n0, false)
    val (s1, c1) = fullAdder(a.n1, b.n1, c0)
    val (s2, c2) = fullAdder(a.n2, b.n2, c1)
    val (s3, c3) = fullAdder(a.n3, b.n3, c2)
    return Nybble(s3, s2, s1, s0) to c3.I
}
 
const val f = "%s + %s = %d %s (%2d + %2d = %2d)"
 
fun test(i: Int, j: Int) {
    val a = i.toNybble()
    val b = j.toNybble()
    val (r, c) = fourBitAdder(a, b)
    val s = c * 16 + r.toInt()
    println(f.format(a, b, c, r, i, j, s))
}
 
