import java.io.File
import java.io.FileNotFoundException
import java.util.*
 
class Genome(var strand: String, var length: Int, var next: Genome?)
 
var genomeData: Genome? = null
var totalLength = 0
var Adenine = 0
var Cytosine = 0
var Guanine = 0
var Thymine = 0
 
fun numDigits(num: Int): Int {
    var len = 1
 
    while (num > 10) {
        num /= 10
        len++
    }
 
    return len
}
 
fun buildGenome(str: String) {
    val len = str.length
    var genomeIterator: Genome? = null
    var newGenome: Genome? = null
 
    totalLength += len
 
    for (i in 0 until len) {
        when (str[i]) {
            'A' -> Adenine++
            'T' -> Thymine++
            'C' -> Cytosine++
            'G' -> Guanine++
        }
    }
 
    if (genomeData == null) {
        genomeData = Genome(str, len, null)
    } else {
        genomeIterator = genomeData
 
        while (genomeIterator!!.next!= null) {
            genomeIterator = genomeIterator.next
        }
 
        newGenome = Genome(str, len, null)
        genomeIterator.next = newGenome
    }
}
 
fun printGenome() {
    var genomeIterator = genomeData
    var width = numDigits(totalLength)
    var len = 0
 
    println("Sequence:")
 
    while (genomeIterator!= null) {
        println("\n%*d%3s%3s".format(width + 1, len, ":", genomeIterator.strand))
        len += genomeIterator.length
 
        genomeIterator = genomeIterator.next
    }
 
    println("\n\nBase Count\n----------\n\n")
 
    println("%3c%3s%*d\n".format('A', ":", width + 1, Adenine))
    println("%3c%3s%*d\n".format('T', ":", width + 1, Thymine))
    println("%3c%3s%*d\n".format('C', ":", width + 1, Cytosine))
    println("%3c%3s%*d\n".format('G', ":", width + 1, Guanine))
    println("\n%3s%*d\n".format("Total:", width + 1, Adenine + Thymine + Cytosine + Guanine))
 
    genomeData = null
}
 
fun main(args: Array<String>) {
    if (args.size!= 1) {
        println("Usage : ${args[0]} <Gene file name>")
        return
    }
 
    val fp = try {
        File(args[0]).bufferedReader()
    } catch (e: FileNotFoundException) {
        println("File not found")
        return
    }
 
    while (true) {
        val str = fp.readLine()?: break
        buildGenome(str)
    }
 
    fp.close()
 
    printGenome()
};1

