fun countCornerRectangles(grid: Array<IntArray>): Int {
    // Counts the number of axis–aligned rectangles in the binary `grid`
    // whose four corners are 1s and whose two diagonals are entirely filled with 1s as well.
    val R = grid.size
    if (R == 0) return 0
    val C = grid[0].size

    // For every row remember the columns that contain 1s
    val rowsOnes = grid.map { row -> row.mapIndexedNotNull { c, v -> if (v != 0) c else null } }
    var ans = 0
    val G = grid

    // Iterate over all unordered pairs of rows
    for (r1 in 0 until R) {
        val colsR1 = rowsOnes[r1]
        if (colsR1.size < 2) continue // a rectangle needs at least 2 columns
        for (r2 in r1 + 1 until R) {
            val common = colsR1.filter { c -> G[r2][c] != 0 }
            val k = common.size
            if (k < 2) continue

            // Every unordered pair of such columns defines a rectangle
            for (i in 0 until k) {
                val c1 = common[i]
                for (j in i + 1 until k) {
                    val c2 = common[j]
                    val height = r2 - r1
                    val width = c2 - c1
                    val g = gcd(height, width)

                    val dr = height / g
                    val dc = width / g
                    val dcn = -dc

                    // Check main diagonal: (r1,c1) \u2192 (r2,c2)
                    var rr = r1
                    var cc = c1
                    var ok = true
                    for (step in 0..g) {
                        if (G[rr][cc] == 0) {
                            ok = false
                            break
                        }
                        rr += dr
                        cc += dc
                    }
                    if (!ok) continue

                    // Check secondary diagonal: (r1,c2) \u2192 (r2,c1)
                    rr = r1
                    cc = c2
                    for (step in 0..g) {
                        if (G[rr][cc] == 0) {
                            ok = false
                            break
                        }
                        rr += dr
                        cc += dcn
                    }
                    if (ok) ans++
                }
            }
        }
    }
    return ans
}

// Helper function for gcd (Kotlin stdlib 1.5+ has Int.gcd)
fun gcd(a: Int, b: Int): Int {
    var aa = abs(a)
    var bb = abs(b)
    while (bb != 0) {
        val temp = bb
        bb = aa % bb
        aa = temp
    }
    return aa
};1

