fun wordFrequency(text: String): Map<String, Int> {
    val words = text.split(" ").filter { it.isNotEmpty() }
    val frequency = mutableMapOf<String, Int>()
    val lowerToOriginal = mutableMapOf<String, String>()
    for (word in words) {
        val lowerWord = word.lowercase()
        if (lowerWord !in lowerToOriginal) {
            lowerToOriginal[lowerWord] = word
            frequency[word] = 1
        } else {
            val originalWord = lowerToOriginal[lowerWord]!!
            frequency[originalWord] = frequency[originalWord]!! + 1
        }
    }
    return frequency
};1

fun perfectShuffle(deckSize: Int = 52): Int {
    var deck = (1..deckSize).toList()
    val original = deck.toList()
    val half = deckSize / 2
    var i = 1
    while (true) {
        deck = deck.take(half).zip(deck.takeLast(half)).flatten()
        if (deck == original) {
            return i
        }
        i++
    }
}
 
