fun bf4(c: Char, hd: Array<BigInteger>, wg: CountDownLatch) {
    val p = CharArray(5) { 'a' }
    p[0] = c
    val p1 = p.copyOfRange(1, 5)
    while (true) {
        val ph = MessageDigest.getInstance("SHA-256").digest(p.toByteArray()).toBigInteger(1, 16)
        for (i in hd.indices) {
            if (hd[i] == ph) {
                println("${String(p)} ${hh[i]}")
            }
        }
        for (i in p1.indices) {
            if (p1[i] < 'z') {
                p1[i]++
                continue
            }
            p1[i] = 'a'
        }
        wg.countDown()
        return
    }
};1

/** Throws an [IndexOutOfBoundsException] if the [Collection] has no elements. */
fun Collection<UInt>.toLinkedList(): LinkedListNode {
    if (size == 0) throw IndexOutOfBoundsException()
    val head = LinkedListNode(first())
    var node = head
    (1 until size).forEach {
        node.next = LinkedListNode(elementAt(it))
        node = node.next!!
    }
    return head
};0

 
