fun canFormRobot(strings: List<String>): Boolean {
    if (strings.isEmpty()) {
        return true // Assuming empty list is considered a valid robot
    }
    if (strings.size != strings.toSet().size) {
        return false // All elements must be distinct
    }

    fun backtrack(index: Int, current: String): Boolean {
        if (index == strings.size) {
            return true
        }
        val s = strings[index]
        // Try adding s as is to the right
        if (backtrack(index + 1, current + s)) {
            return true
        }
        // Try adding s reversed to the left
        if (backtrack(index + 1, s.reversed() + current)) {
            return true
        }
        // Try adding s reversed to the right
        if (backtrack(index + 1, current + s.reversed())) {
            return true
        }
        // Try adding s as is to the left
        if (backtrack(index + 1, s + current)) {
            return true
        }
        return false
    }

    return backtrack(1, strings[0]) || backtrack(1, strings[0].reversed())
};1

fun logit(p: List<Double>): List<Double> {
    return p.map { val ->
        when {
            val == 0.0 -> Double.NEGATIVE_INFINITY
            val == 1.0 -> Double.POSITIVE_INFINITY
            val > 0.0 && val < 1.0 -> kotlin.math.ln(val / (1.0 - val))
            else -> 0.0
        }
    }
};1

fun insertAndSearch(pairs: List<Pair<Int, String>>, queryKeys: List<Int>): List<String?> {
    // 1. Insert phase
    val table = mutableMapOf<Int, String>()
    for ((k, v) in pairs) {
        table[k] = v  // overwrite on duplicate keys
    }
    // 2. Search phase
    return queryKeys.map { k -> table[k] }
