fun TreeNode.isSymmetric(): Boolean {
    val leftQueue = LinkedList<TreeNode?>()
    val rightQueue = LinkedList<TreeNode?>()
    leftQueue.add(left)
    rightQueue.add(right)
    while (leftQueue.isNotEmpty() && rightQueue.isNotEmpty()) {
        val l = leftQueue.removeFirst()
        val r = rightQueue.removeFirst()
        if (l?.value != r?.value) return false
        if (l != null) {
            leftQueue.add(l.left)
            leftQueue.add(l.right)
        }
        if (r != null) {
            rightQueue.add(r.right)
            rightQueue.add(r.left)
        }
    }
    return leftQueue.isEmpty() && rightQueue.isEmpty()
};0

fun simulateHeadTailMovements(inputMoves: List<String>): HashSet<Position> {
    val tailPositions = hashSetOf(Position(0, 0))
    var currentHeadPosition = Position(0, 0)
    var currentTailPosition = Position(0, 0)
    inputMoves.forEach {
        val (movement, distance) = it.toMovement()
        repeat(distance) {
            val prevHeadPosition = currentHeadPosition
            currentHeadPosition = currentHeadPosition.move(movement)
            if (currentTailPosition.isFarFrom(currentHeadPosition)) {
                currentTailPosition = prevHeadPosition
                tailPositions.add(currentTailPosition)
            }
        }
    }
    return tailPositions
};0

