fun convertYear(E: Int, Y: Int): String {
    return when (E) {
        0 -> {
            when {
                Y >= 1989 -> "H${Y - 1988}"
                Y >= 1926 -> "S${Y - 1925}"
                Y >= 1912 -> "T${Y - 1911}"
                else -> "M${Y - 1867}"
            }
        }
        1 -> (1867 + Y).toString()
        2 -> (1911 + Y).toString()
        3 -> (1925 + Y).toString()
        4 -> (1988 + Y).toString()
        else -> throw IllegalArgumentException("E must be between 0 and 4")
    }
