/**
 * The first potential issue with implementing MedianString is writing a
 * function to compute d(Pattern, Dna) = ∑ti=1 d(Pattern, Dnai),
 * the sum of distances between Pattern and each string in Dna = {Dna1, ..., Dnat}.
 */
fun distanceBetweenPatternAndStrings(pattern: String, dnaList: List<String>): Int {

    var distance = 0

    for (g in dnaList) {
        var minHammingDistance = Integer.MAX_VALUE
        for (i in 0..g.length - pattern.length) {
            val kmer = g.substring(i, i + pattern.length)
            val dist = hammingDistance(pattern, kmer)
            minHammingDistance = min(minHammingDistance, dist)
        }
        distance += minHammingDistance
    }
    return distance
};0

import java.lang.Exception
import java.lang.RuntimeException
import java.lang.StringBuilder
 
class Ant {
 
    class OutOfBoundsException(message: String) : RuntimeException(message)
 
    class Plane(val sizeX: Int, val sizeY: Int) {
        private val cells = Array(sizeY) { Array(sizeX) {'' } }
 
        fun white(px: Int, py: Int): Boolean {
            return cells[py][px] ==''
        }
 
        fun toggleColour(px: Int, py: Int) {
            cells[py][px] = if (white(px, py)) '#' else''
        }
 
        fun checkBounds(px: Int, py: Int) {
            if (px < 0 || px >= sizeX || py < 0 || py >= sizeY) {
                throw OutOfBoundsException("($sizeX, $sizeY)")
            }
        }
 
        fun toString(): String {
            val sb = StringBuilder()
            for (row in cells) {
                for (cell in row) {
                    sb.append(cell)
                }
                sb.append('\n')
            }
            return sb.toString()
        }
    }
 
    private val dirMove = arrayOf(Pair("north", Pair(0, -1)), Pair("east", Pair(1, 0)), Pair("south", Pair(0, 1)), Pair("west", Pair(-1, 0)))
    private val move = dirMove.associateBy({ it.first }, { it.second })
    private val directions = dirMove.map { it.first } // [:north, :east, :south, :west]
    private val right = directions.zip(directions.rotate()).toMap()
    private val left = right.entries.associateBy({ it.value }, { it.key })
 
    private val plane: Plane
    private var posX: Int
    private var posY: Int
    private var direction: String
 
    constructor(sizeX: Int, sizeY: Int, posX: Int = sizeX / 2, posY: Int = sizeY / 2) {
        plane = Plane(sizeX, sizeY)
        this.posX = posX
        this.posY = posY
        direction = "south"
        plane.checkBounds(posX, posY)
    }
 
    fun run(): Int {
        var moves = 0
        while (true) {
            try {
                moves++
                move()
            } catch (e: OutOfBoundsException) {
                break
            }
        }
        return moves
    }
 
    fun move() {
        plane.toggleColour(posX, posY)
        advance()
        if (plane.white(posX, posY)) {
            direction = right[direction]!!
        } else {
            direction = left[direction]!!
        }
    }
 
    fun advance() {
        val dx = move[direction]!!.first
        val dy = move[direction]!!.second
        posX += dx
        posY += dy
        plane.checkBounds(posX, posY)
    }
 
    fun position(): String {
        return "($posX, $posY)"
    }
 
