import kotlin.random.Random
 
const val OTHER_VALUES = "!\"#$%&'()*+,-./:;<=>?@[]^_{|}~"
 
fun generatePassword(length: Int): String {
    val basePassword = (0 until length).map {
        Random.nextInt(0, 127).toChar()
    }
    var toAdd = Random.nextInt(1, length)
    while (toAdd > 0) {
        val special = OTHER_VALUES.random()
        toAdd--
        basePassword[toAdd] = special
    }
    return basePassword.joinToString("")
}
 
