fun evaluatePokerHand(hand: List<String>): String {
    val ranksStr = "23456789TJQKA"
    val rankToValue = ranksStr.withIndex().associate { it.value to it.index }
    val values = hand.map { rankToValue[it[0]]!! }.sorted()
    val suits = hand.map { it[1] }
    val valueCounts = values.groupingBy { it }.eachCount()
    val counts = valueCounts.values.sortedDescending()
    val uniqueValues = values.toSet().sorted()
    val isFlush = suits.toSet().size == 1
    var isStraight = false
    // Check for normal straight
    if (uniqueValues.size == 5 && uniqueValues[4] - uniqueValues[0] == 4) {
        isStraight = true
    }
    // Check for Ace-low straight (A,2,3,4,5)
    if (values.toSet() == setOf(0, 1, 2, 3, 12)) {
        isStraight = true
        // values = listOf(0, 1, 2, 3, 12) // not needed further
    }
    if (isFlush && isStraight) {
        // Royal Flush (10, J, Q, K, A)
        if (values.toSet() == setOf(8, 9, 10, 11, 12)) {
            return "Royal Flush"
        }
        return "Straight Flush"
    }
    if (counts[0] == 4) {
        return "Four of a Kind"
    }
    if (counts[0] == 3 && counts[1] == 2) {
        return "Full House"
    }
    if (isFlush) {
        return "Flush"
    }
    if (isStraight) {
        return "Straight"
    }
    if (counts[0] == 3) {
        return "Three of a Kind"
    }
    if (counts[0] == 2 && counts[1] == 2) {
        return "Two Pair"
    }
    if (counts[0] == 2) {
        return "Pair"
    }
    return "High Card"
};1

fun createOrderBook(n: Int, s: Int, orders: List<Triple<String, Int, Int>>): List<String> {
    val sells = mutableMapOf<Int, Int>()
    val buys = mutableMapOf<Int, Int>()
    for ((d, p, q) in orders) {
        if (d == "S") {
            sells[p] = sells.getOrDefault(p, 0) + q
        } else {
            buys[p] = buys.getOrDefault(p, 0) + q
        }
    }
    val sortedSells = sells.entries.sortedBy { it.key }
    val topSells = sortedSells.take(s)
    val topSellsSorted = topSells.reversed()
    val sortedBuys = buys.entries.sortedByDescending { it.key }
    val topBuys = sortedBuys.take(s)
    val result = mutableListOf<String>()
    for ((price, vol) in topSellsSorted) {
        result.add("S $price $vol")
    }
    for ((price, vol) in topBuys) {
        result.add("B $price $vol")
    }
    return result
};1

