fun findMaxIndex(a: Array<Int>, from: Int): Int {
    var i = from
    var max = Int.MIN_VALUE
    var maxIndex = i
    while (i >= 0) {
        if (a[i] >= max) {
            max = a[i]
            maxIndex = i
        }
        i--
    }
    return maxIndex
