fun showLU(a: Array<DoubleArray>) {
    println("\na")
    print(a)
    val l = lu(a)[0]
    println("l")
    print(l)
    val u = lu(a)[1]
    println("u")
    print(u)
    val p = lu(a)[2]
    println("p")
    print(p)
}
 
fun lu(a: Array<DoubleArray>): Array<Array<DoubleArray>> {
    val l = zero(a.size)
    val u = zero(a.size)
    val p = pivotize(a)
    val a = mul(p, a)
    for (j in 0..a.size - 1) {
        l[j][j] = 1.0
        for (i in 0..j) {
            var sum = 0.0
            for (k in 0..i - 1) {
                sum += u[k][j] * l[i][k]
            }
            u[i][j] = a[i][j] - sum
        }
        for (i in j..a.size - 1) {
            var sum = 0.0
            for (k in 0..j - 1) {
                sum += u[k][j] * l[i][k]
            }
            l[i][j] = (a[i][j] - sum) / u[j][j]
        }
    }
    return arrayOf(l, u, p)
}
 
fun pivotize(a: Array<DoubleArray>): Array<DoubleArray> {
    val p = eye(a.size)
    for (j in 0..a.size - 1) {
        var max = a[j][j]
        var row = j
        for (i in j..a.size - 1) {
            if (a[i][j] > max) {
                max = a[i][j]
                row = i
            }
        }
        if (j!= row) {
            // swap rows
            val temp = p[j]
            p[j] = p[row]
            p[row] = temp
        }
    }
    return p
}
 
fun mul(m1: Array<DoubleArray>, m2: Array<DoubleArray>): Array<DoubleArray> {
    val r = zero(m1.size)
    for (i in 0..m1.size - 1) {
        for (j in 0..m2.size - 1) {
            for (k in 0..m1.size - 1) {
                r[i][j] += m1[i][k] * m2[k][j]
            }
        }
    }
    return r
}
 
fun zero(n: Int): Array<DoubleArray> {
    val r = Array(n, { DoubleArray(n) })
    return r
}
 
fun eye(n: Int): Array<DoubleArray> {
    val r = zero(n)
    for (i in 0..n - 1) {
        r[i][i] = 1.0
    }
    return r
}
 
fun print(m: Array<DoubleArray>) {
    for (r in m) {
        for (e in r) {
            print(String.format("%9.5f", e))
        }
        println()
    }
