import kotlin.math.log2
 
fun hist(source: String): Pair<Int, Map<Char, Int>> {
    var hist = mutableMapOf<Char, Int>()
    var l = 0
    for (e in source) {
        l++
        if (e!in hist) {
            hist[e] = 0
        }
        hist[e] = hist[e]!! + 1
    }
    return Pair(l, hist)
}
 
fun entropy(hist: Map<Char, Int>, l: Int): Double {
    var elist = mutableListOf<Double>()
    for (v in hist.values) {
        val c = v / l.toDouble()
        elist.add(-c * log2(c))
    }
    return elist.sum()
}
 
fun printHist(h: Map<Char, Int>) {
    val flip = { (k, v) -> Pair(v, k) }
    val h = h.toList().sortedBy(flip).toMap()
    println("Sym\thi\tfi\tInf")
    for ((k, v) in h) {
        println("%s\t%f\t%f\t%f".format(k, v, v / l, -log2(v / l)))
    }
}
 
