fun PuzzleInput.part1v1(): Any {
    val earliest = lines[0].toInt()
    val buses = lines[1].split(",").stream().filter { it != "x" }.mapToInt(String::toInt).toArray()
    var pair = Pair(0, Integer.MAX_VALUE)
    for (bus in buses) {
        if (earliest % bus == 0) return 0
        val dist = bus * (earliest / bus + 1) - earliest
        if (dist < pair.second) pair = Pair(bus, dist)
    }
    return pair.first * pair.second
};0

fun solution(): Int {
    var answer = 0
    val mc = MathContext(105, RoundingMode.HALF_UP)
    for (i in 2..99) {
        val number = BigDecimal(i)
        val sqrtNumber = sqrt(number, mc)
        val sqrtStr = sqrtNumber.toPlainString()
        if (sqrtStr.contains(".")) {
            answer += sqrtStr[0].digitToInt()
            val decimalDigits = sqrtStr.substringAfter(".").padEnd(100, '0').substring(0, 100)
            answer += decimalDigits.sumOf { it.digitToInt() }
        }
    }
    return answer
}

// Compute sqrt with Newton-Raphson method for BigDecimal
def sqrt(value: BigDecimal, mc: MathContext): BigDecimal {
    if (value < BigDecimal.ZERO) throw IllegalArgumentException("Negative argument.")
    if (value == BigDecimal.ZERO) return BigDecimal.ZERO
    var x = BigDecimal(Math.sqrt(value.toDouble()))
    var prevX = BigDecimal.ZERO
    val two = BigDecimal(2)
    val scale = mc.precision + 10
    while (x.subtract(prevX).abs() > BigDecimal.ONE.movePointLeft(scale)) {
        prevX = x
        x = value.divide(x, scale, RoundingMode.HALF_UP).add(x).divide(two, scale, RoundingMode.HALF_UP)
    }
    return x.round(mc)
};1

import kotlin.math.pow
 
// Only valid for n > 0 && base >= 2
fun mult(n: Long, base: Int): Long {
    var mult = 1L
    for (mult = 1; mult > 0 && n > 0; n /= base) {
        mult *= n % base
    }
    return mult
}
 
// Only valid for n >= 0 && base >= 2
fun MultDigitalRoot(n: Long, base: Int): Pair<Int, Int> {
    var m = n
    var mp = 0
    while (m >= base) {
        m = mult(m, base)
        mp++
    }
    return Pair(mp, m.toInt())
}
 
fun main() {
    val base = 10
    val size = 5
 
    val testFmt = "%20s %3s %3s\n"
    println(String.format(testFmt, "Number", "MDR", "MP"))
    for (n in arrayOf(
        123321, 7739, 893, 899998,
        18446743999999999999,
        // From http://mathworld.wolfram.com/MultiplicativePersistence.html
        3778888999, 277777788888899
    )) {
        val (mp, mdr) = MultDigitalRoot(n, base)
        println(String.format(testFmt, n, mdr, mp))
