    for (cnt in size * base downTo 1; cnt > 0; n++) {
        val (mp, mdr) = MultDigitalRoot(n, base)
        if (list[mdr].size < size) {
            list[mdr].add(n)
            cnt--
        }
    }
    val tableFmt = "%3s: %s\n"
