fun lastSundayOfEachMonths(year: Int): List<String> {
    val lastDay = intArrayOf(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
    val sundays = mutableListOf<String>()
    var date: Date
    var month: Int
    if (year % 4 == 0 && (year % 100!= 0 || year % 400 == 0)) {
        lastDay[2] = 29
    }
    for (date = Date(), month = 0; month < 12; month++) {
        date.setFullYear(year, month, lastDay[month])
        date.setDate(date.getDate() - date.getDay())
        sundays.add(date.toISOString().substring(0, 10))
    }
    return sundays
}
 
