class ListNode(var `val`: Int = 0, var next: ListNode? = null)

fun mergeFiveLists(list1: ListNode?, list2: ListNode?, list3: ListNode?, list4: ListNode?, list5: ListNode?): ListNode? {
    val heap = PriorityQueue<Triple<Int, Int, ListNode>> { a, b ->
        if (a.first != b.first) a.first - b.first else a.second - b.second
    }
    val nodes = listOf(list1, list2, list3, list4, list5)
    for (node in nodes) {
        if (node != null) {
            heap.add(Triple(node.`val`, System.identityHashCode(node), node))
        }
    }
    val mergedHead = ListNode()
    var current = mergedHead
    while (heap.isNotEmpty()) {
        val (_, _, node) = heap.poll()
        current.next = node
        current = current.next!!
        if (node.next != null) {
            heap.add(Triple(node.next!!.`val`, System.identityHashCode(node.next!!), node.next!!))
        }
    }
    current.next = null
    return mergedHead.next
};1

fun runLengthEncoding(text:String,prev:String=""):String {
