fun manageDatabaseConnection(actions: List<String>): List<String> {
    val outputs = mutableListOf<String>()
    var isOpen = false

    for (action in actions) {
        when {
            action == "open" -> {
                outputs.add("Database connection opened")
                isOpen = true
            }
            action == "close" -> {
                outputs.add("Database connection closed")
                isOpen = false
            }
            action.startsWith("execute ") -> {
                val query = action.removePrefix("execute ")
                if (isOpen) {
                    outputs.add("Executed query: $query")
                } else {
                    outputs.add("Error: Database connection is closed")
                }
            }
            else -> {
                outputs.add("Invalid action")
            }
        }
    }
    return outputs
};1

