fun randint(n: Int): Int {
    var r: Int
    var rmax = RAND_MAX / n * n
    r = Random.nextInt(rmax)
    return r / (RAND_MAX / n)
}
 
fun factorial(n: Int): Long {
    //Factorial using dynamic programming to memoize the values.
    var factorials = mutableListOf(1L, 1L, 2L)
    for (i in factorials.size..n)
        factorials.add(factorials[i - 1] * i)
    return factorials[n]
}
 
fun expected(n: Int): Double {
    var sum = 0.0
    for (i in 1..n)
        sum += factorial(n) / pow(n.toDouble(), i.toDouble()) / factorial(n - i)
    return sum
}
 
fun test(n: Int, times: Int): Int {
    var i: Int
    var count = 0
    for (i in 0 until times) {
        var x = 1
        var bits = 0
        while (!(bits and x!= 0)) {
            count++
            bits = bits or x
            x = 1 shl randint(n)
        }
    }
    return count
}
 
