data class Rational(val num: Int, val denom: Int)
 
fun vdc(n: Int, base: Int): Rational {
    var p = 0
    var q = 1
    var nn = n
    while (nn != 0) {
        p = p * base + nn % base
        q *= base
        nn /= base
    }
    val num = p
    val denom = q
    while (p != 0) {
        nn = p
        p = q % p
        q = nn
    }
    return Rational(num / q, denom / q)
}
 
