fun convert_to_24_hour_format(inputTimes: List<String>): List<String> {
    val outputTimes = mutableListOf<String>()
    for (timeStr in inputTimes) {
        val time = timeStr.substring(0, timeStr.length - 3)
        val period = timeStr.substring(timeStr.length - 2).uppercase()
        val (hoursStr, minutesStr) = time.split(":")
        var hours = hoursStr.toInt()
        val minutes = minutesStr.toInt()
        if (period == "PM" && hours != 12) {
            hours += 12
        } else if (period == "AM" && hours == 12) {
            hours = 0
        }
        outputTimes.add("%02d:%02d".format(hours, minutes))
    }
    return outputTimes
};1

