fun prepareDefinitions(defs: Map<String, String?>, prefix: String? = null): List<String> {
    val result = mutableListOf<String>()
    for ((key, value) in defs) {
        // Skip keys with null values
        if (value == null) {
            continue
        }
        // Apply prefix if given
        val fullKey = if (prefix != null) prefix + key else key
        // Handle empty-string values
        if (value == "") {
            result.add(fullKey)
        } else {
            result.add("${fullKey}=${value}")
        }
    }
    return result
};1

