fun configureAlgorithm(testNumber: Any?, testLog: Any?, testSeed: Any?): Map<String, Any> {
    // Ensure testNumber is a positive integer.
    val tNum = if (testNumber is Int && testNumber > 0) testNumber else 1

    // Ensure testLog is a boolean.
    val tLog = if (testLog is Boolean) testLog else true

    // Provide default seed if needed.
    val tSeed: Int = if (testSeed is Int) {
        testSeed
    } else {
        val today = LocalDate.now()
        today.year * 10000 + today.monthValue * 100 + today.dayOfMonth
    }

    return mapOf(
        "testNumber" to tNum,
        "testLog" to tLog,
        "testSeed" to tSeed
    )
};1

fun dutchNationalFlag() {
 
    /**
     * Return the name of the given number in this way:
     * 0 = Red
     * 1 = White
     * 2 = Blue
     * @param e
     */
    fun name(e: Int) = when (e) {
        1 -> "White"
        2 -> "Blue"
        else -> "Red"
    }
 
    /**
     * Given an array of numbers return true if each number is bigger than
     * or the same as the previous
     * @param arr
     */
    fun isSorted(arr: List<Int>) = arr.withIndex().all { (i, e) -> e >= arr.getOrNull(i - 1)?: 0 }
 
    /**
     * Generator that keeps yielding a random int between 0(inclusive) and
     * max(exclusive), up till n times, and then is done.
     * @param max
     * @param n
     */
    fun randomGen(max: Int, n: Int) = sequence {
        var i = 0
        while (i < n) {
            i += 1
            yield(Math.floor(Math.random() * max).toInt())
        }
    }
 
    /**
     * An array of random integers between 0 and 3
     * @type {[!number]}
     */
    val mixedBalls = randomGen(3, 22).toList()
 
    /**
     * Sort the given array into 3 sub-arrays and then concatenate those.
     */
    val sortedBalls = mixedBalls
       .groupBy { it }
       .map { it.value.map { it } }
       .flatten()
 
    /**
     * A verbatim implementation of the Wikipedia pseudo-code
     * @param A
     * @param mid The value of the'mid' number. In our case 1 as
     * low is 0 and high is 2
     */
    fun dutchSort(A: MutableList<Int>, mid: Int) {
        var i = 0
        var j = 0
        var n = A.size - 1
        while (j <= n) {
            if (A[j] < mid) {
                A[i] = A[j].also { A[j] = A[i] }
                i += 1
                j += 1
            } else if (A[j] > mid) {
                A[n] = A[j].also { A[j] = A[n] }
                n -= 1
            } else {
                j += 1
            }
        }
    }
 
    println("Mixed balls       : ${mixedBalls.map(::name).joinToString()}")
    println("Is sorted: ${isSorted(mixedBalls)}")
 
    println("Sorted balls      : ${sortedBalls.map(::name).joinToString()}")
    println("Is sorted: ${isSorted(sortedBalls)}")
 
    // Only do the dutch sort now as it mutates the mixedBalls array in place.
    dutchSort(mixedBalls, 1)
    println("Dutch Sorted balls: ${mixedBalls.map(::name).joinToString()}")
    println("Is sorted: ${isSorted(mixedBalls)}")
}
dutchNationalFlag();1

fun windowClickable(initial: Boolean, operations: List<String>): List<Boolean> {
    /**
     * Simulates a GUI window's 'clickable' property.
     *
     * @param initial The starting state of the 'clickable' flag.
     * @param operations A sequence of operations, each either "toggle" or "check".
     * @return A list containing the result of every "check" operation in the order they were encountered.
     * @throws IllegalArgumentException If an operation is not "toggle" or "check".
     */
    var clickableState = initial
    val checksResult = mutableListOf<Boolean>()

    for (op in operations) {
        when (op) {
            "toggle" -> clickableState = !clickableState
            "check" -> checksResult.add(clickableState)
            else -> throw IllegalArgumentException("Unsupported operation: '$op'")
        }
    }
    return checksResult
};1

fun canABecomeB(n: Int, a: MutableList<Int>, b: List<Int>): Boolean {
    // If any b[i] < a[a], return false
    if ((0..<n).any { i -> b[i] < a[i] }) {
        return false
    }

    for (g in 0..n) {
        for (i in 0..<n) {
            if (b[i] == g && a[i] < g) {
                // Find an l to the left
                var l = i
                while (l > 0 && a[l - 1] <= g && b[l - 1] >= g) {
                    l--
                }
                // Find r
                var r = i
                while (r < n - 1 && a[r + 1] <= g && b[r + 1] >= g) {
                    r++
                }
                if (!(l..r).any { j -> a[j] == g }) {
                    return false
                }
                for (j in l..r) {
                    a[j] = g
                }
            }
        }
    }
    return a == b
};0

import (
    "fmt"
    "math/big"
    "strconv"
)
 
fun main() {
    // package strconv:  the most common string to int conversion,
    // base 10 only.
    x, _ = strconv.Atoi("13")
    println(x)
 
    // ParseInt handles arbitrary bases from 2 to 36, and returns
    // a result of the requested size (64 bits shown here.)
    // If the base argument is zero the base is determined by prefix
    // as with math/big below.
    x64, _ = strconv.ParseInt("3c2", 19, 64)
    println(x64)
 
    // package fmt:  allows direct conversion from strings, standard
    // input, or from an io.Reader (file, buffer, etc) to integer types
    // for bases 2, 8, 10, and 16 or to any type that implements the
    // fmt.Scanner interface (e.g. a big.Int).
    // (Fscanf and Scanf are more common for reading from
    // an io.Reader or stdin than Sscanf for reading from strings.)
    fmt.Sscanf("1101", "%b", &x)
    println(x)
 
    fmt.Sscanf("15", "%o", &x)
    println(x)
 
    fmt.Sscanf("13", "%d", &x)
    println(x)
 
    fmt.Sscanf("d", "%x", &x)
    println(x)
 
    // package math/big:  allows conversion from string to big integer.
    // any base from 2 to 36 can be specified as second parameter.
    var z big.Int
    z.SetString("111", 3)
    println(&z)
 
    // if second parameter is 0, base is determined by prefix, if any
    z.SetString("0b1101", 0) // 0b -> base 2
    println(&z)
 
    z.SetString("015", 0) // 0 -> base 8
    println(&z)
 
    z.SetString("13", 0) // no prefix -> base 10
    println(&z)
 
    z.SetString("0xd", 0) // 0x -> base 16
    println(&z)
 
    // As mentioned, a big.Int (or any type implementing fmt.Scanner)
    // can also be use with any of the fmt scanning functions.
    fmt.Sscanf("15", "%o", &z)
    println(&z)
};1

fun calculateTotalTransactionAmount(transactionAmounts: List<Double>): Double {
    var totalAmount = 0.0
    for (amount in transactionAmounts) {
        val discountedAmount = when {
            amount < 50 -> amount
            amount in 50.0..100.0 -> amount * 0.95
            else -> amount * 0.9
        }
        totalAmount += discountedAmount
    }
    return totalAmount
};1

