fun guessingGame(secretNumber: Int, guesses: List<Int>): String {
    val MAX_CHANCES = 5
    for ((_, guess) in guesses.take(MAX_CHANCES).withIndex()) {
        if (guess == secretNumber) {
            return "Congratulations! You guessed the correct number."
        }
    }
    return "You ran out of chances"
};1

fun getUserById(users: List<Map<String, Any>>, userId: Int): Map<String, Any> {
    for (user in users) {
        val idValue = user["id"]
        if (idValue is Int && idValue == userId) {
            return user
        }
    }
    return emptyMap()
};1

fun getComplianceResults(rules: List<Pair<Int, Boolean>>, maxResultsPerPage: Int): List<Map<String, Any>> {
    // Guard-rail for non-positive page sizes
    if (maxResultsPerPage <= 0) {
        return emptyList()
    }
    val firstPageRules = rules.take(maxResultsPerPage)
    return firstPageRules.map { (ruleId, compliant) ->
        mapOf("rule_id" to ruleId, "compliant" to compliant)
    }
};1
